const React = window.React;
const { useState, useEffect, useMemo } = React;
const SYS = window.SOP_SYS; // the screen-independent rules (game/systems)

/* THE SEAT OF POWER V3 */

/* Portrait layout: the shell gives tall screens a narrow (720px) artboard.
   Components that need a different arrangement there ask TALL(). */
// Follows the page shell's decision (body.sop-portrait), so the keyboard or
// a host frame of the wrong height cannot flip the layout mid-game.
const TALL = () => {
  if (typeof window === "undefined") return false;
  const b = document.body;
  if (b && b.classList.contains("sop-portrait")) return true;
  if (b && document.getElementById("sop-stage")) return false;
  return window.innerHeight > window.innerWidth;
};

const F = { d: "'Fraunces',Georgia,serif", b: "'Plus Jakarta Sans',sans-serif", m: "'Plus Jakarta Sans',sans-serif", c: "'Plus Jakarta Sans',sans-serif" };
/* CL — the colour handles used by ~700 inline styles. The six structural
   ones are no longer fixed hexes: they read live from the stage's CSS
   custom properties, so switching to admin or private mode re-skins every
   inline-styled surface too, not just the .ds-* ones. Values are cached and
   invalidated on mode change (see setMode) so a render costs one read. */
const CL_STATIC = { red: "#cc3333", blu: "#2563eb", pur: "#6d28d9", org: "#c2410c", teal: "#0d9488", gold: "#1a6d2e" };
const CL_VARS = { bg: "--sf-bg", card: "--sf-card", bdr: "--sf-bdr", grn: "--accent", txt: "--ink", tm: "--ink-mid", td: "--ink-dim" };
const CL_FALLBACK = { bg: "#f8faf5", card: "#fff", bdr: "#d0d8c4", grn: "#008751", txt: "#1a2e05", tm: "#4a5e3a", td: "#7a8b6a" };
let _clCache = {};
window.SOP_clearColorCache = () => { _clCache = {}; };
const CL = {};
Object.keys(CL_STATIC).forEach(k => { CL[k] = CL_STATIC[k]; });
Object.keys(CL_VARS).forEach(k => {
  Object.defineProperty(CL, k, {
    enumerable: true,
    get() {
      if (_clCache[k]) return _clCache[k];
      let v = "";
      try {
        const st = document.getElementById("sop-stage");
        if (st) v = getComputedStyle(st).getPropertyValue(CL_VARS[k]).trim();
      } catch (e) {}
      return (_clCache[k] = v || CL_FALLBACK[k]);
    },
  });
});

/* Save slot. The game reads and writes window.storage.get/set, which
   nothing provided, so Save failed and Continue never appeared. Back it
   with localStorage; every access is guarded (private mode, blocked
   storage), and failures surface as rejected promises the callers catch. */
if (!window.storage) {
  window.storage = {
    get: (k) => new Promise((resolve) => {
      let v = null;
      try { v = window.localStorage.getItem(k); } catch (e) {}
      resolve(v == null ? null : { key: k, value: v });
    }),
    set: (k, v) => new Promise((resolve, reject) => {
      try { window.localStorage.setItem(k, v); resolve({ key: k, value: v }); } catch (e) { reject(e); }
    }),
  };
}

/* ─────────────────────────────────────────────────────────────────
   SAVE FORMAT
   v1 → the original blob: no version marker, no ledger, autosave
        always wrote phase:"budget".
   v2 → carries `sv`, `savedAt` and the serialised Historic Ledger,
        and stores the real phase.
   v4 → every project uses the one project model (estimate, budget, money,
        contractor); projects stuck waiting for the old procurement screen
        are converted to their real next step.
   v3 → campaign loans are a list of accepted loans (setup.gfLoans) and
        patronage favours are separate (setup.favours). Older totals are
        cleaned of the ghost amounts patronage moves added (see
        SYS.migrateCampaignLoans); the chosen adviser is kept as saved.
   migrateSave() upgrades an old save in place rather than rejecting
   it, so runs in progress survive this change.
   ───────────────────────────────────────────────────────────────── */
// Running inside a Vatar world's game player (Lagos Life): the server sets
// window.SOP_VATAR. Popups, downloads, clipboard and fullscreen are blocked
// there, so those controls are hidden.
const VATAR = typeof window !== "undefined" && !!window.SOP_VATAR;
const SAVE_VERSION = 4;
function migrateSave(d) {
  if (!d || typeof d !== "object") return d;
  if (!d.sv) {
    // v1: no ledger was ever stored, and the phase is untrustworthy.
    d.sv = 1;
    d.ledger = null;
    if (d.phase === "budget" && d.nav === "gov") d.phase = "budget"; // best we can do
    d._migratedFrom = 1;
  }
  if (d.sv < 3 && d.setup) { d.setup = window.SOP_SYS.migrateCampaignLoans(d.setup); d._migratedFrom = d._migratedFrom || d.sv; }
  // v4: projects from the old procurement model (some stuck at "Resume
  // procurement" with no screen to resume on) become actionable projects.
  if (d.sv < 4 && Array.isArray(d.projects)) { d.projects = d.projects.map(p => window.SOP_SYS.migrateOldProject(p, d.turn || 1)); d.pendingProc = null; d._migratedFrom = d._migratedFrom || d.sv; }
  d.sv = SAVE_VERSION;
  scrubRemovedContent(d);
  return renameParties(d);
}
// The parties are fictional. Saves made when they carried real names are
// converted on load: any value that is exactly an old party id becomes the new one.
const OLD_PARTY = { APC: "NRA", NDC: "YDM", ADC: "UCP", PDP: "PFP", LP: "WPN" };
function renameParties(v) {
  if (typeof v === "string") return OLD_PARTY[v] || v;
  if (Array.isArray(v)) return v.map(renameParties);
  if (v && typeof v === "object") { for (const k in v) v[k] = renameParties(v[k]); return v; }
  return v;
}
/* Removed content (4 Oct, Steve's decision): the First 100 Days /
   inauguration scenes and the budget-padding ("Budget Assembly")
   decisions. A save made before that may still carry their traces: drop
   them on load so nothing refers to a choice the player can no longer
   have made, and so a save paused in the old padding phase resumes on the
   budget instead. */
const REMOVED_LOG = /^📋 DAY \d+:|First 100 days|envelope as submitted|Padding untouched|envelope by \d+%|real-need envelope|padding proved|padding referral|constituency projects\. House delighted|Negotiated down to ₦[\d.]+B constituency|Refused Speaker's demand|Recorded conversation leaked|Speaker's constituency/i;
function scrubRemovedContent(d) {
  try {
    if (d.phase === "mda") d.phase = "budget";
    delete d.mdaEnv;
    const L = Array.isArray(d.ledger) ? d.ledger : d.ledger && Array.isArray(d.ledger.entries) ? d.ledger.entries : null;
    if (L) {
      const gone = new Set();
      L.forEach(e => {
        if (!e) return;
        if (/^DAY \d+ — /.test(e.location || "") || e.note === "First 100 days concluded" || e.kind === "budget_padding" || e.relatedEntity === "project:signature_road" || /Ring Road \(Phase 1\)/.test(e.target || "")) gone.add(e.id);
      });
      // Consequences and settlements that hang off a removed entry go too.
      L.forEach(e => {
        if (e && ((e.causedBy || []).some(id => gone.has(id)) || (e.kind === "debt_settled" && e.meta && gone.has(e.meta.settles)))) gone.add(e.id);
      });
      const kept = L.filter(e => e && !gone.has(e.id));
      if (Array.isArray(d.ledger)) d.ledger = kept; else d.ledger.entries = kept;
    }
    if (Array.isArray(d.logs)) d.logs = d.logs.filter(l => !REMOVED_LOG.test(String(l && l.tx || "")));
    if (Array.isArray(d.saMemory)) d.saMemory = d.saMemory.filter(m => !/^DAY \d+:/.test(String(m && m.txt || "")));
    if (Array.isArray(d.wikiEvents)) d.wikiEvents = d.wikiEvents.filter(w => !/Ring Road \(Phase 1\)|party-financier nomination/.test(String(w && w.txt || "")));
    if (Array.isArray(d.projects)) d.projects = d.projects.filter(p => p && p.id !== "signature_road");
    if (Array.isArray(d.procLog)) d.procLog = d.procLog.filter(x => !/Ring Road \(Phase 1\)/.test(String(x && x.txt || "")));
  } catch (e) { console.warn("[save] scrub", e); }
  return d;
}
window.SOP_migrateSave = migrateSave;
window.CL_REF = CL; window.F_REF = F;

/* ─────────────────────────────────────────────────────────────────
   DS — the JS half of the design system. Mirrors the CSS custom
   properties so inline-styled components can pull from the same
   ladder instead of inventing numbers. Overlay modules read it off
   window.SOP_DS so their panels match the core screens.
   ───────────────────────────────────────────────────────────────── */
const DS = {
  /* compact landscape-phone ladder — overlay modules read these so their
     panels never drift back to the old oversized scale. */
  t: {}, // filled below: landscape ladder, or three sizes on phones
  s: [0, 6, 10, 16, 24, 36, 52],
  r: { sm: 8, md: 14, lg: 22, pill: 999 },
  ctl: { h: 64, cta: 78, pad: "16px 36px" },
};
// Type sizes. On phones (portrait) every role maps to one of three sizes,
// small / body / headline, matching TS() in the page shell.
const DS_T_WIDE = { micro: 16, meta: 18, label: 21, body: 24, lead: 27, title: 34, screen: 48, hero: 68 };
const DS_T_PHONE = { micro: "small", meta: "small", label: "small", body: "body", lead: "body", title: "headline", screen: "headline", hero: "headline" };
Object.keys(DS_T_WIDE).forEach(k => Object.defineProperty(DS.t, k, {
  enumerable: true,
  get: () => (TALL() && window.SOP_PHONE_TYPE ? window.SOP_PHONE_TYPE[DS_T_PHONE[k]] : DS_T_WIDE[k]),
}));
window.SOP_DS = DS;

/* Visual mode — public (out among the people), admin (behind the desk),
   private (the back room). Switching it re-skins every ds-* surface. */
const MODES = ["public", "admin", "private"];
function setMode(m) {
  const st = document.getElementById("sop-stage");
  if (!st || MODES.indexOf(m) < 0) return;
  MODES.forEach(x => st.classList.remove("mode-" + x));
  st.classList.add("mode-" + m);
  // Inline styles read CL, which caches computed vars — drop the cache so the
  // next render picks up the new mode's ink and surfaces.
  try { window.SOP_clearColorCache && window.SOP_clearColorCache(); } catch (e) {}
}
window.SOP_setMode = setMode;
// Keeps the stage in mode m. Runs after every render (cheap when nothing
// changed) so a mode set elsewhere is corrected, and
// re-renders once on a switch: inline colours read CL, which is only
// refreshed after the class changes, so the first paint would otherwise
// mix one mode's ink with another's surfaces.
const useMode = (m) => {
  const [, bump] = React.useState(0);
  React.useEffect(() => {
    const st = document.getElementById("sop-stage");
    if (st && !st.classList.contains("mode-" + m)) { setMode(m); bump(x => x + 1); }
  });
};

const cl = (v, a = 0, b = 1) => Math.max(a, Math.min(b, v));
const cl100 = (v) => Math.max(0, Math.min(100, v));
const rng = (s) => { let x = ((Math.abs(s) + 1) % 2147483647) || 1; return () => { x = (x * 16807) % 2147483647; return (x - 1) / 2147483646; }; };
const pick = (a, r) => a[Math.floor(r() * a.length)];
const ri = (a, b, r) => Math.floor(a + r() * (b - a + 1));
const naira = (v) => typeof v === "number" && Math.abs(v) >= 1000 ? "₦" + (v / 1000).toFixed(2) + "T" : "₦" + (typeof v === "number" ? v.toFixed(1) : v) + "B";
