const ZONE_LABELS = ["North Senatorial", "Central Senatorial", "South Senatorial"];
// The presidency runs on the governorship's engine with Nigeria as the polity:
// its "LGAs" are the 36 states and the FCT, its zones the six geopolitical zones.
const NATION = "Nigeria";
const NATION_ZONES = ["North-West", "North-East", "North-Central", "South-West", "South-East", "South-South"];
const NATION_ZONE_IDS = ["NW", "NE", "NC", "SW", "SE", "SS"];
const zonesOf = (state) => state === NATION ? NATION_ZONES : ZONE_LABELS;
const getLGAs = (state) => STATE_LGAS[state] || [];
/* Nigeria as a polity: kept out of Object.keys (so no state picker, map or
   leaderboard ever lists it) but readable as STATES.Nigeria. The money is the
   Federal Government's: independent revenue and its share of the Federation
   Account, about nine times the largest state's. */
Object.defineProperty(STATES, NATION, { enumerable: false, value: mkS(220, 240, 380, .62, .40, .38, .40, .50, .33, .46, "NC", "Extreme", "The Federal Republic.", ["insecurity", "fuel and power", "the naira"]) });
Object.defineProperty(STATE_LGAS, NATION, { enumerable: false, value: Object.keys(STATES) });
// Real senatorial districts where they are entered (index 0 North, 1 Central,
// 2 South); elsewhere the state's LGAs are dealt into three groups.
const SENATORIAL = {
  Edo: [["Akoko-Edo", "Etsako East", "Etsako West", "Etsako Central", "Owan East", "Owan West"],
        ["Esan Central", "Esan North-East", "Esan South-East", "Esan West", "Igueben"],
        ["Egor", "Ikpoba-Okha", "Oredo", "Orhionmwon", "Ovia North-East", "Ovia South-West", "Uhunmwonde"]],
};
const lgaCluster = (lgas, idx) => { const st = lgas === STATE_LGAS[NATION] ? NATION : Object.keys(STATE_LGAS).find(k => STATE_LGAS[k] === lgas); if (st === NATION) return lgas.filter(k => (k === "FCT" ? "NC" : STATES[k]?.zone) === NATION_ZONE_IDS[idx]); if (st && SENATORIAL[st]) return SENATORIAL[st][idx].filter(l => lgas.includes(l)); return lgas.filter((_, i) => i % 3 === idx); };
const buildBattlegrounds = (state, seed, partyId, oppPartyId) => {
  const lgas = getLGAs(state);
  const r = rng(seed + state.length * 101 + (partyId || "").length * 17);
  const zoneInfo = STATES[state]?.zone || "SW";
  // Regional bias: YDM strong SE/SS/Lagos; UCP strong North/NC; NRA & PFP national; WPN weakened
  const partyBias = (pid) => {
    if (!pid) return 0;
    if (pid === "NRA") return 2;
    if (pid === "PFP") return 1;
    if (pid === "UCP") return (zoneInfo === "NW" || zoneInfo === "NE" || zoneInfo === "NC") ? 3 : -2;
    if (pid === "YDM") return (zoneInfo === "SE" || zoneInfo === "SS" || state === "Lagos") ? 4 : -1;
    if (pid === "WPN") return (zoneInfo === "SE" || state === "Lagos") ? 1 : -3;
    return 0;
  };
  // Party strength is in the poll from the start, so the poll is what gets counted:
  // a weaker party starts visibly behind instead of losing a race it seemed to lead.
  const strength = (pid) => (PARTIES.find(p => p.id === pid) || {}).strength || 1;
  const ps = strength(partyId), os = strength(oppPartyId);
  return zonesOf(state).map((zone, idx) => {
    const names = lgaCluster(lgas, idx);
    const b0 = 43 + Math.round(r() * 14) + partyBias(partyId), o0 = 40 + Math.round(r() * 16) + partyBias(oppPartyId);
    const k = (b0 + o0) / (b0 * ps + o0 * os), base = Math.round(b0 * ps * k), opp = Math.round(o0 * os * k);
    return { id: idx, zone, names, key: names.slice(0, 4).join(", "), support: cl100(base), opp: cl100(opp), turnout: cl100(44 + Math.round(r() * 28)), swing: cl100(100 - Math.abs(base - opp) * 2), visits: 0 };
  });
};
/* What the polls show is what gets counted: the campaign's running points
   (your moves against their attacks) and, at re-election, your record, moved
   into every zone. Election night adds only a little noise. */
const ptsShift = (zones, d) => !d ? zones : zones.map(z => ({ ...z, support: cl100(z.support + d), opp: cl100(z.opp - d * .4) }));
// Poll share: you vs the main opponent, always adding to 100
const pollShare = (z) => { const t = (z.support || 0) + (z.opp || 0); return t > 0 ? Math.round(100 * z.support / t) : 50; };
const sgnN = (n) => (n > 0 ? "+" : n < 0 ? "\u2212" : "\u00b1") + Math.abs(n);
const shiftZones = (zones, target, your = 0, opp = 0, turnout = 0) => zones.map(z => {
  const hit = target === "all" || target === z.id;
  return hit ? { ...z, support: cl100(z.support + your), opp: cl100(z.opp + opp), turnout: cl100(z.turnout + turnout), visits: z.visits + (your > 0 || turnout > 0 ? 1 : 0) } : z;
});
// Real INEC-style collation: derive actual vote counts from registered voters, turnout and party support share
// The opponent's own move. It lands on the polls before you answer, harder on
// hard mode and harder still when you lead (a trailing opponent goes all out).
const oppStrike = (zones, hit, level, week) => {
  const k = level === "hard" ? 1.2 : level === "easy" ? 0.7 : 1.1;
  const state0 = zones.reduce((a, z) => a + pollShare(z), 0) / zones.length;
  const press = state0 > 54 ? 3 : state0 > 50 ? 1 : 0;
  const after = shiftZones(zones, hit.target ?? "all", -Math.round((hit.your || 0) * k), Math.round(((hit.opp || 0) + press) * k), hit.turnout ? -hit.turnout : 0);
  const out = after.map((z, i) => { const d = pollShare(z) - pollShare(zones[i]); return d !== 0 ? { ...z, moves: [...(zones[i].moves || []), { w: week, l: "Their " + hit.l, d, them: true }] } : z; });
  const lost = Math.round(state0 - out.reduce((a, z) => a + pollShare(z), 0) / out.length);
  const worst = out.map((z, i) => ({ z, d: pollShare(z) - pollShare(zones[i]) })).sort((a, b) => a.d - b.d)[0];
  return { zones: out, pts: Math.round(((hit.your || 0) + (hit.opp || 0) + press) * k / 2), lost, worstZone: worst && worst.d < 0 ? worst.z.zone.replace(" Senatorial", "") : null, worstD: worst ? worst.d : 0 };
};
const lgaElectionSummary = (zones, partyStrength = 1, oppStrength = 1, state = null) => {
  const popM = (state && STATES[state]?.pop) || 4; // millions
  // ~48% of population is registered (matches INEC 2023 national average)
  const registeredTotal = Math.round(popM * 1_000_000 * 0.48);
  const zoneReg = Math.round(registeredTotal / zones.length);
  const rows = zones.map(z => {
    const turnoutFrac = Math.max(0.12, Math.min(0.68, z.turnout / 100));
    const votesCast = Math.round(zoneReg * turnoutFrac);
    const yourShare = Math.max(1, z.support * partyStrength);
    const oppShare = Math.max(1, z.opp * oppStrength);
    // ~5% goes to minor party candidates so totals feel real
    const validVotes = Math.round(votesCast * 0.95);
    const shareTotal = yourShare + oppShare;
    const yourVotes = Math.round(validVotes * (yourShare / shareTotal));
    const oppVotes = Math.max(0, validVotes - yourVotes);
    return { ...z, votesCast, yourVotes, oppVotes, won: yourVotes >= oppVotes };
  });
  const totalYou = rows.reduce((a, r) => a + r.yourVotes, 0);
  const totalOpp = rows.reduce((a, r) => a + r.oppVotes, 0);
  // Section 179(2): the most votes AND at least a quarter of the votes in two-thirds of
  // the local governments. Each LGA's share varies around its zone's (seeded by name).
  const lgas = rows.flatMap(r => { const share = r.yourVotes / Math.max(1, r.yourVotes + r.oppVotes); return (r.names && r.names.length ? r.names : [r.zone]).map(nm => { const j = (hashStr(nm + (state || "")) % 1000) / 1000 - .5; const you = Math.max(.02, Math.min(.98, share + j * .36)); return { nm, you: Math.round(you * 1000) / 10, opp: Math.round((1 - you) * 1000) / 10 }; }); });
  const need = Math.ceil(lgas.length * 2 / 3);
  const you25 = lgas.filter(l => l.you >= 25).length, opp25 = lgas.filter(l => l.opp >= 25).length;
  const most = totalYou > totalOpp;
  // If the leader misses the spread, the Constitution calls a further election between
  // the top two. With two serious candidates, the leader on votes carries it.
  const runoff = most ? you25 < need : opp25 < need;
  return { rows, zonesWon: rows.filter(r => r.won).length, totalYou, totalOpp, margin: totalYou - totalOpp, registeredTotal, lgas, need, you25, opp25, won: most, runoff };
};
const fmtVotes = (n) => n >= 1_000_000 ? (n / 1_000_000).toFixed(2) + "M" : n >= 1_000 ? (n / 1_000).toFixed(0) + "k" : String(n);
const fmtVotesFull = (n) => Math.round(n).toLocaleString("en-US");

