// ─── PERSONNEL ───
// Every commissioner (and the adviser) has a hidden competence and honesty,
// fixed by name. Each year they act on it, and what they do is on record.
// Anonymous choice tallies for the makers (see server /api/track): what players pick, never who.
const track = (e, v) => { try { window.SOP_track && window.SOP_track(e, v); } catch (x) {} };
const hashStr = (t) => { let h = 7; for (const ch of String(t || "")) h = (h * 31 + ch.charCodeAt(0)) >>> 0; return h; };
const traits = (name) => { const h = hashStr(name); return { comp: 32 + (h % 58), hon: 28 + ((h >>> 7) % 66) }; };
const MIN_SECTOR = { works: "infrastructure", health: "health", educ: "education", agric: "agriculture", sec: "security" };
const OFFENCE = {
  graft: { label: "Contract fraud", tone: "bad" },
  failure: { label: "Missed targets", tone: "bad" },
  disloyal: { label: "Disloyalty", tone: "bad" },
  praise: { label: "Delivered", tone: "good" },
};

// ── Statecraft: the pressures every Nigerian governor lives with ──
// Salaries against the monthly FAAC allocation, campaign promises, the
// zonal balance of the cabinet, the House of Assembly, each state's own
// recurring crises, the street's verdict and, at the end, succession.
const SECTOR_STAT = { infrastructure: "infra", health: "hp", education: "lit", agriculture: "agr", security: "sec" };
const PROMISE_TEXT = {
  infrastructure: (z) => "Tar the roads of " + z + " zone",
  health: (z) => "A working general hospital for " + z + " zone",
  education: (z) => "No child out of school in " + z + " zone",
  agriculture: (z) => "Fertiliser for every farmer in " + z + " zone",
  security: (z) => "Safe roads and farms in " + z + " zone",
};
// FNV-1a: hashStr's ×31 keeps the letter sum mod 3, which piles names into one zone.
const zoneOfName = (name, n = 3) => { let h = 2166136261; for (const ch of String(name || "")) { h ^= ch.charCodeAt(0); h = Math.imul(h, 16777619) >>> 0; } return h % n; };
const houseSeats = (pop) => pop >= 9 ? 40 : pop >= 5 ? 30 : 24;
const NASS_SEATS = 469; // the President's: 109 senators and 360 representatives

