// One story per topic: crises, needs, dilemmas and bills that tell the same story.
const CRISIS_TOPIC = { oil_spill: "oil", illegal_refinery: "oil", bandits_tax: "kidnap", school_abduction: "kidnap", insurgent_attack: "displaced", farmer_herder: "farm", flood: "flood", sit_at_home: "sitathome", almajiri: "school", demolition: "displaced", cult_clash: "cult", erosion: "road", mining: "health", land_clash: "land" };
const NEED_TOPIC = { road: "road", clinic: "health", school: "school", water: "health", security: "kidnap", farm: "farm", power: "power", housing: "displaced" };
// Dilemmas the statecraft systems now tell better (salary strikes via FAAC
// and arrears; herders, floods, kidnaps and oil spills as each state's own crises).
const DILEMMA_REPLACED = ["strike", "herder", "flood", "kidnap", "oil_spill"];
const BILL_CRISIS = { hb_almajiri: "almajiri", hb_grazing: "farmer_herder", hb_anti_cult: "cult_clash" };
const stateCrisesFor = (st) => {
  const iss = (STATES[st]?.issues || []).join(" | ");
  const own = STATE_CRISES.filter(c => c.keys.test(iss));
  return own.length ? own : STATE_CRISES.filter(c => c.id === "land_clash" || c.id === "erosion");
};

// The street's verdict, rebuilt every year from what you actually did.
// A face for each street voice.
const VOICE_ART = [[/okada|keke/i, "okada-rider"], [/mechanic/i, "mechanic"], [/civil servant|teacher/i, "civil-servant"], [/nurse/i, "nurse"], [/trader|food seller/i, "market-trader"], [/graduate/i, "young-voter-student"], [/farmer/i, "vigilante-guard"], [/elder/i, "traditional-ruler-emir"], [/Pastor/i, "deputy-male"], [/Radio|caller/i, "reporter"]];
const voiceArt = (w) => { const hit = VOICE_ART.find(([rx]) => rx.test(w || "")); return hit ? hit[1] : "market-trader"; };
const streetVoices = (ctx) => {
  const { stName, last, app, cor, arrears, needs, house, balance, turn } = ctx;
  const r = rng(turn * 97 + stName.length * 13);
  const pickOne = (a) => a[Math.floor(r() * a.length)];
  const who = ["Mama Ngozi, trader", "Aliyu, okada rider", "Mrs Adebayo, teacher", "Emeka, mechanic", "Hajiya Binta, food seller", "Tunde, graduate", "Pastor Okon", "Malam Sani, farmer", "Blessing, nurse", "Chidi, keke driver"];
  const v = [];
  const failed = needs.filter(n => n.status === "failed" && n.closed >= turn - 1);
  const met = needs.filter(n => n.status === "met" && n.closed >= turn - 1);
  const stalled = needs.filter(n => n.status === "stalled");
  if (arrears >= 1) v.push({ w: pickOne(["Mrs Adebayo, civil servant", "Blessing, nurse"]), t: "Na " + arrears + " month" + (arrears === 1 ? "" : "s") + " now dem never pay us. My landlord don give me quit notice." });
  if (failed[0]) v.push({ w: pickOne(who), p: failed[0].lga, t: "Dem come " + failed[0].lga + " campaign, dance, share rice. Since then? Nothing. People die here." });
  if (stalled[0]) v.push({ w: "Emeka, mechanic", p: stalled[0].lga, t: "The contractor don pack him caterpillar commot from " + stalled[0].lga + ". E say government never pay am." });
  if (met[0]) v.push({ w: pickOne(who), p: met[0].lga, t: "I go talk true: wetin dem do for " + met[0].lga + " don help us. Make dem continue." });
  if (cor > .5) v.push({ w: "Tunde, graduate", t: "Their children dey school abroad, our own dey sit for floor. Where the money dey go?" });
  if (house && house.loyal < house.seats / 2) v.push({ w: "Aliyu, okada rider", t: "Assembly members dey cross carpet like say na bus stop. Wahala dey come." });
  if (balance) v.push({ w: "An elder from " + balance, t: "All the commissioners from one side? Are we not part of this state?" });
  if (app >= 62) v.push({ w: pickOne(who), t: "This governor dey try. Even my husband wey no dey like politician dey hail am." });
  if (app < 40) v.push({ w: pickOne(who), t: "This government don tire us. Na election we dey wait." });
  if (last) v.push({ w: "Phone-in caller on Radio " + stName, t: "About the governor and the " + last.toLowerCase().replace(/[.!]+$/, "") + ": " + (app >= 50 ? "at least him dey do something." : "na so dem dey talk every time.") });
  if (!v.length) v.push({ w: pickOne(who), t: "We dey watch. Talk no be food." });
  const tag = arrears >= 2 ? "#PayOurSalaries" + stName.replace(/\s/g, "") : app < 40 ? "#" + stName.replace(/\s/g, "") + "DeservesBetter" : cor > .5 ? "#WhereIsOurMoney" : app >= 62 ? "#" + stName.replace(/\s/g, "") + "IsWorking" : "#" + stName.replace(/\s/g, "") + "Decides";
  return { tag, lines: v.slice(0, 3) };
};


// ── Raising money without borrowing ──
// Real measures Nigerian states have used. Each pays over time on a schedule
// (k = years from adoption): revIGR is money a year (new revenue or
// savings), taxEff multiplies taxes collected, debt pays down borrowing.
const REVENUE_MEASURES = [
  { id: "irs", img: "pos-terminal", icon: "🧾", t: "Make the revenue service autonomous and digital",
    what: "Tax IDs, e-payment, no cash at the counter, and collectors paid on results. Lagos multiplied its own revenue this way.",
    cost: "IGR −₦0.4B this year; party −2 (collectors lose their cut)",
    gain: (c) => "Taxes collected +30% over three years (about +₦" + (Math.max(1.5, c.s.igr || 3) * .3).toFixed(1) + "B a year)",
    adopt: () => ({ fx: { pStab: -2 }, sched: [{ k: 0, revIGR: -.4 }, { k: 1, revIGR: .4, taxEff: .1 }, { k: 2, taxEff: .1 }, { k: 3, taxEff: .1 }], log: "made the revenue service autonomous and digital", wiki: "Made the state revenue service autonomous and moved tax payments online." }) },
  { id: "payroll", img: "fingerprint-scanner", icon: "🪪", t: "Biometric payroll audit to remove ghost workers",
    what: "Every worker verified with BVN and fingerprints. States have found thousands of names that collect salaries but do not exist.",
    cost: "Unions protest (approval −1); a risk that real workers are wrongly removed",
    gain: (c) => "Saves about ₦" + Math.max(.3, Math.round((c.s.faac || 10) * .55 * (.03 + c.s.cor * .1) * 10) / 10) + "B every year (more where corruption is high)",
    adopt: (c) => { const g = Math.max(.3, Math.round((c.s.faac || 10) * .55 * (.03 + c.s.cor * .1) * 10) / 10); return { fx: { app: -1, cor: -.02 }, sched: [{ k: 0, revIGR: g }], cashNow: g, log: "ran a biometric payroll audit that removed ghost workers, saving ₦" + g + "B a year", wiki: "A biometric payroll audit removed ghost workers from the state's wage bill.", risk: { p: .3, fx: { app: -2 }, log: "The payroll audit wrongly struck off hundreds of real teachers. The unions are marching." } }; } },
  { id: "tsa", icon: "🏦", t: "Treasury Single Account for every ministry",
    what: "Close the hundreds of ministry and agency accounts in commercial banks and sweep idle balances into one state account.",
    cost: "Ministries and their bankers resist (party −2)",
    gain: (c) => "One-off: about ₦" + Math.round(((c.s.faac || 10) * .1 + c.s.cor * 2) * 10) / 10 + "B of idle money found, used to pay down debt",
    adopt: (c) => { const f = Math.round(((c.s.faac || 10) * .1 + c.s.cor * 2) * 10) / 10; return { fx: { pStab: -2, cor: -.03 }, sched: [{ k: 0, debt: -f }], log: "set up a Treasury Single Account and swept ₦" + f + "B of idle balances into paying down debt", wiki: "Introduced a Treasury Single Account, recovering idle funds held across ministries." }; } },
  { id: "land", img: "certificate-of-occupancy", icon: "🗺️", t: "Digital land registry and C of O drive",
    what: "Map every plot with GIS and issue Certificates of Occupancy fast. Kaduna's KADGIS turned land into steady ground rent and fees.",
    cost: "IGR −₦0.5B this year to set it up",
    gain: () => "+₦1.5B a year within two years; owners get secure titles (approval +1)",
    adopt: () => ({ fx: { app: 1 }, sched: [{ k: 0, revIGR: -.5 }, { k: 1, revIGR: 1 }, { k: 2, revIGR: 1 }], log: "launched a digital land registry and Certificate of Occupancy drive", wiki: "Launched a GIS land registry and mass Certificate of Occupancy regularisation." }) },
  { id: "levy", icon: "🧺", t: "One market levy, no touts",
    what: "Replace the dozen tickets traders pay to touts and councils with one levy, paid by phone, straight to the state.",
    cost: "Touts are party foot soldiers (party −3); they may fight back",
    gain: () => "+₦0.6B a year, and traders pay less overall (approval +2)",
    adopt: () => ({ fx: { app: 2, pStab: -3 }, sched: [{ k: 0, revIGR: .6 }], log: "replaced multiple market levies with one levy and drove out the touts", risk: { p: .25, fx: { app: -1, sec: -.01 }, log: "Touts clashed with revenue officers at the main market." } }) },
  { id: "property", icon: "🏘️", t: "Land Use Charge on high-value property",
    what: "An annual charge on valuable houses and commercial property. Fair if the register is good; resented if it is guesswork.",
    cost: "The middle class and landlords grumble (approval −2)",
    gain: (c) => c.stc.rev && c.stc.rev.land ? "+₦1.2B a year (your land registry makes it accurate)" : "+₦0.5B a year (+₦1.2B if you build the land registry first)",
    adopt: (c) => { const g = c.stc.rev && c.stc.rev.land ? 1.2 : .5; return { fx: { app: -2 }, sched: [{ k: 1, revIGR: g }], log: "introduced a Land Use Charge on high-value property (₦" + g + "B a year from next year)" }; } },
  { id: "refunds", icon: "📑", t: "Claim federal road refunds and fiscal-transparency grants",
    what: "Bill Abuja for federal roads the state repaired, and qualify for Global Development Fund grants that reward published budgets and audited accounts.",
    cost: "Your books must be clean: corruption under 45%",
    req: (c) => c.s.cor >= .45 ? "Grants need clean books: corruption must be under 45% (now " + Math.round(c.s.cor * 100) + "%)." : null,
    gain: () => "One-off ₦2B next year, used to pay down debt (approval +1)",
    adopt: () => ({ fx: { app: 1 }, sched: [{ k: 1, debt: -2 }], log: "filed federal road refund claims and qualified for fiscal-transparency grants", wiki: "Qualified for performance grants for fiscal transparency and recovered federal road refunds." }) },
  { id: "secvote", icon: "✂️", t: "Cut the security vote and half the political aides",
    what: "Publish the governor's security vote and cut it, and lay off the special assistants with no real job.",
    cost: "Hundreds of party loyalists lose their stipends (party −4)",
    gain: () => "Saves ₦0.7B a year; the public likes it (approval +2)",
    adopt: () => ({ fx: { pStab: -4, app: 2, cor: -.02 }, sched: [{ k: 0, revIGR: .7 }], log: "cut the security vote and laid off half the political aides", wiki: "Published and cut the governor's security vote and reduced political appointees." }) },
  { id: "concession", icon: "🏨", t: "Concession dead state assets to private operators",
    what: "The state hotel, farm settlements and a shut-down factory, leased to operators who must invest and hire.",
    cost: "Critics call it selling the family silver (approval −1); insiders may circle",
    gain: () => "One-off ₦1.2B against debt, then +₦0.3B a year in lease fees",
    adopt: () => ({ fx: { app: -1, cor: .01 }, sched: [{ k: 0, debt: -1.2 }, { k: 1, revIGR: .3 }], log: "concessioned dead state assets to private operators", risk: { p: .3, fx: { cor: .02, app: -1 }, log: "The hotel concession went to a company linked to your chief of staff. The press noticed." } }) },
];


// ── The compound: a landscape hub map of the State House district ──
// One painted map (art/compound/compound-full.webp, 1500×850) with every
// building already drawn in place. Over it sit a click area per building and
// its name and alerts. Points are in map pixels.
const HUB_W = 1500, HUB_H = 850;
// box: the building on the map [left, top, right, bottom].
const HUB_BUILDINGS_STATE = [
  { id: "inec", img: "b09-electoral-commission", name: "Electoral Commission", box: [258, 31, 469, 142] },
  { id: "assembly", img: "b02-house-of-assembly", name: "House of Assembly", box: [633, 8, 867, 150] },
  { id: "party", img: "b07-party-secretariat", name: "Party Secretariat", box: [1039, 39, 1242, 142] },
  { id: "secretariat", img: "b08-state-secretariat", name: "State Secretariat", box: [188, 181, 414, 299] },
  { id: "gh", img: "b01-government-house", name: "Government House", box: [562, 165, 938, 299] },
  { id: "finance", img: "b03-ministry-of-finance", name: "Ministry of Finance", box: [1078, 181, 1297, 299] },
  { id: "court", img: "b04-high-court", name: "High Court", box: [164, 331, 391, 456] },
  { id: "police", img: "b11-police-hq", name: "Police HQ", box: [1094, 338, 1305, 441] },
  { id: "palace", img: "palace", name: "The Palace", box: [62, 472, 359, 653] },
  { id: "efcc", img: "b10-efcc-office", name: "EFCC Office", box: [461, 480, 672, 614] },
  { id: "projects", img: "o-scaffold", name: "Project Sites", overlay: true, box: [797, 472, 1062, 645] },
  { id: "market", img: "b12-market", name: "Central Market", box: [1109, 472, 1406, 653] },
];
/* The President's compound: the Villa and the Three Arms Zone (Pack 14's
   compound-villa-airport.webp, Pack 15). The same destinations as the governor's, on the
   buildings painted here; the rest open from the list under the map. */
const VILLA_BUILDINGS = [
  { id: "market", icon: "v-press-room", name: "Press Briefing Room", box: [30, 150, 455, 258] },
  { id: "assembly", icon: "v-assembly", name: "National Assembly", box: [615, 8, 1025, 165] },
  { id: "court", icon: "v-supreme-court", name: "Supreme Court", box: [1070, 85, 1492, 220] },
  { id: "gh", icon: "v-villa", name: "The Villa", box: [50, 278, 735, 482] },
  { id: "secretariat", icon: "v-fec", name: "Federal Executive Council", box: [838, 255, 1150, 405] },
  { id: "palace", icon: "v-banquet-hall", name: "Banquet Hall", box: [1130, 312, 1486, 440] },
  { id: "police", icon: "v-guards-brigade", name: "Guards Brigade", box: [155, 600, 560, 790] },
  { id: "airport", icon: "v-air-fleet", name: "Presidential Air Fleet", box: [1075, 445, 1450, 625] },
  { id: "projects", name: "Project sites", pic: "backgrounds/project-site-halfway" },
  { id: "finance", icon: "v-finance", name: "Ministry of Finance" },
  { id: "party", icon: "v-party-hq", name: "Party Headquarters" },
  { id: "efcc", icon: "v-efcc", name: "EFCC Office" },
  { id: "inec", icon: "v-inec", name: "INEC" },
];
/* A Villa building's picture: cut from the Villa painting itself (so the list
   matches the map), or its own scene for places off the map. */
const VillaThumb = ({ b, w, h }) => {
  if (!b) return null;
  if (b.icon) return <img src={"./art/compound/villa/" + b.icon + ".webp"} alt="" style={{ width: w, height: h, objectFit: "contain", flexShrink: 0 }} />;
  if (!b.box) return <span style={{ display: "block", width: w, height: h, borderRadius: 8, flexShrink: 0, background: "#1d2a22 url(./art/" + b.pic + ".webp) center/cover" }} />;
  const [x0, y0, x1, y1] = b.box, bw = x1 - x0, bh = y1 - y0, k = Math.max(w / bw, h / bh);
  return <span style={{ display: "block", width: w, height: h, borderRadius: 8, flexShrink: 0, backgroundImage: "url(./art/compound/compound-villa-airport.webp)", backgroundSize: Math.round(1500 * k) + "px " + Math.round(850 * k) + "px", backgroundPosition: Math.round(-(x0 * k) + (w - bw * k) / 2) + "px " + Math.round(-(y0 * k) + (h - bh * k) / 2) + "px" }} />;
};
const CompoundHub = ({ badges, overlays, night, palace, onArrive, next, list, villa }) => {
  const HUB_BUILDINGS = villa ? VILLA_BUILDINGS : HUB_BUILDINGS_STATE, ON_MAP = HUB_BUILDINGS.filter(b => b.box);
  const wrapRef = React.useRef(null);
  const [cw, setCw] = React.useState(1000);
  React.useEffect(() => {
    const el = wrapRef.current; if (!el) return;
    const ro = new ResizeObserver(() => setCw(el.clientWidth || 1000)); ro.observe(el); setCw(el.clientWidth || 1000);
    return () => ro.disconnect();
  }, []);
  const pct = (p) => ({ left: (p[0] / HUB_W * 100) + "%", top: (p[1] / HUB_H * 100) + "%" });
  const go = (b) => { try { window.SOP_sound && window.SOP_sound("neutral"); } catch (e) {} onArrive(b.id); };
  const fz = Math.max(10, Math.min(16, cw / 80));
  const nextB = next ? HUB_BUILDINGS.find(b => b.id === next.id) : null;
  return <div>
    {next && <button onClick={() => nextB && go(nextB)} style={{ width: "100%", maxWidth: TALL() ? "none" : "max(720px, calc((var(--stage-h, 1080px) - 500px) * 16 / 9))", margin: "0 auto 10px", display: "flex", gap: 10, alignItems: "center", justifyContent: "space-between", background: "#12301f", color: "#f3f7ef", border: 0, borderRadius: 16, padding: TALL() ? "10px 14px" : "10px 18px", cursor: "pointer", textAlign: "left", fontFamily: F.b }}>
      <span><span style={{ display: "block", fontSize: TALL() ? TS(18) : TS(24), opacity: .8 }}>Next</span><b style={{ fontSize: TALL() ? TS(22) : TS(32) }}>{next.label}</b></span>
      <span style={{ background: "#0b7a4b", borderRadius: 999, padding: "8px 16px", fontWeight: 800, fontSize: TALL() ? TS(20) : TS(26), whiteSpace: "nowrap" }}>Go →</span>
    </button>}
    <div ref={wrapRef} style={{ position: "relative", isolation: "isolate", width: "100%", maxWidth: TALL() ? "none" : "max(720px, calc((var(--stage-h, 1080px) - 500px) * 16 / 9))", margin: "0 auto", aspectRatio: HUB_W + " / " + HUB_H, borderRadius: 18, overflow: "hidden", background: "#5f8f3a", boxShadow: "0 10px 30px rgba(0,0,0,.18)", userSelect: "none" }}>
      <img src={villa ? "./art/compound/compound-villa-airport.webp" : "./art/compound/compound-full.webp"} alt="" draggable={false} style={{ position: "absolute", inset: 0, width: "100%", height: "100%", display: "block", filter: night ? "brightness(.62) saturate(.75)" : "none", transition: "filter .6s" }} />
      {night && <div style={{ position: "absolute", inset: 0, background: "rgba(20,34,90,.32)", mixBlendMode: "multiply", pointerEvents: "none" }} />}
      {/* a click area over each painted building; it lights up when it needs you */}
      {ON_MAP.map(b => { const badge = badges[b.id], [x0, y0, x1, y1] = b.box;
        return <button key={b.id} onClick={() => go(b)} aria-label={b.name + (badge ? ": " + badge.text : "")} title={b.name} className={"sop-hub-spot" + (nextB && nextB.id === b.id ? " sop-next" : "")}
          style={{ position: "absolute", left: (x0 / HUB_W * 100) + "%", top: (y0 / HUB_H * 100) + "%", width: ((x1 - x0) / HUB_W * 100) + "%", height: ((y1 - y0) / HUB_H * 100) + "%", padding: 0, border: 0, borderRadius: 10, background: "transparent", cursor: "pointer", zIndex: 10,
            boxShadow: badge ? "inset 0 0 0 2px " + (badge.tone === "bad" ? "rgba(192,57,43,.85)" : "rgba(233,162,59,.9)") + ", 0 0 14px " + (badge.tone === "bad" ? "rgba(192,57,43,.55)" : "rgba(255,209,102,.6)") : "none" }} />; })}
      {/* names and alerts sit above every building so none is hidden */}
      {ON_MAP.map(b => { const badge = badges[b.id]; return <div key={"l" + b.id} onClick={() => go(b)} style={{ position: "absolute", ...pct([(b.box[0] + b.box[2]) / 2, b.box[3]]), transform: "translate(-50%, -85%)", zIndex: 4500, display: "flex", flexDirection: "column", alignItems: "center", gap: 2, cursor: "pointer" }}>
        {badge && <span className="sop-fade-in" style={{ background: badge.tone === "bad" ? "#c0392b" : "#e9a23b", color: "#fff", borderRadius: 999, padding: (fz * .25) + "px " + (fz * .7) + "px", fontSize: fz, fontWeight: 800, whiteSpace: "nowrap", boxShadow: "0 3px 10px rgba(0,0,0,.3)", fontFamily: F.b }}>{badge.text}</span>}
        <span style={{ background: "rgba(18,48,31,.85)", color: "#fff", borderRadius: 999, padding: (fz * .2) + "px " + (fz * .6) + "px", fontSize: fz * .85, fontWeight: 700, whiteSpace: "nowrap", fontFamily: F.b }}>{b.name}</span>
      </div>; })}
      {/* what is happening around the buildings */}
      {!villa && overlays.map(o => <img key={o.img + o.p} src={"./art/compound/overlays/" + o.img + ".webp"} alt="" draggable={false} className="sop-fade-in"
        style={{ position: "absolute", ...pct(o.p), width: ((o.w || 120) / HUB_W * 100) + "%", transform: "translate(-50%, -85%)", zIndex: 20, pointerEvents: "none" }} />)}
    </div>
    {(list || villa) && <div style={{ display: "grid", gridTemplateColumns: "repeat(2, 1fr)", gap: 8, marginTop: 12 }}>
      {HUB_BUILDINGS.map(b => { const badge = badges[b.id]; return <button key={b.id} onClick={() => go(b)} style={{ display: "grid", gridTemplateColumns: "auto 1fr", gap: 8, alignItems: "center", background: CL.card, border: "1.5px solid " + (badge ? (badge.tone === "bad" ? CL.red : CL.gold) + "88" : CL.bdr), borderRadius: 14, padding: "8px 10px", cursor: "pointer", textAlign: "left", fontFamily: F.b, color: CL.txt }}>
        {villa ? <VillaThumb b={b} w={52} h={40} /> : <img src={b.id === "palace" ? "./art/compound/buildings/" + palace + ".webp" : b.overlay ? "./art/compound/overlays/" + b.img + ".webp" : "./art/compound/buildings/" + b.img + ".webp"} alt="" style={{ width: 52, height: 40, objectFit: "contain" }} />}
        <span style={{ minWidth: 0 }}><b style={{ display: "block", fontSize: TS(19), lineHeight: 1.2 }}>{b.name}</b>{badge ? <span style={{ fontSize: TS(17), color: badge.tone === "bad" ? CL.red : CL.org, fontWeight: 700 }}>{badge.text}</span> : <span style={{ fontSize: TS(17), color: CL.td }}>All quiet</span>}</span>
      </button>; })}
    </div>}
  </div>;
};

// The end-of-term title.
const reportTitle = (r) =>
  r.gEnd === "impeached" ? "Impeached" :
  r.gEnd === "nullified" ? "Removed by the Supreme Court" :
  r.cor > .55 ? "The Contractors' Governor" :
  r.arrearsMax >= 5 ? "The Governor Who Owed Salaries" :
  r.failed >= 4 && r.met <= 1 ? "Mr Autopilot" :
  r.met >= 5 && r.kept >= r.broken ? "The Builder" :
  r.kept >= 3 && r.broken === 0 ? "Promise Keeper" :
  r.app >= 65 ? "The People's Governor" :
  r.app < 35 ? "The Unloved" : "The Survivor";

// Every title a career can end with, for the gallery of titles earned and still locked.
const ALL_TITLES = ["The Builder", "Promise Keeper", "The People's Governor", "The Survivor", "The Unloved", "Mr Autopilot", "The Governor Who Owed Salaries", "The Contractors' Governor", "Impeached", "Removed by the Supreme Court"];
// What each flagship does every quarter (shown on the State sheet).
const FLAGSHIP_BONUS = {
  education: "+50% literacy growth · +2 youth/turn", health: "+50% health growth · +2 women/turn",
  infrastructure: "+50% infra growth · +10% project speed", security: "+50% security · -20% shock damage",
  agriculture: "+50% agr · +₦0.3B IGR/turn", anticorruption: "-40% corruption drift · +3 media/turn",
  youth: "+3 youth/turn · MSME IGR boost", women: "+25% health & literacy",
  technology: "+₦0.4B IGR/turn · +5 business", housing: "+3 approval/turn if treasury > ₦5B",
};
const FLAGSHIP = {
  education: { i: "📚", nm: "Education for All", goal: "rehabilitate 120 primary schools" },
  health: { i: "🏥", nm: "Healthcare Revolution", goal: "reopen 40 primary health centres" },
  infrastructure: { i: "🏗️", nm: "Build, Build, Build", goal: "complete one trunk road in each senatorial zone" },
  security: { i: "🛡️", nm: "Peace & Security", goal: "equip 2,000 community guards" },
  agriculture: { i: "🌾", nm: "Agricultural Transformation", goal: "irrigate 5,000 hectares of farmland" },
  anticorruption: { i: "⚖️", nm: "Clean Governance", goal: "publish every state contract online" },
  youth: { i: "💼", nm: "Youth Empowerment", goal: "train and place 10,000 young people" },
  women: { i: "👩", nm: "Women & Social Welfare", goal: "put 20,000 more girls in school" },
  technology: { i: "💻", nm: "Digital Economy", goal: "connect 200 public schools to broadband" },
  housing: { i: "🏠", nm: "Affordable Housing", goal: "hand over 1,000 low-cost homes" },
};

// ─── STATES IN ONE LINE ───
// What a player feels in this state, from the state's own starting numbers
// (own revenue, security, poverty) and its godfather. Replaces raw percentages.
function stateLine(stateId, d) {
  if (!d) return "";
  const gf = STATE_GODFATHERS[stateId] || {};
  const wealth = d.igr >= 15 ? "Rich state, high expectations" : d.igr >= 6 ? "Earns some of its own money, needs federal money too" : "Poor state, depends on federal money";
  const bits = [wealth];
  bits.push(d.sec < .35 ? "serious security pressure" : d.sec < .5 ? "some security pressure" : "relatively calm");
  if ((gf.power || 0) >= 80) bits.push("a dominant godfather");
  else if ((gf.power || 0) <= 45) bits.push("a weak godfather");
  return bits.join(" · ");
}

// ─── THE CAST ───
// Eight recurring people who carry the consequences. Built once when the
// governor takes office and saved with the game, so every screen and module
// uses the same name for the same person. Their record is the ledger: any
// entry whose target is their name (see SOP_CAST.history).
// The godfather's title and description come from the state's power and
// aggression (STATE_GODFATHERS).
function gfPersona(def) {
  const p = (def && def.power) || 60, a = (def && def.aggression) || 50;
  return {
    title: p >= 80 ? "The Kingmaker" : p >= 60 ? "The Party Financier" : "The Old Guard Boss",
    desc: a > 70 ? "Funds campaigns, owns the party structure, and punishes disloyalty in public."
      : a > 50 ? "Funds campaigns and controls the party machinery. He collects what he is owed."
      : "A quieter power broker. He prefers favours to fights, until he doesn't.",
  };
}
// Portraits (public/art). The deputy's picture follows the deputy's first name.
const CAST_ART = { godfather: "godfather", adviser: "special-adviser", speaker: "speaker", reporter: "reporter", efcc: "efcc-investigator", rival: "rival", labour: "labour-leader" };
const FEMALE_FIRST = ["Adaeze", "Adunni", "Aisha", "Amina", "Ayomide", "Bilkisu", "Binta", "Bisola", "Bukola", "Chiamaka", "Chidinma", "Damilola", "Ekaette", "Fatima", "Folake", "Folashade", "Funmilayo", "Hadiza", "Halima", "Hannatu", "Hauwa", "Kemi", "Khadija", "Maryam", "Ngozi", "Sade", "Titi", "Yemisi", "Zainab", "Adeola", "Aishatu", "Aminat", "Falmata", "Bintu", "Yagana", "Ifeoma", "Chioma", "Nkechi", "Uche", "Modupe", "Bisi", "Funke", "Omolara", "Yetunde", "Adaobi", "Chinyere", "Amaka", "Ogechi", "Fanna", "Iquo", "Mbang", "Ebiere", "Ibinabo", "Chinwe", "Ivie", "Doosuur", "Nguavese", "Mngusoor", "Hanatu", "Kaneng", "Ladi", "Ochanya", "Onyeche", "Ojone", "Ene", "Ozavize", "Laraba", "Martha", "Deborah", "Grace", "Blessing", "Mercy", "Imaobong", "Emem"];
// The deputy's dress follows the state's region: a northern deputy in a
// kaftan or hijab, an eastern or south-south man in isiagu, a western man
// in a suit.
const NORTH_ZONES = ["NW", "NE", "NC"];
// A south-western man wears a suit, and his face shows his loyalty to you.
const DEPUTY_MOODS = [
  "deputy-female-pleased", "deputy-female-worried", "deputy-female-angry", "deputy-northern-female-hijab-pleased", "deputy-northern-female-hijab-worried", "deputy-northern-female-hijab-angry",
  "deputy-male-pleased", "deputy-male-worried", "deputy-male-angry", "deputy-male-suit-pleased", "deputy-male-suit-worried", "deputy-male-suit-angry",
  "deputy-southern-male-isiagu-pleased", "deputy-southern-male-isiagu-worried", "deputy-southern-male-isiagu-angry",
];
const deputyArt = (female, zone, lo) => {
  const base = female ? (NORTH_ZONES.includes(zone) ? "deputy-northern-female-hijab" : "deputy-female")
    : zone === "SW" || zone === "NC" ? "deputy-male-suit" : NORTH_ZONES.includes(zone) ? "deputy-male" : zone === "SE" || zone === "SS" ? "deputy-southern-male-isiagu" : "deputy-male";
  const mood = lo == null ? null : DEPUTY_MOODS.find(x => x === base + "-" + (lo >= 60 ? "pleased" : lo >= 40 ? "worried" : "angry"));
  return "./art/characters/" + (mood || base) + ".webp";
};
// The opponent's portrait: the female candidate when the name is a woman's.
const oppArt = (nm) => FEMALE_FIRST.includes(String(nm || "").replace(/^Hon\.\s*/, "").split(" ")[0]) ? "opposition-candidate-female" : "rival";
const castArt = (c, zone, lo) => {
  if (!c) return null;
  if (c.id === "deputy") return deputyArt(FEMALE_FIRST.includes(String(c.name).split(" ")[0]), zone, lo);
  if (c.id === "adviser") return saPortrait(c.name);
  if (c.id === "rival") return "./art/characters/" + oppArt(c.name) + ".webp";
  return CAST_ART[c.id] ? "./art/characters/" + CAST_ART[c.id] + ".webp" : null;
};
const CAST_FEMALE = ["Adaeze", "Funmilayo", "Halima", "Ngozi", "Aisha", "Kemi", "Chiamaka", "Zainab", "Ekaette", "Bisola", "Hauwa", "Yemisi"];
function makeCast(setup, stateId, zone) {
  const r = rng((stateId || "").length * 131 + ((setup && setup.nm) || "").length * 17 + 7);
  // Same seed and call as the first campaign, so this is the opponent the
  // player already met.
  const oppName = gN(rng((stateId ? stateId.length : 5) * 77 + 99), zone, stateId);
  const opp = "Hon. " + oppName;
  // No two people in the cast share a name or a surname.
  const used = new Set([oppName, (setup && setup.nm) || "", (setup && setup.depGov && setup.depGov.nm) || ""].filter(Boolean));
  const usedSur = new Set([...used].map(n => n.split(" ").slice(1).join(" ")));
  const usedFirst = new Set([...used].map(n => n.split(" ")[0]));
  const taken = (n) => used.has(n) || usedSur.has(n.split(" ").slice(1).join(" ")) || usedFirst.has(n.split(" ")[0]);
  const person = () => {
    let n = gN(r, zone, stateId);
    for (let i = 0; i < 20 && taken(n); i++) n = gN(r, zone, stateId);
    used.add(n); usedSur.add(n.split(" ").slice(1).join(" ")); usedFirst.add(n.split(" ")[0]);
    return n;
  };
  const surname = () => person().split(" ").slice(1).join(" ");
  // The godfather is written as "he" throughout.
  const man = () => { let n = person(); for (let i = 0; i < 12 && FEMALE_FIRST.includes(n.split(" ")[0]); i++) n = person(); return n; };
  const gfDef = STATE_GODFATHERS[stateId] || {};
  const sa = (setup && setup.saName) || (SA_ROSTER[0] && SA_ROSTER[0].name) || "Special Adviser";
  return {
    godfather: { id: "godfather", role: "Godfather", title: gfPersona(gfDef).title, name: "Chief " + man() },
    adviser: { id: "adviser", role: "Special Adviser", title: "Special Adviser", name: sa },
    deputy: { id: "deputy", role: "Deputy Governor", title: "Deputy Governor", name: (setup && setup.depGov && setup.depGov.nm) || person() },
    speaker: { id: "speaker", role: "Speaker", title: "Speaker, State House of Assembly", name: "Rt. Hon. " + person() },
    reporter: { id: "reporter", role: "Reporter", title: "Investigative reporter", name: pick(CAST_FEMALE, r) + " " + surname() },
    efcc: { id: "efcc", role: "EFCC investigator", title: "Head of Operations, EFCC zonal command", name: person() },
    rival: { id: "rival", role: "Rival", title: "Leader of the opposition", name: opp },
    labour: { id: "labour", role: "Labour leader", title: "NLC State Chairman", name: "Comrade " + person() },
  };
}
function genBio(r) { return pick(BIO_JOBS, r) + ", " + pick(BIO_LINKS, r) + ". " + (r() > .5 ? "Known as a hard worker." : r() > .5 ? "Reputation for loyalty." : "Considered ambitious."); }
const genCab = (st, seed, zone) => { const r = rng(seed + st.length * 42); const c = {}; CROLES.forEach(role => { c[role.k] = { nm: gN(r, zone, st), co: ri(35, 92, r), lo: ri(25, 90, r), cr: ri(5, 55, r), pu: ri(25, 85, r), role: role.k, bio: genBio(r) }; }); return c; };

