// ─── UI ───
const SB = ({ label, value, max = 1, color = CL.grn, icon, fmt }) => {
  const p = max === 1 ? value * 100 : value / max * 100;
  return React.createElement("div", { style: { marginBottom: 4 } },
    React.createElement("div", { style: { display: "flex", justifyContent: "space-between", fontSize: TS(16), fontFamily: F.b, color: CL.td, marginBottom: 2 } },
      React.createElement("span", null, icon, " ", label),
      React.createElement("span", { style: { color: CL.tm } }, fmt ? fmt(value) : Math.round(cl(p, 0, 100)) + "%")
    ),
    React.createElement("div", { style: { height: 8, background: "#e8ece0", borderRadius: 4, overflow: "hidden" } },
      React.createElement("div", { style: { width: cl(p, 0, 100) + "%", height: "100%", background: color, borderRadius: 4, transition: "width .4s" } })
    )
  );
};

const Cd = ({ children, style: st, onClick, active }) => {
  const [h, setH] = useState(false);
  return React.createElement("div", {
    className: "ds-card",
    onClick, onMouseEnter: () => setH(true), onMouseLeave: () => setH(false),
    style: { borderColor: active ? CL.grn : h && onClick ? "#b8c8a8" : undefined, cursor: onClick ? "pointer" : "default", transition: "all .2s", ...st }
  }, children);
};

// Phone: a section that starts closed and shows its title and one summary
// line; tap to open. In landscape it renders its content unchanged.
const Fold = ({ title, summary, children, open: startOpen = false }) => {
  const [open, setOpen] = React.useState(startOpen);
  if (!TALL()) return React.createElement(React.Fragment, null, children);
  return React.createElement("div", { style: { background: CL.card, border: "1px solid " + CL.bdr, borderRadius: 18, marginBottom: 14, overflow: "hidden" } },
    React.createElement("button", { onClick: () => setOpen(o => !o), "aria-expanded": open,
      style: { width: "100%", display: "flex", alignItems: "center", gap: 12, padding: "16px 18px", background: "transparent", border: 0, cursor: "pointer", textAlign: "left", color: CL.txt, fontFamily: F.b } },
      React.createElement("div", { style: { flex: 1, minWidth: 0 } },
        React.createElement("div", { style: { fontSize: TS(25), fontWeight: 700 } }, title),
        summary ? React.createElement("div", { style: { fontSize: TS(20), color: CL.td, marginTop: 2 } }, summary) : null),
      React.createElement("span", { style: { fontSize: TS(20), color: CL.td, transform: open ? "rotate(180deg)" : "none", transition: "transform .2s" } }, "▼")),
    open ? React.createElement("div", { style: { padding: "0 14px 14px" } }, children) : null);
};

// A scene banner: a background from public/art with a cast member in front.
// Only cast members get portraits (see CAST_ART); other scenes get the
// background alone.
// An icon from the icon pack (public/art/icons), sized to sit in a line of text.
const Ico = ({ n, s = 22, style }) => React.createElement("img", { src: "./art/icons/" + n + ".webp", alt: "", "aria-hidden": "true", style: { width: s, height: s, objectFit: "contain", verticalAlign: "middle", flexShrink: 0, ...(style || {}) } });
const SceneArt = ({ bg, scene, who, obj, alt, h = 230 }) => React.createElement("div", {
  style: { height: h, borderRadius: 20, overflow: "hidden", marginBottom: 18, display: "flex", alignItems: "flex-end", justifyContent: "center",
    background: "#1d2a22 url(./art/" + (scene ? "scenes/" + scene : "backgrounds/" + bg) + ".webp) center/cover" } },
  scene ? null : who ? React.createElement("img", { src: "./art/characters/" + who + ".webp", alt: alt || "", style: { height: h - 8, width: "auto", objectFit: "contain", objectPosition: "bottom" } })
    : obj ? React.createElement("img", { src: "./art/objects/" + obj + ".webp", alt: alt || "", style: { height: Math.round(h * .68), width: "auto", objectFit: "contain", marginBottom: Math.round(h * .12), filter: "drop-shadow(0 10px 18px rgba(0,0,0,.35))" } }) : null);

// ── Campaign screens (first election and re-election) ──
// A scoreboard (you against the opponent), three zones to win and short move cards.
const campFz = () => TALL() ? { s: TS(20), m: TS(24), l: TS(32) } : { s: TS(30), m: TS(38), l: TS(56) };
const CampChip = ({ txt, col }) => { const fz = campFz(); return <span style={{ display: "inline-block", padding: TALL() ? "3px 10px" : "4px 12px", borderRadius: 999, background: col + "16", color: col, fontSize: fz.s, fontWeight: 700, whiteSpace: "nowrap" }}>{txt}</span>; };
const CampaignBoard = ({ week, isOpp, youImg, youName, youParty, oppName, oppParty, oppImg = "rival", zones, swingId, money, days, maxDays, gfDebt, slogan, lastLog, ev }) => {
  const tall = TALL(), fz = campFz();
  const youState = Math.round(zones.reduce((a, z) => a + pollShare(z), 0) / zones.length);
  const lastMove = (z) => { const m = (z.moves || []).slice(-1)[0]; return m && m.w >= week - 1 ? m : null; };
  const nameBox = (img, nm, pty) => <div style={{ textAlign: "center" }}>
    <img src={img} alt="" style={{ height: tall ? 64 : 120, width: "auto", display: "block", margin: "0 auto" }} />
    <div style={{ fontSize: fz.s, fontWeight: 800, maxWidth: tall ? 96 : 200, lineHeight: 1.2, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{nm}</div>
    <div style={{ fontSize: fz.s, opacity: .75 }}>{pty}</div>
  </div>;
  return <>
    <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 12 }}>
      {[1, 2, 3, 4].map(w => <div key={w} style={{ flex: 1, height: 8, borderRadius: 4, background: w < week ? CL.grn : w === week ? (isOpp ? CL.red : CL.gold) : CL.bdr }} />)}
      <span style={{ fontSize: fz.s, color: CL.td, fontWeight: 800, whiteSpace: "nowrap", marginLeft: 6 }}>Week {week} of 4</span>
    </div>
    <div style={{ background: "#12301f", color: "#fff", borderRadius: 24, padding: tall ? "12px 12px 14px" : "18px 22px", display: "grid", gridTemplateColumns: "auto 1fr auto", gap: tall ? 10 : 18, alignItems: "end", marginBottom: 14 }}>
      {nameBox(youImg, youName, youParty)}
      <div style={{ alignSelf: "center" }}>
        <div style={{ display: "flex", justifyContent: "space-between", fontFamily: F.d, fontWeight: 700, fontSize: fz.l, lineHeight: 1 }}><span style={{ color: "#7ee2a8" }}>{youState}%</span><span style={{ color: "#ff9b8f" }}>{100 - youState}%</span></div>
        <div style={{ display: "flex", height: 14, borderRadius: 7, overflow: "hidden", margin: "8px 0", background: "#c0392b" }}><div style={{ width: youState + "%", background: "#2fa866", transition: "width .6s cubic-bezier(.2,.8,.2,1)" }} /></div>
        <div style={{ textAlign: "center", fontSize: fz.s, opacity: .8 }}>Statewide poll{youState > 52 ? ": you lead" : youState < 48 ? ": you trail" : ": too close to call"}</div>
      </div>
      {nameBox("./art/characters/" + oppImg + ".webp", oppName, oppParty)}
    </div>
    <div style={{ display: "grid", gridTemplateColumns: "repeat(3, minmax(0,1fr))", gap: 8, marginBottom: 12 }}>
      {zones.map(z => { const you = pollShare(z), lead = you >= 50, lm = lastMove(z); return <div key={z.id} title={z.key} style={{ background: CL.card, border: "1.5px solid " + (lead ? CL.grn + "66" : CL.red + "55"), borderRadius: 16, padding: tall ? "8px 8px" : "12px 14px" }}>
        <div style={{ fontSize: fz.s, color: CL.td, fontWeight: 700, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{z.zone.replace(" Senatorial", "")}</div>
        <div style={{ fontFamily: F.d, fontWeight: 700, fontSize: fz.m, color: lead ? CL.grn : CL.red }}>{you}%</div>
        <div style={{ height: 6, borderRadius: 3, background: CL.red + "40", overflow: "hidden" }}><div style={{ width: you + "%", height: "100%", background: CL.grn, transition: "width .6s cubic-bezier(.2,.8,.2,1)" }} /></div>
        <div style={{ fontSize: tall ? TS(18) : TS(24), marginTop: 4, color: lm ? (lm.d > 0 ? CL.grn : CL.red) : CL.td, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{lm ? (lm.d > 0 ? "▲ +" : "▼ ") + lm.d + " " + lm.l : z.id === swingId ? "Swing zone" : lead ? "Leaning you" : "Leaning them"}</div>
      </div>; })}
    </div>
    <div style={{ display: "flex", gap: 8, flexWrap: "wrap", alignItems: "center", marginBottom: 10 }}>
      <CampChip txt={"₦" + money.toFixed(2) + "B left"} col={CL.gold} />
      {gfDebt > 0 && <CampChip txt={"Godfather debt " + SYS.fmtB(gfDebt)} col={CL.red} />}
      {slogan && <CampChip txt={"“" + slogan + "”"} col={CL.grn} />}
    </div>
    {lastLog && (/^🔻/.test(lastLog)
      ? <div className="sop-fade-in" style={{ fontSize: fz.m, fontWeight: 700, color: "#fff", background: CL.red, borderRadius: 14, padding: tall ? "10px 14px" : "12px 18px", marginBottom: 12 }}>{lastLog.replace(/^🔻\s*/, "")}</div>
      : <div style={{ fontSize: fz.s, color: CL.tm, background: CL.card, borderRadius: 12, padding: "8px 12px", marginBottom: 12, border: "1px solid " + CL.bdr }}>{lastLog}</div>)}
    {isOpp ? <div style={{ marginBottom: 12 }}>
      {artFor(ATTACK_ART, ev?.t) ? <SceneArt scene={artFor(ATTACK_ART, ev?.t)} alt={(ev?.t || "").replace(/^[^A-Za-z]+/, "")} h={tall ? 160 : 200} /> : <SceneArt bg="rally" who={oppImg} alt={oppName} h={tall ? 160 : 200} />}
      <div style={{ fontFamily: F.d, fontWeight: 700, fontSize: fz.l, color: CL.txt, lineHeight: 1.15 }}>{(ev?.t || "The opponent moves").replace(/^[^A-Za-z]+/, "")}</div>
      <div style={{ fontSize: fz.m, color: CL.tm, marginTop: 6 }}>{ev?.d}</div>
    </div> : <div style={{ fontFamily: F.d, fontWeight: 700, fontSize: fz.m, color: CL.txt, margin: "2px 0 8px" }}>Pick one move this week</div>}
  </>;
};
/* One screen a week, three choices: your best answer to their last attack
   (if they made one), then the strongest moves you can afford. Never a list
   of things you can't do. */
const weekPicks = (moves, answers, canTake, sitOut) => {
  const best = (l) => (l || []).filter(canTake).sort((a, b) => (b.pts || 0) - (a.pts || 0));
  const ans = best(answers)[0], mv = best(moves);
  const out = ans ? [{ ...ans, answer: true }, ...mv.slice(0, 2)] : mv.slice(0, 3);
  return out.length ? out : [sitOut];
};
// A picture for each campaign move and each of the opponent's attacks.
const CAMP_ART = [[/Rally Tour/, "camp-rally-tour"], [/Debate/, "camp-debate"], [/Manifesto/, "camp-manifesto-drop"], [/Door-to-Door/, "camp-door-to-door"], [/LGA Chair/, "camp-lga-chairs"], [/Radio/, "camp-radio"],
  [/Youth Town Hall/, "camp-youth-town-hall"], [/Opposition Research|Attack Back/, "camp-opposition-research"], [/Market & Motor-Park|Influencer/, "camp-market-walk"], [/Mega Rally|Bigger One/, "camp-mega-rally"],
  [/GOTV/, "camp-gotv"], [/Polling Unit/, "camp-polling-agents"], [/Receipts/, "camp-answer-receipts"], [/Press Conference/, "camp-answer-press"]];
const ATTACK_ART = [[/Credentials/, "attack-credentials"], [/Rally Outdraws/, "attack-rally"], [/Smear/, "attack-smear"], [/Endorsement/, "attack-endorsement"]];
const artFor = (table, text) => { const hit = table.find(([rx]) => rx.test(text || "")); return hit ? hit[1] : null; };
const CampaignMove = ({ opt, ok, why, boosted, advised, onPick }) => {
  const tall = TALL(), fz = campFz();
  const cost = opt.cost || opt.dc || 0;
  const icon = (opt.l.match(/^\S+/) || [""])[0], name = opt.l.replace(/^\S+\s/, "");
  const st = (opt.pts || 0) >= 7 ? 3 : (opt.pts || 0) >= 4 ? 2 : (opt.pts || 0) > 0 ? 1 : 0;
  // The one line shows the trade-off when there is one; real dangers get a chip.
  const line = opt.risk || opt.d;
  const zoneTxt = opt.zoneLabel;
  return <Cd onClick={ok ? onPick : undefined} style={{ padding: tall ? "12px 14px" : "16px 18px", opacity: ok ? 1 : .45, display: "grid", gridTemplateColumns: "auto 1fr", gap: 12, alignItems: "center", textAlign: "left" }}>
    {artFor(CAMP_ART, opt.l) ? <img src={"./art/scenes/" + artFor(CAMP_ART, opt.l) + ".webp"} alt="" loading="lazy" style={{ width: tall ? 76 : 120, height: tall ? 50 : 76, objectFit: "cover", borderRadius: 12, flexShrink: 0 }} /> : <div style={{ fontSize: tall ? 30 : 40, lineHeight: 1 }}>{icon}</div>}
    <div style={{ minWidth: 0 }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", gap: 8 }}>
        <b style={{ fontSize: fz.m, color: CL.txt }}>{name}</b>
        <span aria-label={"Strength " + st + " of 3"} style={{ color: CL.grn, letterSpacing: 2, fontSize: fz.s, whiteSpace: "nowrap" }}>{"●".repeat(st)}<span style={{ color: CL.bdr }}>{"●".repeat(3 - st)}</span></span>
      </div>
      <div style={{ fontSize: fz.s, color: CL.td, margin: "2px 0 6px", lineHeight: 1.3, display: "-webkit-box", WebkitLineClamp: 2, WebkitBoxOrient: "vertical", overflow: "hidden" }} title={[opt.d, opt.risk].filter(Boolean).join(" ")}>{line}</div>
      <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
        <CampChip txt={cost > 0 ? "₦" + cost.toFixed(2) + "B" : "Free"} col={CL.gold} />
        {advised && <CampChip txt="⭐ Adviser's pick" col={CL.gold} />}
        {opt.answer && <CampChip txt="Answers their attack" col={CL.red} />}
        {zoneTxt && <CampChip txt={zoneTxt} col={CL.blu} />}
        {boosted && <CampChip txt="Slogan +2" col={CL.grn} />}
        {opt.appRisk && <CampChip txt="Can backfire" col={CL.org} />}
        {opt.corAdd && <CampChip txt="Owes favours" col={CL.org} />}
        {!ok && why && <CampChip txt={why} col={CL.red} />}
      </div>
    </div>
  </Cd>;
};

