// The President's ministers who have their own portraits (Pack 18), by ministry.
const MINISTER_ART = { fct: "fct-minister", fin: "finance-minister", petroleum: "petroleum-minister", sec: "defence-minister", just: "attorney-general" };
const commissionerArt = (name, perf, mid) => {
  if (SEAT.nat && MINISTER_ART[mid] && isFemaleName(name) === (mid === "fin")) return "./art/characters/" + MINISTER_ART[mid] + (perf == null ? "" : perf >= 65 ? "-pleased" : perf < 40 ? "-angry" : "") + ".webp";
  const nm = String(name || ""), set = FEMALE_FIRST.includes(nm.split(" ")[0]) ? COMM_F : COMM_M;
  let h = 0; for (const ch of nm) h = (h * 31 + ch.charCodeAt(0)) >>> 0;
  const base = set[h % set.length], mood = perf == null ? null : COMM_MOODS.find(x => x === base + (perf >= 65 ? "-pleased" : perf < 40 ? "-worried" : ""));
  return "./art/characters/" + (mood || base) + ".webp";
};

const Bg = ({ text, color = CL.grn }) => React.createElement("span", { className: "ds-chip", style: { background: color + "15", color, borderColor: color + "40" } }, text);

// Buttons read in sentence case: "PROCEED TO POLICIES →" becomes
// "Proceed to policies →", keeping acronyms (NRA, INEC, EFCC…) as they are.
const KEEP_CAPS = /^(NRA|PFP|YDM|UCP|WPN|INEC|EFCC|ICPC|NLC|SA|FG|FCT|FAAC|IGR|EIA|LGA|LGAS|EC8D|PS|II|UK|UN|UAE|US|NIC|BPP|AI|X|OK)$/;
const sentence = (t) => {
  if (typeof t !== "string") return t;
  const letters = t.replace(/[^A-Za-z]/g, "");
  if (letters.length < 4 || letters !== letters.toUpperCase()) return t;
  let first = true;
  return t.split(/(\s+)/).map(w => {
    const core = w.replace(/[^A-Za-z0-9]/g, "");
    if (!core) return w;
    if (KEEP_CAPS.test(core.toUpperCase()) && /[A-Z]/.test(core)) { first = false; return w; }
    const low = w.toLowerCase();
    if (first) { first = false; return low.replace(/[a-z]/, c => c.toUpperCase()); }
    return low;
  }).join("");
};
const kids = (c) => Array.isArray(c) ? c.map(sentence) : sentence(c);
