// ─── NEWS DESK CUTSCENE (iCivics-style two-anchor broadcast) ───
// A screen behind the desk, an anchor at each end, the line being read in
// a bubble pointing at whoever is speaking, and their names on the bar.
// One of the four numbers in the top strip: an icon, the value, a thin meter,
// and a short flash with the change when it moves (green good, red bad).
const StatPill = ({ label, value, color, icon, pct, raw, invert, dark }) => {
  const prev = React.useRef(raw), [d, setD] = useState(null);
  useEffect(() => {
    const p = prev.current; prev.current = raw;
    if (p == null || raw == null || Math.abs(raw - p) < (label === "In the bank" ? .05 : .5)) return;
    const up = raw > p; setD({ up, good: invert ? !up : up, txt: label === "In the bank" ? (up ? "+" : "−") + naira(Math.abs(raw - p)) : (up ? "+" : "−") + Math.round(Math.abs(raw - p)), k: Date.now() });
    const t = setTimeout(() => setD(null), 1800); return () => clearTimeout(t);
  }, [raw]);
  const tall = TALL(), ink = dark ? "#f3f7ef" : CL.txt;
  return <span style={{ position: "relative", display: "grid", gridTemplateColumns: tall ? "1fr" : "auto 1fr", alignItems: "center", columnGap: 10, minWidth: 0, textAlign: "left" }}>
    {!tall && <span style={{ gridRow: "span 2", width: 46, height: 46, borderRadius: "50%", background: dark ? "rgba(255,255,255,.1)" : CL.bg, display: "grid", placeItems: "center" }}><Ico n={icon} s={32} /></span>}
    <b style={{ display: "flex", alignItems: "center", gap: 3, minWidth: 0 }}>{tall && <Ico n={icon} s={17} />}<span key={d ? d.k : 0} className={d ? "sop-bump" : ""} style={{ fontFamily: F.m, fontSize: tall ? TS(22) : TS(38), lineHeight: 1.05, whiteSpace: "nowrap", color: d ? (d.good ? "#2fbf71" : "#ff6b5e") : ink, overflow: "hidden", textOverflow: "ellipsis" }}>{value}</span></b>
    <span style={{ display: "grid", gap: 3, minWidth: 0 }}>
      {pct != null ? <span style={{ height: tall ? 4 : 5, borderRadius: 3, background: dark ? "rgba(255,255,255,.15)" : CL.bdr, overflow: "hidden" }}><span style={{ display: "block", height: "100%", width: Math.max(4, Math.min(100, pct)) + "%", background: color || "#2fa866", transition: "width .6s ease" }} /></span> : null}
      <span style={{ fontSize: tall ? TS(14) : TS(21), opacity: .75, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis", color: pct == null && color ? color : undefined }}>{tall && label === "In the bank" ? "Bank" : label}</span>
    </span>
    {d && <span className="sop-delta" style={{ position: "absolute", right: 0, top: tall ? -12 : -18, fontSize: tall ? TS(15) : TS(22), fontWeight: 800, color: "#fff", background: d.good ? "#2fa866" : "#e0574c", borderRadius: 999, padding: "1px 7px", pointerEvents: "none" }}>{d.txt}</span>}
  </span>;
};

const AnchorDesk = ({ lines, onDone }) => {
  useMode("public");
  // The anchors have the screen to themselves: pop-ups wait for them.
  useEffect(() => { try { window.SOP_hold && window.SOP_hold(true); } catch (e) {} return () => { try { window.SOP_hold && window.SOP_hold(false); } catch (e) {} }; }, []);
  useEffect(() => { try { window.SOP_sound && window.SOP_sound("news"); } catch (e) {} }, []);
  const [i, setI] = useState(0);
  const line = lines[Math.min(i, lines.length - 1)];
  const last = i >= lines.length - 1;
  const active = line.who;
  const tall = TALL();
  const anchor = (k) => <div style={{ position: "relative", flex: "0 0 auto", width: tall ? "52%" : "28%", maxWidth: 420, display: "flex", justifyContent: "center", alignItems: "flex-end", transition: "transform .3s, filter .3s", transform: active === k ? "translateY(0)" : "translateY(4%)", filter: active === k ? "none" : "brightness(.82) saturate(.85)" }}>
    <img src={k === "m" ? ANCHOR_MALE : ANCHOR_FEMALE} alt={ANCHORS[k].first + " " + ANCHORS[k].last} style={{ width: "100%", height: "auto", display: "block" }} />
  </div>;
  return (
    <div style={{ position: "fixed", inset: 0, zIndex: 9000, display: "flex", flexDirection: "column", background: "linear-gradient(180deg,#123c4c 0%,#1f5a6d 45%,#2f6f7d 100%)", overflow: "hidden", fontFamily: F.b }}>
      {/* studio light bands */}
      <div style={{ position: "absolute", inset: 0, background: "repeating-linear-gradient(90deg, rgba(255,255,255,.035) 0 60px, rgba(255,255,255,0) 60px 140px)" }} />
      {/* the screen behind the desk */}
      <div style={{ position: "relative", zIndex: 1, margin: tall ? "8% auto 0" : "3% auto 0", width: tall ? "86%" : "min(760px,46%)", aspectRatio: "16/9", border: "4px solid #f2f2f2", borderRadius: 8, background: `#0d2a33 url(${ANCHOR_BACKDROP}) center/cover`, boxShadow: "0 12px 30px rgba(0,0,0,.35)" }}>
        <div style={{ position: "absolute", left: 10, bottom: 10, background: "#12301f", color: "#e9c46a", fontWeight: 800, fontSize: TS(18), letterSpacing: 1.5, padding: "4px 10px", borderRadius: 6 }}>STATE HOUSE REPORT · LIVE</div>
      </div>
      {/* anchors at the desk */}
      <div style={{ position: "relative", zIndex: 2, flex: 1, minHeight: 0, display: "flex", alignItems: "flex-end", justifyContent: "space-between", padding: tall ? "0 0" : "0 8%", marginTop: tall ? "-6%" : "-8%" }}>
        {anchor("m")}
        {anchor("f")}
      </div>
      {/* the desk */}
      <div style={{ position: "relative", zIndex: 3, background: "linear-gradient(180deg,#c56a22 0%,#a5521a 100%)", borderTop: "6px solid #e0904a", padding: tall ? "14px 16px 10px" : "16px 24px 12px" }}>
        <div style={{ position: "relative", maxWidth: 820, margin: "0 auto", background: "#efe9df", borderRadius: 14, padding: tall ? "14px 16px" : "16px 22px", boxShadow: "0 6px 16px rgba(0,0,0,.25)", color: "#1d2420", fontSize: tall ? 24 : TS(24), lineHeight: 1.45 }}>
          <div style={{ position: "absolute", top: -12, [active === "m" ? "left" : "right"]: "18%", width: 0, height: 0, borderBottom: "14px solid #efe9df", borderLeft: "12px solid transparent", borderRight: "12px solid transparent" }} />
          <div style={{ fontSize: TS(18), fontWeight: 800, color: "#7a4a1a", letterSpacing: 1, textTransform: "uppercase", marginBottom: 4 }}>{ANCHORS[active].first} {ANCHORS[active].last}</div>
          {line.t}
        </div>
        <div style={{ textAlign: "center", marginTop: 12 }}>
          <button onClick={() => { if (last) onDone(); else setI(i + 1); }}
            style={{ background: "#12301f", color: "#fff", border: "none", borderRadius: 999, padding: "12px 40px", minHeight: 52, fontWeight: 800, letterSpacing: .5, fontSize: TS(22), cursor: "pointer", fontFamily: F.b, boxShadow: "0 4px 12px rgba(0,0,0,.25)" }}>
            {last ? "Finish" : "Continue"}
          </button>
        </div>
      </div>
      {/* name bar */}
      <div style={{ position: "relative", zIndex: 3, background: "#2c6f7c", display: "flex", justifyContent: "space-around", padding: "10px 0 calc(10px + env(safe-area-inset-bottom))", color: "#fff", textAlign: "center" }}>
        {["m", "f"].map(k => <div key={k} style={{ opacity: active === k ? 1 : .6 }}>
          <div style={{ fontWeight: 800, fontSize: TS(26), letterSpacing: 1, textTransform: "uppercase", lineHeight: 1.1 }}>{ANCHORS[k].first}</div>
          <div style={{ fontSize: TS(18), letterSpacing: 1, textTransform: "uppercase" }}>{ANCHORS[k].last}</div>
        </div>)}
      </div>
    </div>
  );
};

const SA_PORTRAIT = "./art/characters/special-adviser.webp";
// The four advisers with a full figure, in four poses each.
const ADVISER_POSES = [
  "adviser-southwest-female-full-neutral", "adviser-southwest-female-full-pleased", "adviser-southwest-female-full-worried", "adviser-southwest-female-full-urgent",
  "adviser-north-female-full-neutral", "adviser-north-female-full-pleased", "adviser-north-female-full-worried", "adviser-north-female-full-urgent",
  "adviser-north-male-full-neutral", "adviser-north-male-full-pleased", "adviser-north-male-full-worried", "adviser-north-male-full-urgent",
  "adviser-southeast-male-full-neutral", "adviser-southeast-male-full-pleased", "adviser-southeast-male-full-worried", "adviser-southeast-male-full-urgent",
];
const saPose = (name, mood) => { const r = (typeof SA_ROSTER !== "undefined") ? SA_ROSTER.find(a => a.name === name) : null; const f = r && ADVISER_POSES.find(x => x === r.pic + "-full-" + mood); return f ? "./art/characters/" + f + ".webp" : null; };
const saMood = (say, alert) => alert ? "urgent" : /stall|block|collaps|owe|arrears|crisis|fail|reject|broke|empty|debt|missed|danger|angry/i.test(say || "") ? "worried" : /done|deliver|open|passed|ready|well|good news|award|won|paid/i.test(say || "") ? "pleased" : "neutral";
// Each adviser has their own face (SA_ROSTER.pic); unknown names fall back by first name.
const saPortrait = (name) => {
  const r = (typeof SA_ROSTER !== "undefined") ? SA_ROSTER.find(a => a.name === name) : null;
  if (r && r.pic) return "./art/characters/" + r.pic + ".webp";
  const first = String(name || "").replace(/^(Dr|Barr|Mallam|Ms|Mrs|Prof|Alh|Engr|Comrade|Hajiya|Otunba|Amb|Mai)\.?\s+/, "").split(" ")[0];
  return FEMALE_FIRST.includes(first) ? SA_PORTRAIT : "./art/characters/commissioner-male-suit.webp";
};
