const NG_CODE = { Abia: "AB", Adamawa: "AD", Akwa_Ibom: "AK", Anambra: "AN", Bauchi: "BA", Bayelsa: "BY", Benue: "BE", Borno: "BO", Cross_River: "CR", Delta: "DE", Ebonyi: "EB", Edo: "ED", Ekiti: "EK", Enugu: "EN", FCT: "FCT", Gombe: "GO", Imo: "IM", Jigawa: "JI", Kaduna: "KD", Kano: "KN", Katsina: "KT", Kebbi: "KE", Kogi: "KO", Kwara: "KW", Lagos: "LA", Nassarawa: "NA", Niger: "NI", Ogun: "OG", Ondo: "ON", Osun: "OS", Oyo: "OY", Plateau: "PL", Rivers: "RI", Sokoto: "SO", Taraba: "TA", Yobe: "YO", Zamfara: "ZA" };
// The state picker: Nigeria, state by state. Tap a state to choose it; the
// region filter fades the others. Shapes from geoBoundaries (CC BY 4.0).
const NigeriaMap = ({ value, onPick, zone, tints }) => {
  const [hover, setHover] = useState(null);
  return <svg viewBox={"-6 -6 " + (NG_MAP.w + 12) + " " + (NG_MAP.h + 12)} style={{ width: "100%", height: "auto", display: "block", touchAction: "manipulation" }} role="img" aria-label="Map of Nigeria's states">
    {Object.entries(NG_MAP.paths).map(([k, d]) => {
      const z = STATES[k]?.zone, on = value === k, faded = zone && z !== zone, fct = k === "FCT";
      return <path key={k} d={d} onClick={() => onPick(k)} onMouseEnter={() => setHover(k)} onMouseLeave={() => setHover(h => h === k ? null : h)}
        fill={on ? UI.dark : fct ? "#e4dfd5" : (tints[z] || "#fff")} stroke="#fff" strokeWidth={on ? 3 : 2} strokeLinejoin="round"
        style={{ cursor: "pointer", opacity: faded ? .28 : 1, filter: hover === k && !on ? "brightness(.93)" : "none", transition: "opacity .2s, fill .2s" }}>
        <title>{k.replace("_", " ")}</title>
      </path>;
    })}
    {Object.entries(NG_MAP.centers).map(([k, [x, y]]) => {
      const on = value === k, faded = zone && STATES[k]?.zone !== zone;
      return <text key={k} x={x} y={y + 6} textAnchor="middle" pointerEvents="none" style={{ fontFamily: F.b, fontWeight: 800, fontSize: 19, fill: on ? "#fff" : UI.ink, opacity: faded ? .3 : .78, letterSpacing: .5 }}>{NG_CODE[k] || k.slice(0, 2).toUpperCase()}</text>;
    })}
  </svg>;
};

// ─── THE SETUP FLOW: one look for every pre-game screen ───
// A slim header (back + progress), a kicker, a serif headline, one line of
// context, the choices as soft cards, and the next step in a bar that stays
// at the bottom of the screen.
const FLOW_STEPS = 7;
const Flow = ({ n, kicker, title, sub, onBack, onHelp, children, cta, ctaLabel, ctaDisabled, ctaNote, ctaTone, wide }) => {
  const tall = TALL();
  // min-height from the stage (set by the page shell): "100%" does not
  // resolve here, which left the bottom bar floating mid-screen.
  return <div style={{ minHeight: "var(--stage-h, 100%)", background: UI.cream, display: "flex", flexDirection: "column", color: UI.ink, fontFamily: F.b }}>
    <div style={{ width: "100%", maxWidth: wide && !tall ? 1100 : 760, margin: "0 auto", padding: tall ? "16px 18px 24px" : "26px 32px 28px", flex: 1 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 12, marginBottom: tall ? 18 : 24 }}>
        {onBack ? <button onClick={onBack} aria-label="Back" style={{ width: 48, height: 48, minHeight: 48, borderRadius: 24, border: "1px solid " + UI.line, background: "#fff", color: UI.ink, fontSize: 28, lineHeight: 1, cursor: "pointer", flexShrink: 0 }}>‹</button> : <span style={{ width: 48, flexShrink: 0 }} />}
        <div style={{ flex: 1, display: "flex", gap: 6 }}>
          {Array.from({ length: FLOW_STEPS }).map((_, i) => <span key={i} style={{ flex: 1, height: 6, borderRadius: 3, background: n && i < n ? UI.dark : UI.line }} />)}
        </div>
        {onHelp ? <button onClick={onHelp} aria-label="How to play" style={{ width: 48, height: 48, minHeight: 48, borderRadius: 24, border: "1px solid " + UI.line, background: "#fff", color: UI.ink, fontWeight: 700, fontSize: 20, cursor: "pointer", flexShrink: 0 }}>?</button> : <span style={{ width: 48, flexShrink: 0 }} />}
      </div>
      {kicker && <div style={{ fontSize: DS.t.meta, letterSpacing: 1.6, textTransform: "uppercase", color: UI.sub, fontWeight: 700 }}>{kicker}</div>}
      {title && <h1 style={{ fontFamily: F.d, fontWeight: 700, fontSize: tall ? 40 : 52, lineHeight: 1.12, margin: "6px 0 8px", color: UI.ink, letterSpacing: -.3 }}>{title}</h1>}
      {sub && <p style={{ fontSize: DS.t.body, color: UI.sub, lineHeight: 1.45, margin: "0 0 18px" }}>{sub}</p>}
      {children}
    </div>
    {cta && <div style={{ position: "sticky", bottom: 0, zIndex: 30, padding: tall ? "18px 18px calc(16px + env(safe-area-inset-bottom))" : "18px 32px 24px", background: "linear-gradient(180deg, rgba(246,242,234,0) 0%, " + UI.cream + " 38%)" }}>
      <div style={{ maxWidth: wide && !tall ? 1100 : 760, margin: "0 auto", textAlign: "center" }}>
        {ctaNote && <div style={{ fontSize: DS.t.label, color: UI.sub, marginBottom: 10 }}>{ctaNote}</div>}
        <button onClick={ctaDisabled ? undefined : cta} disabled={ctaDisabled} style={{ width: "100%", maxWidth: 560, minHeight: 64, borderRadius: 999, border: 0, background: ctaTone === "warn" ? CL.org : UI.dark, color: "#fff", fontFamily: F.b, fontWeight: 700, fontSize: DS.t.lead, cursor: ctaDisabled ? "not-allowed" : "pointer", opacity: ctaDisabled ? .35 : 1, boxShadow: ctaDisabled ? "none" : "0 8px 20px rgba(18,48,31,.22)" }}>{ctaLabel}</button>
      </div>
    </div>}
  </div>;
};
// A soft card in the style of the reference: tinted, rounded, an icon in a
// white circle, a bold title and one grey line; a dark ring when chosen.
const Tile = ({ tint = "#fff", icon, title, sub, on, onClick, children, style: st, disabled, badge }) => <button onClick={disabled ? undefined : onClick} style={{
  textAlign: "left", background: tint, border: "2px solid " + (on ? UI.dark : "transparent"), borderRadius: 28, padding: TALL() ? "16px 16px" : "20px 20px",
  display: "flex", flexDirection: "column", gap: 6, cursor: disabled ? "default" : "pointer", position: "relative", color: UI.ink, fontFamily: F.b, fontWeight: 400,
  boxShadow: on ? "0 10px 24px rgba(18,48,31,.14)" : "none", opacity: disabled ? .5 : 1, transition: "box-shadow .15s, border-color .15s", minHeight: 0, ...st }}>
  {badge && <span style={{ alignSelf: "flex-start", background: "#0b7a4b", color: "#fff", borderRadius: 999, padding: "3px 10px", fontSize: DS.t.meta, fontWeight: 700 }}>⭐ {badge}</span>}
  {icon && <span style={{ width: 46, height: 46, borderRadius: 23, background: "rgba(255,255,255,.75)", display: "grid", placeItems: "center", fontSize: 24, marginBottom: 6 }}>{icon}</span>}
  {title && <span style={{ fontWeight: 700, fontSize: DS.t.body, lineHeight: 1.22 }}>{title}</span>}
  {sub && <span style={{ fontSize: DS.t.label, color: UI.sub, lineHeight: 1.35 }}>{sub}</span>}
  {children}
  {on && <span style={{ position: "absolute", top: 12, right: 12, width: 30, height: 30, borderRadius: 15, background: UI.dark, color: "#fff", display: "grid", placeItems: "center", fontSize: 16, fontWeight: 700 }}>✓</span>}
</button>;
// Pill filters: the active one is filled dark, the rest are plain text.
const Seg = ({ items, value, onChange, style: st }) => <div style={{ display: "flex", gap: 4, overflowX: "auto", margin: "4px 0 16px", paddingBottom: 2, WebkitOverflowScrolling: "touch", ...st }}>
  {items.map(([k, l]) => <button key={String(k)} onClick={() => onChange(k)} style={{ flexShrink: 0, padding: "10px 18px", minHeight: 44, borderRadius: 999, border: 0, background: value === k ? UI.dark : "transparent", color: value === k ? "#fff" : UI.ink, fontWeight: 700, fontSize: DS.t.label, fontFamily: F.b, cursor: "pointer" }}>{l}</button>)}
</div>;
const Grid2 = ({ children, min = 220 }) => <div style={{ display: "grid", gridTemplateColumns: TALL() ? "1fr 1fr" : "repeat(auto-fill,minmax(" + min + "px,1fr))", gap: 12 }}>{children}</div>;
const Field = ({ label, value, onChange, placeholder, autoFocus }) => <label style={{ display: "block", textAlign: "left" }}>
  <span style={{ display: "block", fontSize: DS.t.meta, fontWeight: 700, color: UI.sub, letterSpacing: 1, textTransform: "uppercase", margin: "0 0 6px 6px" }}>{label}</span>
  <input value={value} onChange={e => onChange(e.target.value)} placeholder={placeholder} autoFocus={autoFocus} autoComplete="off" autoCapitalize="words" spellCheck={false}
    style={{ width: "100%", padding: "16px 20px", minHeight: 60, borderRadius: 20, border: "1px solid " + UI.line, background: "#fff", color: UI.ink, outline: "none", fontFamily: F.b, fontWeight: 600, boxSizing: "border-box" }} />
</label>;

// A first game's recommended picks: a calmer state, a promise that fits it,
// a strong party that still leaves campaign money, and a slogan the party
// helps you keep.
// Matches buildBattlegrounds' regional pull: UCP in the North, YDM in the
// South-East, South-South and Lagos, the NRA elsewhere.
const recParty = (k) => { const z = STATES[k]?.zone; return ["NW", "NE", "NC"].includes(z) ? "UCP" : ["SE", "SS"].includes(z) || k === "Lagos" ? "YDM" : "NRA"; };
const recState = (zone) => {
  const ks = Object.keys(STATES).filter(k => k !== "FCT" && (!zone || STATES[k].zone === zone));
  const med = ks.filter(k => STATES[k].diff === "Medium");
  return (med.length ? med : ks).reduce((a, b) => (STATES[b].sec || 0) > (STATES[a].sec || 0) ? b : a);
};
const recAgenda = (k) => (STATES[k]?.sec || 1) < .45 ? "security" : "infrastructure";
const recSlogan = (k) => "Building " + String(k || "").replace("_", " ") + " Together";
const PLAYED_KEY = "sop_played"; // set once a first governorship begins

const SetupScreen = ({ onDone, level, setLevel, profile, mode }) => {
  useMode("public");
  const [firstNm, setFirstNm] = useState(profile?.first || "");
  const [lastNm, setLastNm] = useState(profile?.last || "");
  const nm = (firstNm.trim() + " " + lastNm.trim()).trim();
  const setNm = (v) => { const p = String(v || "").trim().split(/\s+/); setFirstNm(p[0] || ""); setLastNm(p.slice(1).join(" ") || ""); };
  const [party, setParty] = useState(profile && MAIN_PARTY_IDS.includes(profile.leaning) ? profile.leaning : null);
  const [customParty, setCustomParty] = useState(null); // a party the player registers
  const [cpOpen, setCpOpen] = useState(false);
  const [cpName, setCpName] = useState("");
  const [cpId, setCpId] = useState("");
  const [cpCol, setCpCol] = useState("#7c3aed");
  const [avatar, setAvatar] = useState(profile?.avatar || null);
  const [st, setSt] = useState(profile?.origin || null);
  const [depGov, setDepGov] = useState(null);
  const [homeDistrict, setHomeDistrict] = useState(null); // 0–2: North, Central, South senatorial district
  const [homeLga, setHomeLga] = useState(null); // the local government you come from, inside that district
  // Badges earned in earlier careers: carry one honour into this campaign.
  const [earned, setEarned] = useState([]), [legacy, setLegacy] = useState(null);
  useEffect(() => { (async () => { try { const r = await window.storage.get("sop_career"); const L = r && r.value ? JSON.parse(r.value) : []; const b = SYS.careerBadges(L, (k) => STATES[k] && STATES[k].zone).filter(x => x.got && SYS.BADGE_PERKS[x.id]); setEarned(b); if (b.length) setLegacy(b[b.length - 1].id); } catch (e) {} })(); }, []);
  // Your politician says where they are from: running at home, that is your home district and LGA.
  useEffect(() => { if (!profile || !st) return; if (profile.origin === st && profile.district != null) { setHomeDistrict(profile.district); setHomeLga(profile.lga || null); } else if (homeDistrict == null) setHomeDistrict(1); }, [st]);
  const [partyDeal, setPartyDeal] = useState(null); // how you settled with the party after passing over its candidate
  const [agenda, setAgenda] = useState(null);
  const [slogan, setSlogan] = useState(null);
  const [zf, setZf] = useState(null);
  const [openZone, setOpenZone] = useState(null); // phone: the one region open in the state list
  const [step, setStep] = useState(1);
  const [showFCT, setShowFCT] = useState(false);
  const [sCampRound, setSCampRound] = useState(0);
  const [sCampScore, setSCampScore] = useState(0);
  const [sCampOpp, setSCampOpp] = useState(0);
  const [sCampLog, setSCampLog] = useState([]);
  const [sCampZones, setSCampZones] = useState(null);
  const [sCampDays, setSCampDays] = useState(0); // campaign days spent on this week's main move
  const [election, setElection] = useState(null); // the first election's result, for the Wikipedia article
  const [warChest, setWarChest] = useState(0.8); // ₦800M starting campaign funds
  // Fees your company earned from other governors go into this campaign.
  useEffect(() => { let off = false; (async () => { try { const r = window.SOP_companyClaim ? await window.SOP_companyClaim() : null; if (off || !r || !(r.amountM > 0)) return; setWarChest(w => Math.round((w + r.amountM / 1000) * 100) / 100); window.SOP_outcome && window.SOP_outcome({ icon: "💼", title: r.name + " paid in", text: r.hires + " governor" + (r.hires === 1 ? "" : "s") + " hired your company. Its fees go into this campaign's war chest.", rows: [{ l: "War chest", v: "+" + SYS.fmtM(r.amountM), good: true }], tone: "good", ok: "Good" }); } catch (e) {} })(); return () => { off = true; }; }, []);
  // Personal campaign loans from the godfather: one record per accepted offer
  // (SYS.addLoan ignores a repeat of the same key). gfDebt is their total in ₦B.
  const [gfLoans, setGfLoans] = useState([]);
  const gfDebt = SYS.toB(SYS.loanTotalM(gfLoans));
  const takeGfLoan = (key, amountB, reason) => setGfLoans(l => SYS.addLoan(l, { key, amountM: SYS.toM(amountB), reason }));
  const setGfDebt = () => setGfLoans([]); // only ever used to clear (restart)
  const gfBorrowed = gfLoans.length > 0;
  const setGfBorrowed = () => {};
  // Patronage promised in the campaign (LGA chairs, gifts, agents). An obligation
  // that raises corruption in office, not money owed: kept apart from the loans.
  const [favours, setFavours] = useState(0);
  const [gfMandates, setGfMandates] = useState([]); // concrete godfather obligations that must handshake with cabinet/projects
  const [preTrib, setPreTrib] = useState(null); // {level, spent, log, oppName, oppPartyId, margin, zonesWon, evidence}
  // Each new screen (and each new court stage) opens at its top, not at the
  // scroll position the last, longer screen was left at.
  useEffect(() => { try { window.scrollTo(0, 0); } catch (e) {} }, [step, preTrib ? preTrib.level : -1]);
  // Phase 2 §1 — Election Night has to play once before the EC8D card renders.
  // Per-instance flag ("first"/"re") — resetting sCampRound to 0 for a retry
  // clears the flag too (see reset sites below).
  const [enightPlayed, setEnightPlayed] = useState({});
  const [enightSummary, setEnightSummary] = useState(null);
  const [anchorsShown, setAnchorsShown] = useState(false);
  // First game: recommended picks, a Quick start, and the party's veterans on election day.
  const [firstRun, setFirstRun] = useState(!(profile?.games || []).length);
  useEffect(() => { if (!firstRun) return; Promise.resolve(window.storage && window.storage.get(PLAYED_KEY)).then(r => { if (r && r.value) setFirstRun(false); }).catch(() => {}); }, []);
  const [quick, setQuick] = useState(false); // Quick start running: waits for the deputies of the chosen state
  const [quickUsed, setQuickUsed] = useState(false);
  const [ticketPaid, setTicketPaid] = useState(0); // so going Back and choosing again doesn't charge twice
  const payTicket = (t) => { setWarChest(w => w + ticketPaid - t); setTicketPaid(t); };
  useEffect(() => {
    if (sCampRound >= 8 && !enightPlayed.first && st && window.SOP && window.SOP.playElectionNight) {
      // Derive opponent identity the same way the render path does (line 1312),
      // so ledger `target` and overlay labels stay coherent.
      const oppR = rng((st?.length || 5) * 77 + 99);
      const oNm = "Hon. " + gN(oppR, STATES[st]?.zone, st);
      const oPt = PARTIES.filter(p => MAIN_PARTY_IDS.includes(p.id) && p.id !== party)[Math.floor(oppR() * (MAIN_PARTY_IDS.includes(party) ? 3 : 4))];
      window.SOP.playElectionNight({
        state: st, playerName: nm, partyId: party,
        oppName: oNm, oppPartyId: oPt?.id || "OPP",
        cashRemaining: warChest, year: new Date().getFullYear(),
      }, (summary) => {
        setEnightSummary(summary);
        setEnightPlayed(p => ({ ...p, first: true }));
        try { window.SOP.__lastEnight = summary; } catch(e){}
      });
    }
  }, [sCampRound, enightPlayed.first, st]);
  const fs = useMemo(() => { const e = Object.entries(STATES); return zf ? e.filter(([, d]) => d.zone === zf) : e; }, [zf]);
  // Four running mates, one of each kind (SYS.genDeputies): no one is best at everything.
  const depCands = useMemo(() => {
    if (!st) return [];
    const r = rng(st.length * 88 + (homeDistrict || 0) * 7), used = new Set(), names = [];
    for (let i = 0; i < 4; i++) { let n = gN(r, STATES[st]?.zone, st); for (let k = 0; k < 12 && used.has(n.split(" ").slice(1).join(" ")); k++) n = gN(r, STATES[st]?.zone, st); used.add(n.split(" ").slice(1).join(" ")); names.push(n); }
    return SYS.genDeputies({ stateId: st, playerDistrict: homeDistrict || 0, names }).map(c => ({ ...c, bio: genBio(rng(c.nm.length * 31 + st.length)) }));
  }, [st, homeDistrict]);  const dc = { "Medium": CL.grn, "Hard": CL.org, "Very Hard": CL.red, "Extreme": "#8b0000" };
  useEffect(() => {
    if (!quick || !depCands.length) return;
    setDepGov(depCands.find(c => c.partyFav) || depCands[0]); setPartyDeal(null);
    setQuick(false); setQuickUsed(true);
    if (saName) setStep(7); else { setQuickNext(true); setStep(25); }
  }, [quick, depCands]);
  // Fill every step with the recommended pick and jump to the ticket. Anything can be changed with Back.
  const quickStart = () => {
    const k = st || (profile?.origin && STATES[profile.origin] && profile.origin !== "FCT" ? profile.origin : recState(zf));
    setSt(k); if (homeDistrict == null) setHomeDistrict(1);
    if (!avatar) setAvatar(AVATARS[0].id);
    if (!(firstNm.trim() && lastNm.trim())) setNm(gN(rng(Date.now() % 100000), STATES[k].zone, k));
    setAgenda(recAgenda(k));
    const P = PARTIES.find(x => x.id === recParty(k));
    setParty(P.id); payTicket(P.ticket);
    setSlogan(recSlogan(k));
    setQuick(true);
  };
  // The weekly challenge: everyone gets this week's state on Medium, set up by Quick start.
  const chDone = React.useRef(false);
  useEffect(() => { if (!mode || mode.kind !== "challenge" || chDone.current) return; if (st !== mode.state) { setSt(mode.state); return; } chDone.current = true; setLevel && setLevel("medium"); quickStart(); }, [st, mode]);
  // The Special Adviser is the player's choice (step 25), never a default.
  const [saName, setSaName] = useState(null);
  const advisedPick = React.useRef(null); // this week's move she recommends, once consulted
  const [consulted, setConsulted] = useState(-1); // the campaign round you last consulted her in
  // The comeback with the old team: every choice as it was; straight to the ticket.
  const comebackDone = React.useRef(false);
  useEffect(() => {
    if (!mode || mode.kind !== "comeback" || !mode.team || comebackDone.current) return;
    const T = mode.team.setup || {}; comebackDone.current = true;
    if (mode.team.state) setSt(mode.team.state);
    if (T.customParty) { try { registerParty(T.customParty); setCustomParty(T.customParty); } catch (e) {} }
    const P = PARTIES.find(x => x.id === T.party); if (P) { setParty(P.id); payTicket(P.ticket); }
    if (T.avatar) setAvatar(T.avatar); if (T.homeDistrict != null) setHomeDistrict(T.homeDistrict); if (T.homeLga) setHomeLga(T.homeLga);
    if (T.agenda) setAgenda(T.agenda); if (T.slogan) setSlogan(T.slogan); if (T.saName) setSaName(T.saName); if (T.depGov) setDepGov(T.depGov);
    setPartyDeal(null); setStep(7);
  }, [mode]);
  const [quickNext, setQuickNext] = useState(false); // Quick start: after choosing the adviser, go straight to the ticket

  // AGENDA_EFFECTS drives real gameplay each turn (see endTurn hook). Every option here
  // is a permanent multiplier on that domain plus a stakeholder tilt, so the choice is not cosmetic.
  const AGENDAS = [
    { id: "education", i: "📚", nm: "Education for All", d: "Free basic education, school feeding, teacher training, tech hubs.", bonus: "+50% literacy growth · +2 youth/turn · Edu budget stretches 25% further" },
    { id: "health", i: "🏥", nm: "Healthcare Revolution", d: "Revitalise PHCs, health insurance, clean water for all.", bonus: "+50% health growth · +2 women/turn · Maternal-mortality Wiki entry" },
    { id: "infrastructure", i: "🏗️", nm: "Build, Build, Build", d: "Roads, bridges, airports, housing estates.", bonus: "+50% infra growth · +1 business/turn · +10% project completion speed" },
    { id: "security", i: "🛡️", nm: "Peace & Security", d: "Community policing, intel, state security outfits (Amotekun/Ebubeagu).", bonus: "+50% security growth · -20% bandit/insurgency shock damage" },
    { id: "agriculture", i: "🌾", nm: "Agricultural Transformation", d: "Irrigation, subsidies, value chains, export crops.", bonus: "+50% agriculture growth · +₦0.3B IGR/turn from agro-clusters" },
    { id: "anticorruption", i: "⚖️", nm: "Clean Governance", d: "Transparency portal, digital government, zero tolerance.", bonus: "-40% corruption drift · Judiciary win-chance +10% · +3 media/turn" },
    { id: "youth", i: "💼", nm: "Youth Empowerment", d: "Skills, N-Power-style loans, tech hubs, mandatory youth-employment quotas.", bonus: "+3 youth/turn · +₦0.2B IGR from MSMEs · -1 approval when unfunded" },
    { id: "women", i: "👩", nm: "Women & Social Welfare", d: "Gender equality, maternal care, girl-child education.", bonus: "+25% health & literacy growth · +2 women/turn · protects against gender-based shocks" },
    { id: "technology", i: "💻", nm: "Digital Economy", d: "Broadband, e-governance, startup ecosystem, coding schools.", bonus: "+25% literacy · +₦0.4B IGR/turn from tech sector · +5 business" },
    { id: "housing", i: "🏠", nm: "Affordable Housing", d: "Mass housing, land reform, mortgage schemes for workers.", bonus: "+30% infra growth · +3 approval/turn while treasury > ₦5B" },
  ];

  const SLOGANS = [
    "A New Dawn for " + (st || "").replace("_", " "),
    "Progress, Peace, Prosperity",
    "The People's Governor",
    "Building " + (st || "").replace("_", " ") + " Together",
    "No One Left Behind",
    "Action, Not Words",
    "From Promise to Performance",
    "A Future We Can Trust",
  ];

  // The look of every setup screen comes from Flow / Tile / Seg (above).
  const ZTINT = { SW: UI.tints[3], SS: UI.tints[0], SE: UI.tints[4], NW: UI.tints[1], NE: UI.tints[2], NC: UI.tints[5] };

  // STEP 1: Choose State — on the map, like a real campaign office wall
  if (step === 1) {
    const zoneKey = zf || "all";
    const pick = (k) => { if (k === "FCT") { setShowFCT(true); return; } setSt(k); };
    const randomState = () => { const keys = Object.keys(STATES).filter(k => k !== "FCT" && (!zf || STATES[k].zone === zf)); setSt(keys[Math.floor(Math.random() * keys.length)]); };
    const d = st ? STATES[st] : null;
    const rec = recState(zf);
    return <Flow n={1} kicker="Step 1 of 7 · Your state" title="Where will you run?" wide
      cta={() => setStep(profile && profile.avatar && profile.first ? 25 : 2)} ctaDisabled={!st} ctaLabel={st ? "Run in " + st.replace("_", " ") : "Tap a state on the map"}>
      <Tile tint={UI.tints[4]} icon="⚡" onClick={quickStart} badge={firstRun ? "Best for a first game" : null} style={{ marginBottom: 14, border: "2px solid #0b7a4b" }}
        title={"Quick start" + (st ? " in " + st.replace("_", " ") : "")} sub="We pick a good first campaign: name, promise, party, slogan and deputy. You see the ticket and can change anything." />
      <div style={{ display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
        <Seg items={[["easy", "Easy"], ["medium", "Medium"], ["hard", "Hard"]]} value={level} onChange={setLevel} style={{ margin: "0 0 4px" }} />
      </div>
      <div style={{ fontSize: DS.t.meta, color: UI.sub, margin: "0 0 10px", lineHeight: 1.4 }}>{{
        easy: "Easy: approval drains slowly, fewer crises and no godfather demands, and the House only moves to impeach below 25% approval.",
        medium: "Medium: the standard game. Approval drains every year, crises are regular, and the House turns on you below 30%.",
        hard: "Hard: approval drains fast, corruption and insecurity cost more, the opposition hits harder in campaigns, and impeachment starts below 38%.",
      }[level] || ""}</div>
      <Seg items={[["all", "All Nigeria"], ...Object.entries(ZONES)]} value={zoneKey} onChange={k => setZf(k === "all" ? null : k)} />
      <div style={{ display: TALL() ? "block" : "grid", gridTemplateColumns: "1.5fr 1fr", gap: 18, alignItems: "start" }}>
        <div style={{ background: "#fff", border: "1px solid " + UI.line, borderRadius: 28, padding: TALL() ? 10 : 16 }}>
          <NigeriaMap value={st} onPick={pick} zone={zf} tints={ZTINT} />
        </div>
        <div style={{ marginTop: TALL() ? 12 : 0, background: d ? (ZTINT[d.zone] || "#fff") : "#fff", border: "1px solid " + UI.line, borderRadius: 28, padding: TALL() ? "16px 18px" : "22px 24px", minHeight: TALL() ? 0 : 220 }}>
          {d ? <>
            <div style={{ fontSize: DS.t.meta, fontWeight: 700, letterSpacing: 1.4, textTransform: "uppercase", color: UI.sub }}>{ZONES[d.zone]} · {d.pop}M people</div>
            <div style={{ fontFamily: F.d, fontWeight: 700, fontSize: TALL() ? 36 : 44, lineHeight: 1.1, margin: "4px 0 8px" }}>{st.replace("_", " ")}</div>
            <div style={{ fontSize: DS.t.body, color: UI.ink, lineHeight: 1.45 }}>{stateLine(st, d)}.</div>
            {d.desc && <div style={{ fontSize: DS.t.label, color: UI.sub, marginTop: 6, lineHeight: 1.45 }}>{d.desc}</div>}
          </> : <>
            <div style={{ fontFamily: F.d, fontWeight: 700, fontSize: TALL() ? 30 : 36 }}>Choose a state</div>
            <div style={{ fontSize: DS.t.body, color: UI.sub, marginTop: 6, lineHeight: 1.45 }}>Tap it on the map. Each starts differently: how much money it raises itself, how safe it is, and how strong its godfather is.</div>
            <button onClick={() => pick(rec)} style={{ marginTop: 12, minHeight: 48, padding: "10px 20px", borderRadius: 999, border: 0, background: "#0b7a4b", color: "#fff", fontFamily: F.b, fontWeight: 700, fontSize: DS.t.label, cursor: "pointer" }}>⭐ Recommended: {rec.replace("_", " ")}</button>
          </>}
          <button onClick={randomState} style={{ marginTop: 14, minHeight: 48, padding: "10px 20px", borderRadius: 999, border: "1px solid " + UI.line, background: "#fff", color: UI.ink, fontFamily: F.b, fontWeight: 700, fontSize: DS.t.label, cursor: "pointer" }}>🎲 Random state</button>
        </div>
      </div>
      <div style={{ fontSize: DS.t.meta, color: UI.dim, marginTop: 10 }}>Map: geoBoundaries (CC BY 4.0)</div>
      <OL show={showFCT}>
        <CivicPanel style={{ textAlign: "left" }}>
          <div style={{ fontSize: DS.t.meta, fontWeight: 700, color: UI.sub, letterSpacing: 1, textTransform: "uppercase" }}>Not playable</div>
          <h3 style={{ fontFamily: F.d, fontSize: 34, margin: "6px 0 10px" }}>Federal Capital Territory</h3>
          <p style={{ fontSize: DS.t.body, color: UI.sub, lineHeight: 1.5 }}>The FCT (Abuja) is not a state. A minister appointed by the President runs it (Section 299). There is no elected governor, no House of Assembly and no deputy governor.</p>
          <div style={{ marginTop: 16 }}><Bt onClick={() => setShowFCT(false)} style={{ width: "100%" }}>Back to the map</Bt></div>
        </CivicPanel>
      </OL>
    </Flow>;
  }

  // STEP 2: Your candidate — every portrait, and the name on the ballot
  if (step === 2) {
    const cur = AVATARS.find(a => a.id === avatar);
    const ready = firstNm.trim() && lastNm.trim() && avatar && homeDistrict != null;
    return <Flow n={2} kicker="Step 2 of 7 · Your candidate" title="Who is running?" onBack={() => setStep(1)}
      sub="Pick a portrait and type the name that goes on the ballot."
      cta={() => setStep(25)} ctaDisabled={!ready} ctaLabel="Continue"
      ctaNote={!avatar ? "Pick a portrait" : !(firstNm.trim() && lastNm.trim()) ? "Type a first and last name" : homeDistrict == null ? "Pick your home district" : <span>On the ticket: <b style={{ color: UI.ink }}>{lastNm.trim().toUpperCase()} / DEPUTY</b></span>}>
      <div style={{ display: "grid", gridTemplateColumns: TALL() ? "repeat(3,1fr)" : "repeat(auto-fill,minmax(150px,1fr))", gap: 10, marginBottom: 20 }}>
        {pickLooks().map((a, i) => {
          const on = avatar === a.id;
          return <button key={a.id} onClick={() => pickLook(a, setAvatar)} aria-label={a.label} style={{ position: "relative", padding: 0, border: "2px solid " + (on ? UI.dark : "transparent"), borderRadius: 24, background: UI.tints[i % UI.tints.length], overflow: "hidden", cursor: "pointer", aspectRatio: "3 / 4", boxShadow: on ? "0 10px 22px rgba(18,48,31,.16)" : "none" }}>
            <img src={AVATAR_IMGS[a.id]} alt="" style={{ position: "absolute", left: 0, right: 0, bottom: 0, margin: "0 auto", width: "100%", height: "100%", objectFit: "cover", objectPosition: "top" }} />
            <LookLock a={a} />
            {on && <span style={{ position: "absolute", top: 8, right: 8, width: 28, height: 28, borderRadius: 14, background: UI.dark, color: "#fff", display: "grid", placeItems: "center", fontSize: 15, fontWeight: 700 }}>✓</span>}
          </button>;
        })}
      </div>
      <div style={{ display: "grid", gridTemplateColumns: TALL() ? "1fr" : "1fr 1fr", gap: 12 }}>
        <Field label="First name" value={firstNm} onChange={setFirstNm} placeholder="Ciroma Chukwuma" />
        <Field label="Last name" value={lastNm} onChange={setLastNm} placeholder="Adekunle" />
      </div>
      <div style={{ fontSize: DS.t.meta, fontWeight: 700, color: UI.sub, letterSpacing: 1, textTransform: "uppercase", margin: "18px 0 6px 6px" }}>Your home senatorial district</div>
      <div style={{ display: "grid", gap: 8 }}>
        {SYS.DISTRICTS.map((d, i) => { const l = lgaCluster(getLGAs(st), i).slice(0, 3).join(", "); return <Tile key={d} tint={homeDistrict === i ? "#fff" : UI.tints[(i + 1) % UI.tints.length]} on={homeDistrict === i} onClick={() => { setHomeDistrict(i); setHomeLga(null); }} title={d} sub={l ? l + "…" : null} />; })}
      </div>
      {homeDistrict != null && (() => { const ls = lgaCluster(getLGAs(st), homeDistrict); return ls.length ? <>
        <div style={{ fontSize: DS.t.meta, fontWeight: 700, color: UI.sub, letterSpacing: 1, textTransform: "uppercase", margin: "16px 0 6px 6px" }}>Your home local government</div>
        <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>{ls.map(l => { const on = (homeLga || ls[0]) === l; return <button key={l} onClick={() => setHomeLga(l)} aria-pressed={on} style={{ padding: "8px 14px", minHeight: 44, borderRadius: 999, border: "1.5px solid " + (on ? UI.dark : UI.line), background: on ? UI.dark : "#fff", color: on ? "#fff" : UI.ink, fontFamily: F.b, fontWeight: 700, fontSize: DS.t.meta, cursor: "pointer" }}>{l}</button>; })}</div>
        <div style={{ fontSize: DS.t.meta, color: UI.sub, margin: "6px 6px 0" }}>Your people there vote for you, and expect you not to forget them.</div>
      </> : null; })()}
    </Flow>;
  }

  // STEP 2.5: Choose your Special Adviser. Each sees government differently;
  // none of them is always right (see SYS.SA_LENSES).
  if (step === 25) {
    const picks = SYS.SA_SHORTLIST.map(n => SA_ROSTER.find(a => a.name === n)).filter(Boolean);
    const cur = picks.find(a => a.name === saName);
    return <Flow n={2} kicker="Your team" title="Choose your Special Adviser" onBack={() => setStep(quickNext || (profile && profile.avatar && profile.first) ? 1 : 2)}
      sub="They advise across the whole government. What they notice first, and what they miss, depends on who you pick."
      cta={() => setStep(26)} ctaDisabled={!cur} ctaLabel={cur ? "Appoint " + cur.name : "Pick an adviser"} ctaNote={cur ? SYS.lensOf(cur.name).note : null}>
      <div style={{ display: "grid", gap: 12 }}>
        {picks.map((a, i) => { const L = SYS.lensOf(a.name); return <Tile key={a.name} tint={saName === a.name ? "#fff" : UI.tints[i % UI.tints.length]} on={saName === a.name} onClick={() => setSaName(a.name)}>
          <span style={{ display: "flex", gap: 12, alignItems: "center", paddingRight: 34 }}>
            <img src={saPortrait(a.name)} alt="" style={{ width: 64, height: 76, objectFit: "cover", objectPosition: "top", borderRadius: 16, background: "rgba(255,255,255,.7)", flexShrink: 0 }} />
            <span style={{ minWidth: 0 }}>
              <span style={{ display: "block", fontWeight: 800, fontSize: DS.t.body }}>{a.name}</span>
              <span style={{ display: "block", fontSize: DS.t.label, color: UI.sub }}>{L.nm} · {a.file}</span>
            </span>
          </span>
          <span style={{ fontSize: DS.t.label, color: UI.ink, lineHeight: 1.4 }}><b>Good at:</b> {L.strength}</span>
          <span style={{ fontSize: DS.t.label, color: UI.sub, lineHeight: 1.4 }}><b style={{ color: UI.ink }}>Blind spot:</b> {L.blind}</span>
        </Tile>; })}
      </div>
    </Flow>;
  }

  // STEP 2.6: Meet the adviser you chose
  if (step === 26 && saName) return (
    <Flow n={2} kicker="Your team" title={"Meet " + saName} onBack={() => setStep(25)} cta={() => { if (quickNext) { setQuickNext(false); setStep(7); } else setStep(3); }} ctaLabel={quickNext ? "See the ticket" : "Let's get to work"}>
      <div style={{ display: "flex", flexDirection: TALL() ? "column" : "row", gap: 18, alignItems: TALL() ? "stretch" : "flex-start" }}>
        <div style={{ background: UI.tints[2], borderRadius: 28, display: "flex", justifyContent: "center", alignItems: "flex-end", height: TALL() ? 300 : 360, flex: TALL() ? "none" : "0 0 300px", overflow: "hidden" }}>
          <img src={saPortrait(saName)} alt={saName} className="sop-fade-in" style={{ height: "100%", width: "auto", objectFit: "contain", objectPosition: "bottom" }} />
        </div>
        <CivicPanel style={{ flex: 1 }}>
          <div style={{ fontSize: DS.t.meta, fontWeight: 700, color: UI.green, marginBottom: 6 }}>Special Adviser to the candidate</div>
          <div style={{ fontSize: DS.t.body, lineHeight: 1.6, color: UI.ink }}>{ADV.welcome(nm, st, saName)}</div>
        </CivicPanel>
      </div>
    </Flow>
  );

  // STEP 3: Agenda (10 options)
  if (step === 3) {
    const ag = AGENDAS.find(a => a.id === agenda);
    return <Flow n={3} kicker="Step 3 of 7 · Your promise" title="What is your one big promise?" onBack={() => setStep(26)} wide
      sub="Your flagship. The adviser, the news and your Wikipedia page will judge you by it."
      cta={() => setStep(4)} ctaDisabled={!agenda} ctaLabel={ag ? "Promise " + ag.nm : "Pick a promise"} ctaNote={ag ? ag.bonus : null}>
      <Grid2 min={220}>
        {AGENDAS.map((a, i) => <Tile key={a.id} tint={UI.tints[i % UI.tints.length]} icon={a.i} title={a.nm} sub={a.d} on={agenda === a.id} onClick={() => setAgenda(a.id)} badge={a.id === recAgenda(st) ? "Recommended" : null} style={{ minHeight: TALL() ? 170 : 190 }} />)}
      </Grid2>
    </Flow>;
  }

  // STEP 4: Party Selection + Primaries
  if (step === 4) {
    const selectedParty = PARTIES.find(p => p.id === party);
    const canAffordTicket = selectedParty ? warChest + ticketPaid >= selectedParty.ticket : true;
    return <Flow n={4} kicker="Step 4 of 7 · Your party" title="Which party's ticket?" onBack={() => { setParty(null); setStep(3); }}
      sub="Each party charges a nomination fee. Bigger parties cost more and have stronger machines. What is left pays for your campaign."
      cta={() => { payTicket(selectedParty.ticket); setStep(5); }} ctaDisabled={!selectedParty || !canAffordTicket}
      ctaLabel={!selectedParty ? "Pick a party" : !canAffordTicket ? "You can't afford the " + selectedParty.id + " ticket" : selectedParty.custom ? "Register the " + selectedParty.id + " for ₦" + selectedParty.ticket + "B and stand" : "Pay ₦" + selectedParty.ticket + "B and win the " + selectedParty.id + " primary"}
      ctaNote={selectedParty && canAffordTicket ? "₦" + (warChest + ticketPaid - selectedParty.ticket).toFixed(1) + "B left for the campaign" : null}>
      <div style={{ display: "flex", gap: 10, flexWrap: "wrap", marginBottom: 16 }}>
        <span style={{ background: "#fff", border: "1px solid " + UI.line, borderRadius: 999, padding: "8px 16px", fontSize: DS.t.label, fontWeight: 700 }}>💰 War chest ₦{(warChest + ticketPaid).toFixed(1)}B</span>
        {gfDebt > 0 && <span style={{ background: UI.tints[1], borderRadius: 999, padding: "8px 16px", fontSize: DS.t.label, fontWeight: 700 }}>🎩 Owed to the godfather {SYS.fmtB(gfDebt)}</span>}
      </div>
      <div style={{ display: "grid", gap: 12 }}>
        {PARTIES.filter(p => MAIN_PARTY_IDS.includes(p.id) || (customParty && p.id === customParty.id)).map((p, i) => {
          const afford = warChest + ticketPaid >= p.ticket;
          return <Tile key={p.id} tint={party === p.id ? "#fff" : UI.tints[i % UI.tints.length]} on={party === p.id} onClick={() => setParty(p.id)} badge={p.id === recParty(st) ? "Recommended: strongest here" : null}>
            <span style={{ display: "flex", alignItems: "center", gap: 10, paddingRight: 34 }}>
              <span style={{ width: 14, height: 14, borderRadius: 7, background: p.c, flexShrink: 0 }} />
              <span style={{ fontWeight: 800, fontSize: DS.t.body }}>{p.id}</span>
              <span style={{ fontSize: DS.t.label, color: UI.sub, flex: 1, minWidth: 0 }}>{p.nm}</span>
              <span style={{ fontWeight: 800, fontSize: DS.t.body, color: afford ? UI.ink : CL.red }}>₦{p.ticket}B</span>
            </span>
            <span style={{ fontSize: DS.t.label, color: UI.sub, lineHeight: 1.4 }}>{p.desc}</span>
            <span style={{ fontSize: DS.t.meta, fontWeight: 700, color: p.custom ? CL.red : p.strength >= 1 ? UI.green : p.strength >= .8 ? CL.org : CL.red }}>{p.custom ? "New party · no machine yet" : p.strength >= 1 ? "Strong machine" : p.strength >= .8 ? "Moderate machine" : "Weak machine"}{afford ? "" : " · more than you have"}</span>
          </Tile>;
        })}
      </div>
      {!customParty && <Tile tint="#fff" icon="✚" onClick={() => setCpOpen(o => !o)} style={{ marginTop: 12, border: "2px dashed " + UI.line }}
        title="Create your own party" sub="Register a new party with INEC. Cheap, and the ticket is yours, but there is no machine behind you yet." />}
      {cpOpen && !customParty && <CivicPanel style={{ marginTop: 12 }}>
        <div style={{ display: "grid", gap: 12 }}>
          <Field label="Party name" value={cpName} onChange={setCpName} placeholder="e.g. People's Renewal Party" />
          <Field label="Short name (2–5 letters)" value={cpId} onChange={v => setCpId(String(v).toUpperCase().replace(/[^A-Z]/g, "").slice(0, 5))} placeholder="PRP" />
          <div>
            <div style={{ fontSize: DS.t.meta, fontWeight: 700, color: UI.sub, letterSpacing: 1, textTransform: "uppercase", margin: "0 0 6px 6px" }}>Colour</div>
            <div style={{ display: "flex", gap: 10 }}>{["#7c3aed", "#db2777", "#0891b2", "#ea580c", "#4d7c0f"].map(c => <button key={c} onClick={() => setCpCol(c)} aria-label={"Colour " + c} style={{ width: 44, height: 44, minHeight: 44, borderRadius: 22, background: c, border: cpCol === c ? "3px solid " + UI.dark : "3px solid #fff", boxShadow: "0 0 0 1px " + UI.line, cursor: "pointer" }} />)}</div>
          </div>
          {(() => {
            const taken = PARTIES.some(p => p.id === cpId) || LEGACY_PARTIES[cpId];
            const ok = cpName.trim().length >= 4 && cpId.length >= 2 && !taken;
            return <Bt onClick={() => { if (!ok) return; const p = { id: cpId, nm: cpName.trim(), c: cpCol, i: "⭐", ticket: 0.1, strength: 0.75, custom: true, desc: "Your own party, newly registered with INEC. ₦100M to register. No ward structures and few polling-unit agents yet: the campaign has to build them." }; registerParty(p); setCustomParty(p); setParty(p.id); setCpOpen(false); }} disabled={!ok} style={{ width: "100%" }}>{taken ? cpId + " is taken" : "Register " + (cpId || "the party")}</Bt>;
          })()}
        </div>
      </CivicPanel>}
      {!gfBorrowed && (warChest < 0.5 || (party && !canAffordTicket)) && <Tile tint={UI.tints[1]} icon="🎩" onClick={() => { if (gfLoans.some(l => l.key === "ticket")) return; setWarChest(w => w + 1); takeGfLoan("ticket", 1, "Party ticket and campaign"); }} style={{ marginTop: 14 }}
        title="Borrow ₦1B from the godfather" sub={"It pays for the ticket and the campaign. You start in office owing him, with +5% corruption, and he will collect." + (party && !canAffordTicket ? " You need it for the " + party + " ticket." : "")} />}
    </Flow>;
  }

  // STEP 5: Campaign Slogan
  if (step === 5) return (
    <Flow n={5} kicker="Step 5 of 7 · Your slogan" title="What will the crowds chant?" onBack={() => { setSlogan(null); setStep(4); }}
      sub="It does two jobs. In the campaign, the moves that match it work better. In office, voters hold you to its promise once a year."
      cta={() => setStep(6)} ctaDisabled={!slogan} ctaLabel={slogan ? "Go with this slogan" : "Pick a slogan"}>
      <div style={{ display: "grid", gap: 10 }}>
        {SLOGANS.map((sl, i) => { const sd = sloganDef(sl); return <Tile key={i} tint={slogan === sl ? "#fff" : UI.tints[i % UI.tints.length]} on={slogan === sl} onClick={() => setSlogan(sl)} badge={sl === recSlogan(st) ? "Recommended: easiest promise to keep" : null}>
          <span style={{ fontFamily: F.d, fontSize: TALL() ? 28 : 34, fontWeight: 600, lineHeight: 1.2, paddingRight: 34 }}>“{sl}”</span>
          {sd && <span style={{ fontSize: DS.t.label, color: UI.sub, lineHeight: 1.4 }}><b style={{ color: UI.ink }}>Campaign:</b> {sd.boostText} · <b style={{ color: UI.ink }}>In office:</b> {sd.promise}</span>}
        </Tile>; })}
      </div>
    </Flow>
  );

  // STEP 6: The running mate. Each candidate trades one strength for another;
  // passing over the party's choice is settled with the party (step 65), not
  // punished with a blanket deduction.
  if (step === 6) {
    const partyFav = depCands.find(c => c.partyFav) || depCands[0];
    const chosen = depGov || partyFav;
    const insist = chosen && chosen.nm !== partyFav.nm;
    const risk = SYS.balanceRisk(homeDistrict || 0, chosen);
    const meter = (l, v, c) => <span style={{ display: "flex", alignItems: "center", gap: 10, fontSize: DS.t.meta, color: UI.sub }}><span style={{ flex: "0 0 auto", minWidth: TALL() ? 130 : 110 }}>{l}</span><span style={{ flex: 1, height: 6, borderRadius: 3, background: "rgba(255,255,255,.8)", overflow: "hidden" }}><span style={{ display: "block", width: v + "%", height: "100%", background: c }} /></span></span>;
    return <Flow n={6} kicker="Step 6 of 7 · Your running mate" title="Who will be your deputy?" onBack={() => { setDepGov(null); setStep(5); }}
      sub="Each one brings something and costs something. What you see is what is known; not everything is."
      cta={() => { if (!depGov) setDepGov(partyFav); setPartyDeal(null); setStep(insist ? 65 : 7); }} ctaDisabled={!chosen} ctaTone={risk.same ? "warn" : null}
      ctaNote={risk.same ? "⚠️ " + risk.text : insist ? "The party wanted " + partyFav.nm + ". Next: how you settle it with them." : null}
      ctaLabel={!chosen ? "Pick a running mate" : insist ? "Choose " + chosen.nm.split(" ").pop() : "Accept " + chosen.nm.split(" ").pop() + ", the party's choice"}>
      <div style={{ display: "grid", gap: 12 }}>
        {[partyFav, ...depCands.filter(c => c !== partyFav)].map((c, i) => { const same = c.district === homeDistrict;
          return <Tile key={c.nm} tint={chosen?.nm === c.nm ? "#fff" : UI.tints[(i + 2) % UI.tints.length]} on={chosen?.nm === c.nm} onClick={() => setDepGov(c)}>
          <span style={{ display: "flex", gap: 8, alignItems: "center", paddingRight: 34, flexWrap: "wrap" }}>
            <span style={{ fontWeight: 800, fontSize: DS.t.body }}>{c.nm}</span>
            {c.partyFav && <span style={{ background: UI.dark, color: "#fff", borderRadius: 999, padding: "3px 10px", fontSize: DS.t.meta, fontWeight: 700 }}>Party's choice</span>}
            {same && <span style={{ background: CL.org, color: "#fff", borderRadius: 999, padding: "3px 10px", fontSize: DS.t.meta, fontWeight: 700 }}>Same district as you</span>}
          </span>
          <span style={{ fontSize: DS.t.label, color: UI.sub }}>{c.bg} · {SYS.DISTRICTS[c.district]} · network: {c.network}</span>
          {meter("Competence", c.co, CL.blu)}
          {meter("Pull with voters", c.pu, CL.grn)}
          {meter("Loyal to you", c.lo, CL.pur)}
          <span style={{ fontSize: DS.t.meta, color: UI.ink, lineHeight: 1.4 }}><b>Known:</b> {c.known.join("; ")}.</span>
          {c.allegation && <span style={{ fontSize: DS.t.meta, color: CL.org, lineHeight: 1.4 }}><b>Allegation:</b> {c.allegation}.</span>}
          {c.demand && <span style={{ fontSize: DS.t.meta, color: UI.sub, lineHeight: 1.4 }}><b style={{ color: UI.ink }}>Will want:</b> {c.demand.text}.</span>}
        </Tile>; })}
      </div>
    </Flow>;
  }

  // STEP 6.5: Settling with the party after choosing your own running mate.
  if (step === 65) {
    const partyFav = depCands.find(c => c.partyFav) || depCands[0];
    return <Flow n={6} kicker="Step 6 of 7 · The party" title="The chairman wants to talk" onBack={() => setStep(6)}
      sub={"You chose " + (depGov?.nm || "your own candidate") + " over " + partyFav.nm + ". The party will cooperate, at a price. How do you settle it?"}
      cta={() => setStep(7)} ctaDisabled={!partyDeal} ctaLabel={partyDeal ? "Agree" : "Pick how to settle it"}>
      <div style={{ display: "grid", gap: 12 }}>
        {SYS.PARTY_REACTION.map((o, i) => <Tile key={o.id} tint={partyDeal === o.id ? "#fff" : UI.tints[i % UI.tints.length]} on={partyDeal === o.id} onClick={() => setPartyDeal(o.id)} title={o.label} sub={o.note + " Party support starts at " + o.pStab + "%."} />)}
      </div>
    </Flow>;
  }

  // STEP 7: Convention Result
  if (step === 7) {
    const partyFav = depCands.find(c => c.partyFav) || depCands[0];
    const accepted = depGov?.nm === partyFav.nm;
    const deal = SYS.PARTY_REACTION.find(o => o.id === partyDeal);
    const startingStab = accepted ? SYS.PARTY_ACCEPTED.pStab : (deal ? deal.pStab : 66);
    const back = mode && mode.kind === "comeback" && mode.team;
    return <Flow n={7} kicker="Step 7 of 7 · The ticket" title={back ? "The comeback ticket" : accepted ? "A unity ticket" : "Your own running mate"} onBack={() => setStep(accepted ? 6 : 65)}
      sub={back ? "The same running mate, the same party and the same promises, four years on." : accepted ? "The party got its deputy. The machine is behind you." : "You chose your deputy and settled with the party: " + (deal ? deal.label.toLowerCase() : "no deal") + "."}
      cta={() => setStep(8)} ctaLabel="Launch the campaign">
      {mode && mode.kind === "comeback" && <Situation tone="warn" head={mode.team ? "The old team is back" : "A new team for the comeback"} text={"You served one term before the voters turned you out. The Constitution allows two terms in all (S.182(1)(b)): win this, and you have four years left." + (mode.team && (mode.team.ministries || []).length ? " Your " + mode.team.ministries.length + " commissioners" + (mode.team.cos ? " and your Chief of Staff" : "") + " will be sworn in again." : "")} />}
      {(() => {
        const depFemale = FEMALE_FIRST.includes(String(depGov?.nm || "").split(" ")[0]);
        const depImg = deputyArt(depFemale, STATES[st]?.zone, depGov?.lo);
        const pic = (src, who, role) => <div style={{ textAlign: "center", flex: "0 0 auto", width: TALL() ? 104 : 130 }}>
          <img src={src} alt={who} style={{ width: "100%", height: TALL() ? 136 : 170, objectFit: "cover", objectPosition: "top", borderRadius: 20, background: UI.tints[3], display: "block" }} />
          <div style={{ fontSize: DS.t.meta, fontWeight: 700, marginTop: 6, lineHeight: 1.25 }}>{who}</div>
          <div style={{ fontSize: DS.t.meta, opacity: .7 }}>{role}</div>
        </div>;
        // The ticket as a campaign billboard over a state-capital street.
        const P = PARTIES.find(p => p.id === party) || { nm: party, c: "#1a6d2e" }, pc = P.c || "#1a6d2e", tall = TALL();
        // Each figure wears its own name plate across the chest, never over a face.
        const fig = (src, who, role) => <div style={{ position: "relative", height: "100%", maxWidth: "48%", display: "flex", alignItems: "flex-end" }}>
          <img src={src} alt={who} style={{ height: "100%", width: "auto", maxWidth: "100%", objectFit: "contain", objectPosition: "bottom", display: "block", filter: "drop-shadow(0 4px 6px rgba(0,0,0,.35))" }} />
          <div style={{ position: "absolute", left: "50%", bottom: tall ? 4 : 8, transform: "translateX(-50%)", whiteSpace: "nowrap", textAlign: "center", background: "rgba(255,255,255,.94)", borderLeft: "3px solid " + pc, borderRadius: 4, padding: tall ? "1px 5px" : "2px 8px", fontFamily: F.b, fontSize: tall ? 10 : 12, fontWeight: 800, color: "#12301f", lineHeight: 1.2, boxShadow: "0 2px 4px rgba(0,0,0,.2)" }}>{(who || "").split(" ").pop()}<div style={{ fontWeight: 600, fontSize: tall ? 8 : 10, opacity: .75, textTransform: "uppercase", letterSpacing: .5 }}>{role}</div></div>
        </div>;
        return <div style={{ position: "relative", borderRadius: 24, overflow: "hidden", aspectRatio: "16 / 10", background: "#d8c9ad url(./art/scenes/billboard-street.webp) center / 100% 100% no-repeat", boxShadow: "0 14px 30px rgba(0,0,0,.18)" }}>
          {/* the board */}
          {/* printed on the board's blank face (x 10%–90%, y 6%–50%) */}
          <div style={{ position: "absolute", left: "10%", right: "10%", top: "6%", height: "44%" }}>
            <div style={{ position: "relative", width: "100%", height: "100%", overflow: "hidden", background: "linear-gradient(115deg, " + pc + " 0%, " + pc + " 58%, #ffffff 58.2%, #ffffff 100%)" }}>
              <div style={{ position: "absolute", left: tall ? 10 : 16, top: tall ? 8 : 12, bottom: tall ? 8 : 12, width: "50%", color: "#fff", display: "flex", flexDirection: "column", justifyContent: "space-between" }}>
                <div>
                  <div style={{ fontFamily: F.b, fontWeight: 800, fontSize: tall ? 14 : 15, letterSpacing: 1, textTransform: "uppercase", opacity: .9, lineHeight: 1.2 }}>{P.nm} · {st.replace("_", " ")} {mode && mode.kind === "comeback" ? (mode.startYear || 2027) + 8 : 2027}</div>
                  <div style={{ fontFamily: F.d, fontWeight: 900, fontSize: tall ? 30 : 38, lineHeight: 1, marginTop: 4, textShadow: "0 2px 0 rgba(0,0,0,.2)", wordBreak: "break-word" }}>{(lastNm || "").toUpperCase()}<span style={{ opacity: .7 }}> / </span>{(depGov?.nm.split(" ").pop() || "").toUpperCase()}</div>
                  <div style={{ fontFamily: F.b, fontWeight: 700, fontSize: tall ? 15 : 16, marginTop: 4, fontStyle: "italic", lineHeight: 1.2 }}>“{slogan}”</div>
                </div>
                <div style={{ alignSelf: "flex-start", display: "flex", alignItems: "center", gap: 6, background: "#fff", borderRadius: 6, padding: tall ? "3px 10px" : "4px 12px", fontFamily: F.b, fontWeight: 900, fontSize: tall ? 18 : 22, color: "#b3261e" }}><span style={{ color: pc }}>☑</span> VOTE</div>
              </div>
              <div style={{ position: "absolute", right: 0, bottom: 0, height: "100%", width: "52%", display: "flex", justifyContent: "flex-end", alignItems: "flex-end", gap: 2 }}>
                {fig(AVATAR_IMGS[avatar], nm, "Governor")}
                {fig(depImg, depGov?.nm || "", "Deputy")}
              </div>
              {/* matte vinyl sheen */}
              <div style={{ position: "absolute", inset: 0, background: "linear-gradient(160deg, rgba(255,255,255,.18) 0%, rgba(255,255,255,0) 35%, rgba(0,0,0,.08) 100%)", pointerEvents: "none" }} />
            </div>
          </div>
        </div>;
      })()}
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10, marginTop: 14 }}>
        <Tile tint={UI.tints[4]} title={startingStab + "%"} sub="Party support at the start" />
        <Tile tint={UI.tints[0]} title={"₦" + warChest.toFixed(1) + "B"} sub="Left for the campaign" />
      </div>
      {earned.length > 0 && <div style={{ marginTop: 14, background: "#fff7df", border: "1px solid #e9cf8a", borderRadius: 20, padding: "12px 14px" }}>
        <b style={{ display: "block", fontSize: DS.t.label, color: UI.ink }}>🎖️ Your record goes before you: carry one honour</b>
        <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginTop: 8 }}>{earned.map(b => { const on = legacy === b.id; return <button key={b.id} onClick={() => setLegacy(on ? null : b.id)} aria-pressed={on} style={{ display: "flex", alignItems: "center", gap: 6, padding: "6px 12px 6px 6px", minHeight: 44, borderRadius: 999, border: "1.5px solid " + (on ? UI.dark : UI.line), background: on ? UI.dark : "#fff", color: on ? "#fff" : UI.ink, fontFamily: F.b, fontWeight: 700, fontSize: DS.t.meta, cursor: "pointer" }}><img src={"./art/badges/" + BADGE_ART[b.id] + ".webp"} alt="" style={{ width: 30, height: 30 }} />{SYS.BADGE_PERKS[b.id].text}</button>; })}</div>
      </div>}
      {(quickUsed || firstRun) && <div style={{ marginTop: 14, background: "#fff", border: "1px solid " + UI.line, borderRadius: 20, padding: "12px 16px", fontSize: DS.t.label, color: UI.sub, lineHeight: 1.45 }}>
        {quickUsed && <div>⚡ Quick start chose <b style={{ color: UI.ink }}>{FLAGSHIP[agenda]?.nm}</b>, the <b style={{ color: UI.ink }}>{party}</b> and the party's deputy. Tap ‹ to change any of them.</div>}
        {firstRun && level !== "hard" && <div style={{ marginTop: quickUsed ? 6 : 0 }}>🤝 Your first campaign: party veterans lend you their polling-unit agents, worth about 2 points on election day.</div>}
      </div>}
      {SYS.balanceRisk(homeDistrict || 0, depGov).same && <div style={{ marginTop: 14, background: "#fff7ed", border: "1px solid " + CL.org + "55", borderRadius: 20, padding: "12px 16px", fontSize: DS.t.label, color: UI.ink, lineHeight: 1.45 }}>⚠️ {SYS.balanceRisk(homeDistrict || 0, depGov).text}</div>}
      <div style={{ marginTop: 14 }}><AdvBubble text={ADV.conventionResult(accepted)} saName={saName} /></div>
    </Flow>;
  }

  // STEP 8: Full Campaign Simulation — real LGA battlegrounds, no fake maps

  if (step === 8) {
    const oppR2 = rng((st?.length || 5) * 77 + 99);
    const oName = "Hon. " + gN(oppR2, STATES[st]?.zone, st);
    const oParty = PARTIES.filter(p => MAIN_PARTY_IDS.includes(p.id) && p.id !== party)[Math.floor(oppR2() * (MAIN_PARTY_IDS.includes(party) ? 3 : 4))];
    const ticketFx = SYS.campaignEffects(homeDistrict == null ? 1 : homeDistrict, depGov, partyDeal);
    const activeZones = sCampZones || buildBattlegrounds(st, 2026, party, oParty?.id).map((z, i) => ({ ...z, support: cl100(z.support + (ticketFx[i] || 0)) }));
    const pollZones = ptsShift(activeZones, (sCampScore - sCampOpp) * 0.32); // what the polls show, and what is counted
    const swingZone = activeZones.reduce((a, b) => b.swing > a.swing ? b : a, activeZones[0]);
    const weakZone = activeZones.reduce((a, b) => b.support < a.support ? b : a, activeZones[0]);
    const baseZone = activeZones.reduce((a, b) => b.support > a.support ? b : a, activeZones[0]);
    const week = Math.floor(sCampRound / 2) + 1;
    const isOpp = false; // one screen a week: their move lands straight after yours
    const isResult = sCampRound >= 8;

    // Part 1 — where you stand: one poll line per senatorial zone, shares add to 100
    const renderZones = (zones = activeZones) => <Cd style={{ padding: 24, margin: "18px 0", background: "#fbfcf8" }}>
      <div style={{ fontSize: TS(29), fontWeight: 700, color: CL.grn, fontFamily: F.m, letterSpacing: 2, marginBottom: 12 }}>WHERE YOU STAND</div>
      {zones.map(z => { const you = pollShare(z); return <div key={z.id} style={{ marginBottom: 16 }}>
        <div style={{ display: "flex", justifyContent: "space-between", gap: 14, fontSize: TS(31), color: CL.txt }}><b>{z.zone.replace(" Senatorial", "")}</b><span style={{ fontFamily: F.m }}><b style={{ color: you >= 50 ? CL.grn : CL.txt }}>You {you}%</b> · <span style={{ color: you < 50 ? CL.red : CL.tm }}>{oParty?.id || "Opponent"} {100 - you}%</span></span></div>
        <div style={{ display: "flex", height: 10, borderRadius: 5, overflow: "hidden", margin: "6px 0 4px", background: CL.red + "55" }}><div style={{ width: you + "%", background: CL.grn }} /></div>
        <div style={{ fontSize: TS(27), color: CL.td }}>{z.key}</div>
      </div>; })}
      <div style={{ fontSize: TS(27), color: CL.td }}>Poll, margin ±4. Turnout and money decide close zones.</div>
    </Cd>;

    const mkActs = () => [[
      { l: "📢 Three-Zone Rally Tour", days: 3, d: "Hit " + activeZones.map(z => z.key.split(", ")[0]).join(", ") + ". Strong statewide signal.", pts: 5, oppPts: 1, cost: 0.25, target: "all", your: 3, turnout: 4, risk: "Broad, costly, visible." },
      { l: "📺 Live Governorship Debate", days: 4, d: "No map gimmick — statewide TV/radio. You can move undecided voters everywhere.", pts: 7, oppPts: -3, cost: 0, target: "all", your: 2, opp: -2, risk: "One bad answer becomes tomorrow's headline." },
      { l: "📋 Ward Manifesto Drop", days: 2, d: "Target " + swingZone.zone + ": " + swingZone.key + ". Cheap policy operation.", pts: 3, oppPts: 0, cost: 0.03, target: swingZone.id, your: 4, turnout: 1, risk: "Good for swing LGAs, weak for momentum." },
    ],[
      { l: "🏘️ Door-to-Door Canvass", days: 2, d: "Deploy ward agents in " + swingZone.key + ". Converts actual voters, not vibes.", pts: 6, oppPts: 0, cost: 0.35, target: swingZone.id, your: 8, turnout: 6, risk: "Expensive ground game." },
      { l: "🤝 LGA Chair Coalition", days: 4, d: "Negotiate structures in your weakest zone: " + weakZone.key + ".", pts: 4, oppPts: -4, cost: 0, target: weakZone.id, your: 7, opp: -3, corAdd: .03, risk: "Patronage promises follow you into office." },
      { l: "📻 Community Radio Blitz", days: 2, d: "Local-language radio across " + baseZone.key + ". Protect your base cheaply.", pts: 3, oppPts: 0, cost: 0.05, target: baseZone.id, your: 4, turnout: 3, risk: "Defensive, not transformative." },
    ],[
      { l: "🎤 Youth Town Hall Circuit", days: 3, d: "Campus, market, creators, unions — focused on " + swingZone.zone + ".", pts: 6, oppPts: -1, cost: 0.15, target: swingZone.id, your: 7, opp: -1, turnout: 4, risk: "Youth ask brutal questions." },
      { l: "⚔️ Opposition Research Drop", days: 4, d: "Expose " + oName + ". Free, dirty, high backfire risk.", pts: 3, oppPts: -6, cost: 0, target: "all", your: 1, opp: -4, appRisk: -3, risk: "Negative politics can poison your mandate." },
      { l: "🤲 Market & Motor-Park Walk", days: 2, d: "Retail politics in " + weakZone.key + ".", pts: 2, oppPts: 0, cost: 0.02, target: weakZone.id, your: 4, turnout: 2, risk: "Warm photos, limited reach." },
    ],[
      { l: "🏟️ Final Mega Rally", days: 3, d: "Close with spectacle; buses from all real LGAs.", pts: 8, oppPts: 1, cost: 0.4, target: "all", your: 4, turnout: 5, risk: "Win-or-lose defining image." },
      { l: "🚪 Swing-LGA GOTV", days: 3, d: "Election-eve agents in " + swingZone.key + ".", pts: 6, oppPts: 0, cost: 0.15, target: swingZone.id, your: 6, turnout: 9, risk: "Neglects your base if turnout collapses elsewhere." },
      { l: "🗳️ Polling Unit Agents", days: 2, d: "Minimal agents across collation centres. Cheap but thin.", pts: 3, oppPts: 0, cost: 0.08, target: "all", your: 1, turnout: 2, corAdd: .01, risk: "Opponent may overpower weak wards." },
    ]];

    const oppEvts = [
      { t: "📰 Opponent Questions Your Credentials", d: oName + " attacks your qualifications in " + weakZone.key + ".", hit: { l: "credentials attack", target: weakZone.id, your: 4, opp: 3 }, opts: [
        { l: "📊 Publish Receipts", days: 2, dc: .02, d: "Counter with verifiable records and named community endorsers.", pts: 5, oppPts: -2, target: weakZone.id, your: 5, opp: -2 },
        { l: "🤫 Ignore", days: 1, d: "Stay above it. Costs a day of holding your team back.", pts: 0, oppPts: 3, target: weakZone.id, opp: 4 },
        { l: "⚔️ Attack Back", days: 3, d: "Dig up their failures.", pts: 3, oppPts: -3, target: "all", opp: -2, appRisk: -2 },
      ]},
      { t: "🎤 Opponent's Rally Outdraws Yours", d: oName + " fills a venue near " + swingZone.key + ". Momentum shifts.", hit: { l: "rally", target: swingZone.id, your: 2, opp: 6 }, opts: [
        { l: "🏟️ Organize a Bigger One", days: 2, d: "Outdo them. Costs money.", pts: 5, oppPts: -1, dc: .3, target: swingZone.id, your: 6, turnout: 3 },
        { l: "📱 Local Influencer Counter", days: 2, dc: 0.05, d: "Short videos from traders, students, religious youth.", pts: 4, oppPts: 0, target: swingZone.id, your: 4 },
        { l: "😤 Question Their Crowd", days: 1, d: "Claim they rented supporters.", pts: 2, oppPts: 1, target: "all", opp: 2 },
      ]},
      { t: "💀 Smear Campaign Against You", d: "Anonymous flyers spread across " + baseZone.key + ".", hit: { l: "smear", target: baseZone.id, your: 6, opp: 2, turnout: 2 }, opts: [
        { l: "📢 Immediate Press Conference", days: 2, d: "Deny publicly. Show your real plans.", pts: 6, oppPts: -2, target: "all", your: 2, opp: -2 },
        { l: "📋 Signed Market Pledge", days: 3, dc: 0.05, d: "Ward leaders distribute signed commitments.", pts: 5, oppPts: -1, target: baseZone.id, your: 6, opp: -1 },
        { l: "🤷 Let It Die Down", days: 1, d: "Assume voters won't believe it.", pts: 1, oppPts: 4, target: baseZone.id, opp: 5 },
      ]},
      { t: "🤝 Key Endorsement Goes to Opponent", d: "A major traditional ruler endorses " + oName + ".", hit: { l: "endorsement", target: "all", your: 1, opp: 4 }, opts: [
        { l: "📞 Secure Other Endorsements", days: 3, dc: 0.1, d: "Lock down chiefs and community heads.", pts: 4, oppPts: -2, target: "all", your: 2, opp: -2 },
        { l: "💪 People, Not Chiefs", days: 2, d: "Populist angle in youth-heavy LGAs.", pts: 5, oppPts: 0, target: swingZone.id, your: 5 },
        { l: "💰 Visit with Gifts", days: 2, dc: 0.12, d: "Show respect the old way.", pts: 3, oppPts: -1, target: weakZone.id, your: 4, opp: -1, corAdd: .01 },
      ]},
    ];

    const WEEK_DAYS = 6;
    const daysLeft = isOpp ? WEEK_DAYS - sCampDays : WEEK_DAYS;
    const optCost = (opt) => opt.cost || opt.dc || 0;
    const canTake = (opt) => optCost(opt) <= warChest + 1e-9;
    const zoneLabel = (t) => t === "all" || t === undefined ? "All zones" : (activeZones.find(z => z.id === t)?.zone || "").replace(" Senatorial", "") + " zone";

    const handleSC = (opt) => {
      const cost = optCost(opt);
      if (!canTake(opt)) return;
      setWarChest(w => Math.max(0, w - cost));
      setSCampDays(isOpp ? 0 : (opt.days || 1));
      const hm = level === "hard";
      // TOUGHER CAMPAIGNS: opponent gets a per-round bonus always, harsher on hard mode
      const yourPts = hm ? Math.max(opt.pts - 2, -3) : Math.max(opt.pts - 1, -2);
      const oppGain = (opt.oppPts || 0) + 1;
      setSCampScore(cs => cs + yourPts);
      setSCampOpp(co => co + oppGain);
      // Reduce your zone push, boost opponent zone drift; remember what moved each zone
      const moveName = opt.l.replace(/^[^\s]+ /, "");
      const sBoost = sloganDef(slogan)?.boost.test(opt.l) ? 2 : 0; // the slogan carries matching moves
      if (sBoost) setSCampLog(c => [...c, "📣 \u201c" + slogan + "\u201d carried " + moveName + " (+2)."]);
      // The adviser's pick is run with her ground game behind it: +2 where it lands.
      const aBoost = advisedPick.current === opt.l ? (level === "hard" ? 5 : 3) : 0;
      if (aBoost) setSCampLog(c => [...c, "⭐ " + (saName || "Your adviser") + "'s plan: her people ran " + moveName + " on the ground (+" + aBoost + ")."]);
      const before = activeZones;
      const after = shiftZones(before, opt.target ?? "all", Math.max(0, (opt.your || 0) - 1) + sBoost + aBoost, (opt.opp || 0) - 1, opt.turnout || 0)
        .map((z, i) => { const d = pollShare(z) - pollShare(before[i]); return d !== 0 ? { ...z, moves: [...(before[i].moves || []), { w: week, l: moveName, d }] } : z; });
      // Their move lands straight after yours, before you can answer it.
      const ev = !isOpp ? oppEvts[week - 1] : null;
      const strike = ev && ev.hit ? oppStrike(after, ev.hit, level, week) : null;
      setSCampZones(strike ? strike.zones : after);
      if (strike) setSCampOpp(co => co + strike.pts);
      if (opt.corAdd) setFavours(f => Math.round((f + opt.corAdd) * 1000) / 1000);
      if (opt.appRisk && Math.random() < (hm ? .65 : .55)) { setSCampScore(cs => cs - 4); setSCampLog(c => [...c, "⚠️ Backfire: the negative campaign cost you support (\u22124)."]); }
      setSCampLog(c => [...c, (opt.answer ? "↩️ " : "▶️ ") + "Week " + week + ": " + moveName + " · " + (cost > 0 ? "₦" + cost.toFixed(2) + "B" : "no money") + " · " + zoneLabel(opt.target)]);
      if (strike) setSCampLog(c => [...c, "🔻 " + oName.replace(/^Hon\. /, "") + "'s " + ev.hit.l + " cost you " + (strike.worstZone ? Math.abs(strike.worstD) + " points in " + strike.worstZone : "ground") + (strike.lost > 0 ? " (" + strike.lost + " statewide)" : "") + (week < 4 ? ". You can answer it next week." : ". There's no week left to answer it.")]);
      setSCampRound(r => r + 2);
    };
    // Nothing affordable this week: sit it out (costs the remaining days; the opponent gains ground)
    const sitOut = { l: "🪑 Sit this one out", d: "No money or time for anything better. The opponent gains ground everywhere.", days: Math.max(1, daysLeft), pts: 0, oppPts: 3, target: "all", opp: 3 };

    const makeGfEducationMandate = () => {
      const existing = gfMandates.find(m => m.type === "commissioner" && m.ministryId === "educ");
      if (existing) return existing;
      const r = rng(Date.now() + (st?.length || 1) * 191 + Math.round(gfDebt * 1000));
      return {
        id: "gf_edu_" + Date.now(),
        type: "commissioner",
        ministryId: "educ",
        ministryName: "Education",
        name: gN(r, STATES[st]?.zone, st),
        source: "godfather",
        reason: "first-election emergency campaign bailout",
      };
    };

    const addGfMandate = (mandate) => {
      setGfMandates(prev => prev.some(m => m.type === mandate.type && m.ministryId === mandate.ministryId) ? prev : [...prev, mandate]);
    };

    const restartElectionSetup = () => {
      setParty(null); setDepGov(null); setSlogan(null);
      setSCampRound(0); setSCampScore(0); setSCampOpp(0); setSCampLog([]); setSCampZones(null);
      setWarChest(0.8); setTicketPaid(0); setGfDebt(0); setFavours(0); setGfMandates([]); setPreTrib(null);
      setStep(4);
    };

    const borrowFromGF = () => {
      const amount = 0.8; // ₦800M from godfather
      if (gfLoans.some(l => l.key === "campaign")) return;
      setWarChest(w => w + amount);
      takeGfLoan("campaign", amount, "Campaign money when the war chest ran low");
      setSCampLog(c => [...c, "🎩 GODFATHER: Borrowed ₦" + amount + "B from political godfather. This money comes with strings."]);
    };

    const borrowFromGFWithMandate = () => {
      const amount = 0.6;
      if (gfLoans.some(l => l.key === "bailout")) return;
      const mandate = makeGfEducationMandate();
      addGfMandate(mandate);
      setWarChest(w => w + amount);
      takeGfLoan("bailout", amount, "Emergency bailout; his man becomes Education Commissioner");
      setSCampLog(c => [...c, "🎩 GODFATHER EMERGENCY BAILOUT: Borrowed ₦" + amount + "B. Condition accepted: " + mandate.name + " must become Commissioner for Education when ministries are convened."]);
    };

    if (isResult) {
      const hardMode = level === "hard";
      // Campaign efforts sway zone support before final collation
      // Seeded from the campaign itself, so the result does not change when the screen re-renders
      const eDay = rng((st?.length || 5) * 131 + sCampScore * 7 + sCampOpp * 13 + sCampLog.length * 29);
      const swayedZones = pollZones.map(z => {
        // Collation: noise plus a small party-machine push for the opponent (bigger on hard).
        // The campaign itself is now where they fight you, so the final poll is a fair guide.
        // window.SOP_TEST is set only by the automated playthroughs (tests/e2e), never by the game.
        const testSwing = window.SOP_TEST ? (window.SOP_TEST.win ? 40 : window.SOP_TEST.lose ? -40 : 0) : 0;
        const swing = (firstRun && !hardMode ? 2 : 0) + testSwing; // the campaign's points are already in the poll
        // Election-day noise is small: a player who leads the final poll should almost always win.
        const jitter = (eDay() - 0.5) * (hardMode ? 7 : 4);
        return { ...z, support: cl100(z.support + swing + jitter), opp: cl100(z.opp - swing * 0.4 + (hardMode ? 1 : .5) + (eDay() - 0.5) * (hardMode ? 5 : 3)) };
      });
      const collation = lgaElectionSummary(swayedZones, 1, 1, st); // party strength is already in the poll (buildBattlegrounds)
      const won = collation.won;
      const marginPct = collation.registeredTotal > 0 ? Math.abs(collation.margin) / (collation.totalYou + collation.totalOpp) * 100 : 0;
      const yourTicket = (lastNm || "SURNAME").toUpperCase() + "/" + (depGov?.nm.split(" ").pop() || "DEP").toUpperCase();
      return (
        <div style={{ minHeight: "100%", background: won ? "#f0fff0" : CL.bg, padding: TALL() ? "16px 18px 40px" : "36px 32px" }}>
            <div style={{ maxWidth: 984, margin: "8px auto", textAlign: "center" }}>
            <Sfx k={won ? "cheer" : "lose"} />{won ? <img src={"./art/scenes/" + (collation.runoff ? "second-election" : "declaration") + ".webp"} alt={collation.runoff ? "A second election" : "The Returning Officer declares the result"} style={{ display: "block", width: "100%", maxWidth: 520, aspectRatio: "16/9", objectFit: "cover", borderRadius: 18, margin: "0 auto 12px" }} /> : <ObjArt name="ballot-paper" alt="" size={TALL() ? 110 : 150} />}
            <h2 style={{ fontFamily: F.d, color: won ? CL.grn : CL.red, fontSize: TS(58), fontWeight: 700, margin: "7px 0" }}>{won ? "GOVERNOR-ELECT!" : "DEFEATED"}</h2>
            <p style={{ color: CL.tm, fontSize: TS(38), lineHeight: 1.4, marginBottom: 29 }}>{(won ? "The Returning Officer declares " + nm + " (" + party + ") duly elected, with the most votes and 25% or more in " + collation.you25 + " of " + collation.lgas.length + " local governments (" + collation.need + " needed). Margin: " + marginPct.toFixed(1) + "%." : oName + " (" + (oParty?.id || "OPP") + ") wins with the most votes and 25% or more in " + collation.opp25 + " of " + collation.lgas.length + " local governments. Margin against you: " + marginPct.toFixed(1) + "%.") + (collation.runoff ? " The leader missed the spread at first, so a second election was held between the two of you; the result held." : "")}</p>
            {!won && (() => {
              // A loss ends with one thing to try, not just a red screen.
              const sh = (rw) => rw.yourVotes / Math.max(1, rw.yourVotes + rw.oppVotes);
              const weak = collation.rows.reduce((a, b) => sh(b) < sh(a) ? b : a, collation.rows[0]);
              const behind = sCampOpp > sCampScore;
              return <div style={{ textAlign: "left", background: "#fff", border: "1px solid " + CL.bdr, borderRadius: 17, padding: "16px 20px", marginBottom: 18, fontSize: TS(30), color: CL.tm, lineHeight: 1.45 }}>
                <b style={{ color: CL.txt }}>Why:</b> {SYS.electionWhy(collation.rows, false)}<br />
                <b style={{ color: CL.txt }}>Next time:</b> {weak ? "you were weakest in the " + weak.zone + " district (" + Math.round(sh(weak) * 100) + "% of the vote). Spend more campaign days there. " : ""}{behind ? "The opponent's attacks outscored your campaign: answer them instead of sitting them out." : "Pick moves that match your slogan; they count for more."}{firstRun && level !== "easy" ? " Easy mode is a gentler first race." : ""}
              </div>;
            })()}
            {!won && <div style={{ display: "flex", gap: 22, justifyContent: "center", flexWrap: "wrap", marginBottom: 36, padding: "29px", background: "#fff8f0", border: "1px solid " + CL.gold + "55", borderRadius: 17 }}>
              <Bt onClick={() => { setSCampRound(0); setSCampScore(0); setSCampOpp(0); setSCampLog([]); setSCampZones(null); setEnightPlayed({}); setEnightSummary(null); setWarChest(0.8); setGfDebt(0); setFavours(0); setGfMandates([]); setStep(8); }} style={{ padding: "29px 50px", fontSize: TS(38) }}>😔 Try Again</Bt>
              <Bt onClick={() => {
                const zonesWon = collation.zonesWon;
                const marginPts = Math.round(marginPct * 10) / 10;
                const evBase = Math.max(15, 65 - Math.round(marginPct * 1.6) + zonesWon * 8 + (sCampLog.some(l => l.includes("Polling Unit")) ? 6 : 0));
                setPreTrib({
                  level: 0, spent: 0, groundId: null,
                  oppName: oName, oppPartyId: oParty?.id || "OPP",
                  margin: marginPts, zonesWon,
                  evidence: Math.min(85, evBase),
                  log: ["Filed within 21 days (S.285(5)). Case GET/" + Math.floor(Math.random() * 900 + 100) + "/" + new Date().getFullYear() + "."]
                });
                setStep(85);
              }} style={{ padding: "29px 50px", fontSize: TS(38), background: CL.gold, color: "#000" }}>⚖️ Petition Tribunal</Bt>
            </div>}
            <details className="sp-brief" style={{ textAlign: "left", margin: "0 0 22px" }}><summary style={{ fontSize: 17 }}>See the full count</summary>
            <Cd style={{ textAlign: "left", marginBottom: 29 }}>
              <div style={{ fontSize: TS(31), fontWeight: 700, color: CL.pur, fontFamily: F.m, marginBottom: 14, letterSpacing: 2 }}>HOW THE ZONES MOVED</div>
              {(() => { const start = buildBattlegrounds(st, 2026, party, oParty?.id).map((z, i) => ({ ...z, support: cl100(z.support + (ticketFx[i] || 0)) })); return collation.rows.map((rw, i) => {
                const s0 = pollShare(start[i] || rw), s1 = pollShare(activeZones[i] || rw);
                const res = rw.yourVotes + rw.oppVotes > 0 ? Math.round(1000 * rw.yourVotes / (rw.yourVotes + rw.oppVotes)) / 10 : 50;
                const moves = (activeZones[i]?.moves || []).filter(m => m.d !== 0);
                return <div key={rw.id} style={{ padding: "14px 0", borderBottom: "1px solid " + CL.bdr + "66" }}>
                  <div style={{ display: "flex", justifyContent: "space-between", fontSize: TS(33), color: CL.txt }}><b>{rw.zone.replace(" Senatorial", "")}</b><span style={{ fontFamily: F.m, color: rw.won ? CL.grn : CL.red }}>{rw.won ? "Won" : "Lost"}</span></div>
                  <div style={{ fontSize: TS(30), color: CL.tm, fontFamily: F.m, margin: "4px 0" }}>Start {s0}% → final poll {s1}% ({sgnN(s1 - s0)}) → result {res}%</div>
                  {moves.length ? <div style={{ fontSize: TS(28), color: CL.td, lineHeight: 1.35 }}>{moves.map(m => m.l + " " + sgnN(m.d)).join(" · ")}</div>
                    : <div style={{ fontSize: TS(28), color: CL.td }}>You never campaigned here directly.</div>}
                </div>; }); })()}
            </Cd>
            <SceneArt bg="collation-centre" h={TALL() ? 180 : 240} />
            <Cd style={{ textAlign: "left", marginBottom: 36, background: "#fffef7", borderColor: CL.gold + "55" }}>
              <img src="./art/backgrounds/collation-board-lga.webp" alt="The collation board" style={{ display: "block", width: "100%", aspectRatio: "16/9", objectFit: "cover", borderRadius: 14, marginBottom: 14 }} />
              <ObjArt name="result-sheet-blank" alt="" size={TALL() ? 70 : 90} />
              <div style={{ fontSize: TS(31), fontWeight: 700, color: CL.grn, fontFamily: F.m, marginBottom: 22, textAlign: "center", letterSpacing: 2 }}>INEC · FORM EC8D · FINAL COLLATED RESULT</div>
              <div style={{ fontSize: TS(34), color: CL.txt, textAlign: "center", marginBottom: 29, borderBottom: "1px solid " + CL.bdr, paddingBottom: 22 }}><b>Governorship Election — {st.replace("_", " ")} State</b><br/>Registered Voters: <b>{fmtVotesFull(collation.registeredTotal)}</b> · Total Cast: <b>{fmtVotesFull(collation.totalYou + collation.totalOpp)}</b></div>
              {collation.rows.map(rw => <div key={rw.id} style={{ padding: "22px 0", borderBottom: "1px solid " + CL.bdr + "66" }}>
                <div style={{ display: "flex", justifyContent: "space-between", fontSize: TS(36), color: CL.txt, marginBottom: 7 }}><b>{rw.zone}</b><span style={{ color: rw.won ? CL.grn : CL.red, fontFamily: F.m }}>{rw.won ? party + " ✓" : (oParty?.id || "OPP") + " ✓"}</span></div>
                <div style={{ display: "flex", justifyContent: "space-between", fontSize: TS(34), color: CL.tm, fontFamily: F.m }}>
                  <span>{yourTicket}: <b style={{ color: rw.won ? CL.grn : CL.txt }}>{fmtVotesFull(rw.yourVotes)}</b></span>
                  <span>OPP: <b style={{ color: !rw.won ? CL.red : CL.txt }}>{fmtVotesFull(rw.oppVotes)}</b></span>
                </div>
                <div style={{ fontSize: TS(29), color: CL.td, marginTop: 7 }}>Turnout: {rw.turnout}% · {rw.names.length} LGAs: {rw.names.join(", ")}</div>
              </div>)}
              <div style={{ marginTop: 29, padding: "29px 36px", background: (won ? CL.grn : CL.red) + "12", borderRadius: 13, textAlign: "center" }}>
                <div style={{ fontSize: TS(34), color: CL.td, fontFamily: F.m, marginBottom: 7 }}>STATE TOTAL</div>
                <div style={{ fontSize: TS(48), color: CL.txt, fontFamily: F.m, fontWeight: 700 }}>
                  <span style={{ color: won ? CL.grn : CL.txt }}>{yourTicket}: {fmtVotesFull(collation.totalYou)}</span>
                  <span style={{ margin: "0 29px", color: CL.td }}>vs</span>
                  <span style={{ color: !won ? CL.red : CL.txt }}>OPP: {fmtVotesFull(collation.totalOpp)}</span>
                </div>
                <div style={{ fontSize: TS(31), color: CL.tm, marginTop: 7 }}>Margin: {fmtVotesFull(Math.abs(collation.margin))} votes ({marginPct.toFixed(2)}%)</div>
              </div>
            </Cd>
            {won && gfDebt > 0 && <Cd style={{ borderColor: CL.red + "44", marginBottom: 29, textAlign: "left" }}>
              <div style={{ fontSize: TS(34), fontWeight: 700, color: CL.red, fontFamily: F.m, marginBottom: 10 }}>🎩 GODFATHER DEBT: {SYS.fmtB(gfDebt)}</div>
              <div style={{ fontSize: TS(34), color: CL.tm }}>You borrowed {SYS.fmtB(gfDebt)} from your political godfather ({gfLoans.map(l => SYS.fmtM(l.amountM) + " · " + l.reason.toLowerCase()).join("; ")}). It is your personal debt, not the state's. He WILL come collecting. You start governance with +{Math.round(gfDebt * 5)}% corruption and the godfather expects contracts, land, and positions. Refuse him at your peril.</div>
            </Cd>}
            <Cd style={{ textAlign: "left", marginBottom: 36 }}>
              <div style={{ fontSize: TS(31), fontWeight: 700, color: CL.pur, fontFamily: F.m, marginBottom: 10 }}>CAMPAIGN LOG</div>
              {sCampLog.map((c2, i) => <div key={i} style={{ fontSize: TS(34), color: c2.includes("BACKFIRE") || c2.includes("GODFATHER") ? CL.red : CL.tm, padding: "5px 0" }}>{c2}</div>)}
            </Cd>
            </details>
            <div style={{ fontSize: TS(34), color: CL.td, marginBottom: 22 }}>Campaign funds remaining: ₦{warChest.toFixed(1)}B</div>
            {won ? <Bt onClick={() => { setElection({ opp: oName, oppParty: oParty?.id || "OPP", zonesWon: collation.zonesWon, marginPct: Math.round(marginPct * 10) / 10, votes: collation.totalYou, oppVotes: collation.totalOpp }); setSCampRound(0); setStep(9); }} style={{ padding: "43px 113px" }}>PROCEED TO GOVERNMENT HOUSE →</Bt>
              : null}
          </div>
        </div>
      );
    }

    const opts = weekPicks(mkActs()[week - 1], week > 1 ? (oppEvts[week - 2] || {}).opts : null, canTake, sitOut);
    const tall = TALL(), fz = campFz();
    return (
      <div style={{ minHeight: "100%", background: CL.bg, padding: tall ? "14px 16px 40px" : "28px 32px" }}>
        <div style={{ maxWidth: tall ? 980 : 1440, margin: "0 auto" }}>
          <CampaignBoard week={week} isOpp={isOpp} youImg={AVATAR_IMGS[avatar] || HERO_MALE} youName={lastNm || "You"} youParty={party} oppName={oName.replace(/^Hon\. /, "").split(" ").pop()} oppParty={oParty?.id || "OPP"} oppImg={oppArt(oName)}
            zones={pollZones} swingId={swingZone.id} money={warChest} days={daysLeft} maxDays={WEEK_DAYS} gfDebt={gfDebt} slogan={slogan} lastLog={sCampLog.length ? sCampLog[sCampLog.length - 1] : null} ev={isOpp ? oppEvts[Math.floor(sCampRound / 2)] : null} />

          {/* Money trouble */}
          {!isOpp && warChest < 0.2 && !gfBorrowed && level !== "easy" && <Cd onClick={borrowFromGF} style={{ padding: tall ? 14 : 20, borderColor: CL.red + "44", marginBottom: 12 }}>
            <div style={{ fontSize: fz.m, fontWeight: 700, color: CL.red }}>🎩 Borrow ₦0.8B from the godfather</div>
            <div style={{ fontSize: fz.s, color: CL.td }}>The debt follows you into office, and he will collect.</div>
          </Cd>}
          {!isOpp && warChest < 0.09 && gfBorrowed && level !== "easy" && <Cd style={{ padding: tall ? 14 : 22, borderColor: CL.red + "55", marginBottom: 12, background: "#fff7f2" }}>
            <div style={{ fontSize: fz.m, fontWeight: 800, color: CL.red, marginBottom: 8 }}>💸 The money has run out</div>
            <div style={{ display: "grid", gap: 10 }}>
              <Bt onClick={borrowFromGFWithMandate} style={{ background: CL.gold, color: "#000", fontSize: fz.s }}>🎩 Borrow ₦0.6B: his man becomes Education Commissioner</Bt>
              <Bt onClick={() => {
                const win = Math.random() < 0.20;
                if (win) { setSCampScore(sc => sc + 100); setSCampLog(c => [...c, "🙏 Ran broke — a volunteer miracle carried market women, youth organisers and ward canvassers without cash."]); }
                else { setSCampOpp(op => op + 100); setSCampLog(c => [...c, "💸 Ran broke — no mobilisation, no agents, no final rally. Opponent swept the collation centres."]); }
                setSCampRound(8);
              }} style={{ background: CL.org, fontSize: fz.s }}>🎲 Run with no money (1 in 5 chance)</Bt>
              <Bt v="danger" onClick={() => { setSCampRound(8); setSCampScore(sc => sc - 60); setSCampOpp(op => op + 80); setSCampLog(c => [...c, "🏳️ Withdrew after campaign funds collapsed. Party structures moved to the opponent."]); }} style={{ fontSize: fz.s }}>🏳️ Withdraw</Bt>
            </div>
          </Cd>}

          {(() => { const adv = SYS.campaignAdvice({ zones: pollZones, week, picks: opts.filter(o => o !== sitOut), ok: canTake, isOpp }); if (!adv) return null;
            // The adviser comes when called: Consult brings her forward with her advice, and she can act on it for you.
            const best = adv.pick && opts.find(o => o.l === adv.pick); advisedPick.current = consulted === sCampRound ? adv.pick : null;
            const consult = () => { setConsulted(sCampRound); advisedPick.current = adv.pick; track("camp_advice", "consulted"); try { window.SOP_outcome && window.SOP_outcome({ present: { img: saPose(saName, adv.mood === "worried" ? "worried" : adv.mood === "pleased" ? "pleased" : "neutral") || saPortrait(saName), name: (saName || "Your adviser") + " · Special Adviser", text: adv.say, ok: best ? "Do it: " + adv.name : "Understood", fn: best ? () => { track("camp_advice", "followed"); handleSC(best); } : undefined, alt: best ? "I'll choose myself" : undefined } }); } catch (e) {} };
            return <ConsultButton saName={saName} onClick={consult} />; })()}
          <div style={{ display: "grid", gridTemplateColumns: tall ? "1fr" : "repeat(auto-fit, minmax(400px, 1fr))", gap: 14 }}>
            {(() => { const adv = SYS.campaignAdvice({ zones: pollZones, week, picks: opts.filter(o => o !== sitOut), ok: canTake, isOpp }); return opts.map((opt, i) => { const ok = opt === sitOut || canTake(opt); const cost = optCost(opt);
              return <CampaignMove key={i} opt={{ ...opt, zoneLabel: zoneLabel(opt.target) }} ok={ok} why={cost > warChest + 1e-9 ? "Not enough money" : ""} boosted={sloganDef(slogan)?.boost.test(opt.l)} advised={consulted === sCampRound && !!adv && adv.pick === opt.l} onPick={() => handleSC(opt)} />; }); })()}
          </div>
          <div style={{ textAlign: "center", marginTop: 18 }}><button onClick={restartElectionSetup} style={{ background: "none", border: 0, color: CL.td, fontSize: fz.s, textDecoration: "underline", cursor: "pointer", fontFamily: F.b }}>Restart election setup</button></div>
        </div>
      </div>
    );
  }

  // STEP 85: ELECTION TRIBUNAL BEFORE TAKING OFFICE (first-election defeat only)
  if (step === 85 && preTrib) {
    // The godfather's terms for funding the petition (same as the campaign bailout).
    const makeGfEducationMandate = () => {
      const existing = gfMandates.find(m => m.type === "commissioner" && m.ministryId === "educ");
      if (existing) return existing;
      return { id: "gf_edu_" + Date.now(), type: "commissioner", ministryId: "educ", ministryName: "Education", name: gN(rng(Date.now() + (st?.length || 1) * 191), STATES[st]?.zone, st), source: "godfather", reason: "tribunal petition funding" };
    };
    const addGfMandate = (mandate) => setGfMandates(prev => prev.some(m => m.type === mandate.type && m.ministryId === mandate.ministryId) ? prev : [...prev, mandate]);
    const LVLS = [
      { nm: "Governorship Election Tribunal", tag: "Up to 180 days to judgment", winBonus: 0, appealCost: 0.6 },
      { nm: "Court of Appeal", tag: "60 days to rule", winBonus: 8, appealCost: 1.2 },
      { nm: "Supreme Court", tag: "Final: no further appeal", winBonus: 15, appealCost: 0 },
    ];
    const GROUNDS = [
      { id: "over_voting", nm: "Over-voting", desc: "More votes than accredited voters in " + (3 - preTrib.zonesWon) + " zone" + (3 - preTrib.zonesWon === 1 ? "" : "s") + ".", base: 0.42, req: "EC8A sheets and BVAS printouts" },
      { id: "corrupt", nm: "Vote buying by " + preTrib.oppName.split(" ").pop(), desc: "Cash at collation centres (S.121, Electoral Act 2022).", base: 0.36, req: "Affidavits from 12 agents, and video" },
      { id: "qual", nm: "Opponent not qualified (S.177)", desc: "Doubts over " + preTrib.oppName.split(" ").pop() + "'s certificates.", base: 0.30, req: "Certified certificates and Form EC9" },
      { id: "return", nm: "Not a majority of lawful votes", desc: "Cancelled units change the result.", base: 0.48, req: "Reconciled EC8B and EC8C forms" },
    ];
    const lvl = LVLS[preTrib.level];
    const gd = GROUNDS.find(g => g.id === preTrib.groundId);

    const runHearing = (mode) => {
      const cost = mode === "self" ? 0.2 : mode === "sans" ? 1.2 : mode === "wig" ? 3.5 : 5;
      if (warChest < cost && mode !== "self") {
        setPreTrib(t => ({ ...t, log: [...t.log, "❌ Not enough money for that team."] }));
        try { window.SOP_outcome && window.SOP_outcome({ icon: "💼", title: "Not enough money for this team", text: "You have ₦" + warChest.toFixed(2) + "B; they want ₦" + cost + "B. Argue in person, or borrow from the godfather.", tone: "bad" }); } catch (e) {}
        return;
      }
      setWarChest(w => Math.max(0, w - cost));
      const modeBonus = mode === "self" ? -0.10 : mode === "sans" ? 0.10 : mode === "wig" ? 0.22 : 0.35;
      const evAdj = (preTrib.evidence - 50) / 200; // -0.175 to +0.175
      const lvlBonus = lvl.winBonus / 100;
      const chance = Math.min(0.9, Math.max(0.05, gd.base + modeBonus + evAdj + lvlBonus));
      const roll = Math.random();
      const won = roll < chance;
      const logLine = (won ? "✅ " : "❌ ") + lvl.nm + " · " + (mode === "self" ? "in person" : mode === "sans" ? "a SAN" : mode === "wig" ? "a SAN team" : "a 'settled' panel") + " · odds " + Math.round(chance * 100) + "%";
      const nextLog = [...preTrib.log, logLine];
      // Every ruling is announced, not just logged.
      const court = lvl.nm, nextCourt = LVLS[preTrib.level + 1] ? LVLS[preTrib.level + 1].nm : null, opp = preTrib.oppName;
      const final = won ? (preTrib.level >= 2 || (preTrib.level === 0 && chance > 0.7 && roll < 0.25)) : preTrib.level >= 2;
      try { window.SOP_sound && window.SOP_sound("gavel"); } catch (e) {}
      try { window.SOP_outcome && window.SOP_outcome(won
        ? (final ? { icon: "⚖️", img: "./art/scenes/news-victory-rally.webp", title: "Petition upheld: you are Governor", text: "The " + court + " nullified " + opp + "'s return. You will be sworn in.", tone: "good" }
          : { icon: "⚖️", img: "./art/scenes/news-court-steps.webp", title: "You won at the " + court, text: opp + " has appealed. Next stop: the " + nextCourt + ".", tone: "good" })
        : (final ? { icon: "⚖️", img: "./art/backgrounds/supreme-court-abuja.webp", title: "Supreme Court: petition dismissed", text: "This is final. " + opp + " stays Governor.", tone: "bad" }
          : { icon: "⚖️", img: "./art/scenes/news-court-steps.webp", title: "You lost at the " + court, text: "You have appealed. Next stop: the " + nextCourt + ".", tone: "bad" })); } catch (e) {}
      if (won) {
        if (preTrib.level >= 2 || (preTrib.level === 0 && chance > 0.7 && roll < 0.25)) {
          // Reinstated
          setTimeout(() => { try { window.SOP_sound && window.SOP_sound("cheer"); } catch (e) {} }, 900);
          setPreTrib(t => ({ ...t, log: [...nextLog, "🏛️ Petition upheld: you are declared winner."], reinstated: true, spent: t.spent + cost }));
        } else {
          setPreTrib(t => ({ ...t, level: t.level + 1, groundId: null, log: [...nextLog, "They appealed: on to the " + LVLS[t.level + 1].nm + "."], spent: t.spent + cost }));
        }
      } else {
        if (preTrib.level >= 2) {
          setPreTrib(t => ({ ...t, log: [...nextLog, "⚖️ Dismissed by the Supreme Court. Final."], dismissed: true, spent: t.spent + cost }));
        } else {
          setPreTrib(t => ({ ...t, level: t.level + 1, groundId: null, log: [...nextLog, "You appealed: on to the " + LVLS[t.level + 1].nm + "."], spent: t.spent + cost }));
        }
      }
    };

    const quit = () => { setPreTrib(null); setSCampRound(0); setSCampScore(0); setSCampOpp(0); setSCampLog([]); setSCampZones(null); setEnightPlayed({}); setEnightSummary(null); setWarChest(0.8); setGfDebt(0); setFavours(0); setGfMandates([]); setStep(8); };
    const owesEdu = gfMandates.some(m => m.type === "commissioner" && m.ministryId === "educ");
    const borrow = () => {
      const amt = 2, k = "petition" + gfLoans.filter(l => /^petition/.test(l.key)).length;
      if (owesEdu) {
        setWarChest(w => w + amt); takeGfLoan(k, amt, "Legal fees for the election petition");
        setPreTrib(t => ({ ...t, log: [...t.log, "🎩 Godfather lent ₦" + amt + "B. He'll want contracts."] }));
        return;
      }
      const mandate = makeGfEducationMandate();
      addGfMandate(mandate); setWarChest(w => w + amt);
      takeGfLoan(k, amt, "Legal fees for the election petition; Education Commissioner condition");
      setPreTrib(t => ({ ...t, log: [...t.log, "🎩 Godfather lent ₦" + amt + "B. Price: " + mandate.name + " as Education Commissioner."] }));
    };
    const endCard = (good) => <Cd style={{ maxWidth: 760, margin: "0 auto", borderColor: good ? CL.grn : CL.red, background: good ? "#f0fff0" : "#fff5f5", textAlign: "center", padding: TALL() ? 22 : 40 }}>
      <img src={good ? "./art/scenes/news-victory-rally.webp" : "./art/backgrounds/supreme-court-abuja.webp"} alt="" style={{ width: "100%", borderRadius: 14, display: "block" }} />
      <h3 style={{ color: good ? CL.grn : CL.red, fontFamily: F.d, fontSize: TS(TALL() ? 40 : 60), margin: "14px 0 6px" }}>{good ? "Petition upheld" : "Petition dismissed"}</h3>
      <p style={{ color: CL.tm, fontSize: TS(TALL() ? 24 : 34), lineHeight: 1.45, margin: "0 0 14px" }}>{good ? preTrib.oppName + "'s return is nullified. You are Governor of " + st.replace("_", " ") + "." : "Final. You spent ₦" + preTrib.spent.toFixed(1) + "B and lost."}</p>
      {good ? <Bt onClick={() => { setPreTrib(null); setStep(9); }}>🏛️ To Government House →</Bt> : <Bt onClick={quit}>Try again</Bt>}
    </Cd>;
    return (
      <div style={{ minHeight: "100%", background: CL.bg, padding: TALL() ? "12px 16px 40px" : "28px 32px" }}>
        {preTrib.reinstated ? endCard(true) : preTrib.dismissed ? endCard(false) : <CourtScreen level={preTrib.level} court={lvl.nm} tag={lvl.tag}
          facts={[["Lost by", preTrib.margin + "%"], ["Zones", preTrib.zonesWon + "/3"], ["Evidence", preTrib.evidence + "%", preTrib.evidence <= 35], ["War chest", "₦" + warChest.toFixed(2) + "B", warChest < 1.2]]}
          ground={gd} grounds={GROUNDS} onGround={id => setPreTrib(t => ({ ...t, groundId: id }))}
          modes={[{ id: "self", ic: "👨🏾‍💼", l: "Argue it yourself", cost: 0.2, odds: -10 }, { id: "sans", ic: "📚", l: "A Senior Advocate", cost: 1.2, odds: 10 }, { id: "wig", ic: "🎓", l: "A SAN-led team", cost: 3.5, odds: 22 }, warChest >= 5 && { id: "bribe", ic: "💼", l: "\u201cSettle\u201d the panel", d: "Corruption. It can surface later.", cost: 5, odds: 35, tone: "bad" }]}
          onMode={runHearing} fund={warChest}
          extra={warChest < 3.5 && (gfDebt < 6 ? <Bt onClick={borrow} style={{ background: CL.gold, color: "#000" }}>🎩 Borrow ₦2B · {owesEdu ? "he wants contracts" : "he picks a commissioner"}</Bt>
            : <div style={{ fontSize: TS(24), color: CL.red, textAlign: "center" }}>🎩 No more loans: you owe ₦{gfDebt.toFixed(1)}B.</div>)}
          onWithdraw={quit} log={preTrib.log} />}
      </div>
    );
  }

  if (step === 9) {
    const partyFav = depCands.find(c => c.partyFav) || depCands[0];
    const accepted = depGov?.nm === partyFav.nm;
    const deal = SYS.PARTY_REACTION.find(o => o.id === partyDeal);
    const startingStab = accepted ? SYS.PARTY_ACCEPTED.pStab : (deal ? deal.pStab : 66);
    // The party's price for passing over its candidate, carried into office.
    const partyMandates = !accepted && deal && deal.mandate ? [{ ...deal.mandate, name: gN(rng(st.length * 991), STATES[st]?.zone, st) }] : [];
    if (!anchorsShown) {
      const stNm = (st || "").replace("_", " ");
      const pt = PARTIES.find(p => p.id === party);
      const anchorLines = [
        { who: "m", t: "Good evening. You're watching the State House Report, live from " + stNm + " State — and it's official: we have a new Governor-elect." },
        { who: "f", t: "That's right, " + ANCHORS.m.first + ". INEC has returned " + (nm || "the candidate") + " of the " + (pt?.id || "party") + " as duly elected Governor of " + stNm + " State" + (slogan ? ", after a campaign fought on the slogan ‘" + slogan + "’." : ".") },
        { who: "m", t: (FLAGSHIP[agenda] ? "The Governor-elect has promised to make " + FLAGSHIP[agenda].nm + " the centrepiece: to " + FLAGSHIP[agenda].goal + ". " : "") + "Now the hard part begins. Empty treasury, restless unions, and a godfather who remembers every favour." },
        { who: "f", t: "The swearing-in is done, the convoy is moving. Governor, Government House is waiting for you." },
      ];
      return <AnchorDesk lines={anchorLines} onDone={() => setAnchorsShown(true)} />;
    }
    return (
      <div style={{ minHeight: "100%", background: "linear-gradient(180deg,#f0f5e8,#fafdf7)", padding: TALL() ? "16px 18px 40px" : "36px 32px" }}>
        <div style={{ maxWidth: 912, margin: "120px auto", textAlign: "center" }}>
          <SceneArt bg="government-house" h={TALL() ? 220 : 300} />
          {/* The arrival: your portrait, your new title, the mandate you won. */}
          <img src={AVATAR_IMGS[avatar]} alt={nm} className="sop-pop" style={{ width: TALL() ? 110 : 150, height: TALL() ? 140 : 190, objectFit: "cover", objectPosition: "top", borderRadius: 24, border: "5px solid #fff", boxShadow: "0 12px 30px rgba(18,48,31,.28)", margin: TALL() ? "-70px auto 10px" : "-90px auto 14px", display: "block", position: "relative", background: UI.tints[3], ...frameStyle() }} />
          <div style={{ fontSize: TS(TALL() ? 26 : 32), letterSpacing: 2, textTransform: "uppercase", color: CL.td, fontWeight: 800 }}>Executive Governor of {(st || "").replace("_", " ")} State</div>
          <h2 style={{ fontFamily: F.d, color: CL.grn, fontSize: TS(94), fontWeight: 700, margin: "4px 0 10px" }}>Welcome to Government House</h2>
          {election && <div style={{ fontSize: TS(32), color: CL.tm, margin: "0 0 30px" }}>{Number(election.votes || 0).toLocaleString()} votes · {election.zonesWon} of 3 districts · won by {election.marginPct}%</div>}
          <AdvBubble text={ADV.govHouse(nm, st, saName, FLAGSHIP[agenda])} saName={saName} />
          <div style={{ marginTop: 58 }}>
              <Bt onClick={() => { try { window.storage && window.storage.set(PLAYED_KEY, "1"); } catch (e) {} track("state", st); track("party", party); track("agenda", agenda); track("adviser", saName); track("level", level); track("deputy", accepted ? "party's pick (unity)" : "own pick"); track("runs_at_home", profile && profile.origin === st ? "yes" : "no"); track("quick_start", quickUsed ? "used" : "not used"); if (legacy) track("honour_carried", legacy); onDone({ legacy, nm: nm.trim(), firstNm: firstNm.trim(), lastNm: lastNm.trim(), party, state: st, depGov, avatar, agenda, slogan, saName, partyAccepted: accepted, startingStab, gfDebt, gfLoans, favours, gfMandates: [...gfMandates, ...partyMandates], homeDistrict: homeDistrict == null ? 1 : homeDistrict, homeLga: homeLga || (lgaCluster(getLGAs(st), homeDistrict == null ? 1 : homeDistrict)[0] || null), partyDeal: accepted ? "accepted" : partyDeal, partyPromise: !accepted && deal && deal.promise ? deal.promise : null, level, warChestRemaining: warChest, election, customParty: customParty && customParty.id === party ? customParty : null, ...(mode && mode.kind === "comeback" ? { comeback: { team: mode.team || null, terms: 1 }, startYear: (mode.startYear || 2027) + 4 } : {}) }); }} style={{ padding: "50px 127px", fontSize: TS(53) }}>
              BEGIN YOUR TENURE →
            </Bt>
          </div>
        </div>
      </div>
    );
  }

  return null;
};

// ─── HOUSE OF ASSEMBLY VOTE ───
// ─── BILLS YOU CAN SPONSOR ───
const BILLS = [
  { id: "land_reform", nm: "Land Reform Bill", d: "Streamline Certificate of Occupancy process. Reduces corruption in land allocation.", fx: { corM: -.04, app: 4 }, sk: { business: 8, traditional: -6 }, cost: 0 },
  { id: "edu_compulsory", nm: "Compulsory Education Bill", d: "Make 9 years of education mandatory with penalties for non-compliance.", fx: { lit: .03, app: 3 }, sk: { religious: -4, youth: 8 }, cost: 0.5 },
  { id: "fiscal_resp", nm: "Fiscal Responsibility Bill", d: "Cap state borrowing at 50% of IGR. Forces discipline.", fx: { corM: -.03, app: 2 }, sk: { business: 6, party: -5 }, cost: 0 },
  { id: "market_mod", nm: "Market Modernization Bill", d: "Regulate and upgrade state markets with trader protections.", fx: { app: 5 }, sk: { business: 10, unions: 5 }, cost: 1.5 },
  { id: "env_protect", nm: "Environmental Protection Bill", d: "Create state environmental agency with enforcement powers.", fx: { hp: .02, app: 3 }, sk: { business: -5, youth: 6 }, cost: 0.5 },
  { id: "youth_employ", nm: "Youth Employment Bill", d: "Mandate state agencies to reserve 30% of new positions for under-35s.", fx: { app: 6 }, sk: { youth: 12, unions: -4 }, cost: 1 },
  { id: "open_grazing", nm: "Anti-Open Grazing Law", d: "Ranching only; cattle may not roam farms. Ends most farmer–herder clashes, angers herders' groups.", fx: { sec: .04, app: 4 }, sk: { traditional: -4, religious: -3 }, cost: .5 },
  { id: "vapp", nm: "Violence Against Persons (Prohibition) Law", d: "Domesticates the federal VAPP Act: rape, domestic violence and harmful widowhood rites become crimes.", fx: { app: 3, hp: .01 }, sk: { religious: -4, youth: 6, media: 5 }, cost: 0 },
  { id: "procurement_law", nm: "Public Procurement Law", d: "A procurement bureau, open tenders and published contracts. Contractors hate it.", fx: { corM: -.05, app: 2 }, sk: { business: 4, party: -6 }, cost: .3 },
  { id: "foi", nm: "Freedom of Information Law", d: "Anyone can request government records within seven days.", fx: { corM: -.02, app: 2 }, sk: { media: 10, party: -3 }, cost: 0 },
  { id: "child_rights", nm: "Child Rights Law", d: "Bans child marriage and street hawking by children. Some clerics object.", fx: { lit: .02, app: 2 }, sk: { religious: -6, youth: 4 }, cost: .3 },
  { id: "pension", nm: "Contributory Pension Law", d: "Moves workers to funded pensions; ends the arrears that pile up on retirees.", fx: { app: 3 }, sk: { unions: 6 }, cost: 1.2 },
  { id: "tenancy", nm: "Tenancy Law", d: "Caps advance rent at one year and stops arbitrary evictions.", fx: { app: 4 }, sk: { business: -5, youth: 6 }, cost: 0 },
];
// Lawful executive orders: quick, cheap, immediate, and each has a price.
// risk: chance of a backlash (fx2) when you sign. Once per term each.
const ORDERS = [
  { id: "sanitation", i: "🧹", nm: "Monthly sanitation day", d: "Everyone stays home to clean up on the last Saturday of the month.", fx: { hp: .02, app: -1 }, sk: { business: -3 } },
  { id: "curfew", i: "🌙", nm: "Dusk-to-dawn curfew in hotspot areas", d: "Troops and police enforce it. Fewer attacks; trade suffers.", fx: { sec: .04, app: -2 }, sk: { business: -4 }, need: "security" },
  { id: "okada", i: "🛺", nm: "Ban okada in the state capital", d: "Motorcycle taxis off city roads. Safer streets; thousands of riders lose work.", fx: { sec: .02, app: -2 }, sk: { youth: -8 }, risk: { p: .3, fx: { app: -2 }, log: "Okada riders blocked the city's main roads in protest." } },
  { id: "street_trading", i: "🚫", nm: "Ban street trading on major roads", d: "Clears traffic; traders lose their pitches.", fx: { infra: .01, app: -2 }, sk: { unions: -4, business: 2 } },
  { id: "emerg_health", i: "🏥", nm: "State of emergency in health", d: "Fast-track drugs and staff, skipping normal procurement.", fx: { hp: .025, app: 2, corM: .01 }, sk: {} },
  { id: "emerg_edu", i: "🎓", nm: "State of emergency in education", d: "Emergency teacher hiring and classroom repairs.", fx: { lit: .025, app: 2, corM: .01 }, sk: { unions: 3 } },
  { id: "hiring_freeze", i: "🧊", nm: "Freeze civil service hiring", d: "Saves money on the wage bill; graduates and unions are angry.", fx: { app: -2 }, rev: .4, sk: { unions: -6, youth: -4 } },
  { id: "min_wage", i: "💵", nm: "Pay the new minimum wage now", d: "Workers get the federal minimum wage from this month.", fx: { app: 5 }, rev: -.6, sk: { unions: 12 } },
  { id: "four_day", i: "📆", nm: "Four-day week for civil servants", d: "Relief from transport costs; services slow down.", fx: { app: 2 }, sk: { unions: 6, business: -3 } },
  { id: "open_grazing_eo", i: "🌾", nm: "Order: no open grazing", d: "Bans cattle on farmland until the House passes a law.", fx: { sec: .03, agr: .01, app: 3 }, sk: { traditional: -3 }, risk: { p: .25, fx: { app: -2, pStab: -2 }, log: "Herders' groups went to court and Abuja criticised the order." } },
  { id: "revoke_land", i: "📃", nm: "Revoke your predecessor's land allocations", d: "Takes back plots handed to cronies. Popular, and it will be challenged.", fx: { app: 3, corM: -.01 }, sk: { traditional: -5, business: -3 }, risk: { p: .35, fx: { app: -2 }, log: "The former allottees won an injunction; some plots are back in court." } },
  { id: "close_schools", i: "🔒", nm: "Close schools in bandit-hit areas", d: "Keeps children safe; they fall behind.", fx: { sec: .02, lit: -.02, app: -1 }, sk: { religious: 2 }, need: "security" },
];
// Plain names for effect chips.
const FX_NAME = { app: "Approval", corM: "Corruption", cor: "Corruption", lit: "Education", hp: "Health", sec: "Security", infra: "Infrastructure", agr: "Agriculture", pStab: "Party" };
const fxChip = (k, v) => (FX_NAME[k] || k) + " " + (v > 0 ? "+" : "−") + (Math.abs(v) < 1 ? Math.round(Math.abs(v) * 100) + (k === "app" || k === "pStab" ? "" : "%") : Math.abs(v));

// ─── JUDICIARY EVENTS ───
const JUDICIARY_EVENTS = [
  { id: "budget_challenge", nm: "Budget Legality Challenge", d: "Opposition files suit claiming your budget process violated S.121. Court may order a review.", trigger: "forced_budget" },
  { id: "land_suit", nm: "Land Allocation Lawsuit", d: "A group of displaced farmers sues over land given to contractors without proper compensation.", trigger: "high_corruption" },
  { id: "policy_injunction", nm: "Policy Injunction", d: "A court injunction halts one of your active policies pending judicial review.", trigger: "random" },
  { id: "election_petition", nm: "Election Petition", d: "Opposition challenges your re-election in the Election Tribunal.", trigger: "reelection" },
];

// The chamber, one dot per seat: members who back you, and the rest.
// Who is speaking for a House objection.
const LAWMAKER_ART = (who) => /loyal to|godfather|'s members/i.test(who || "") ? "lawmaker-godfather-loyalist" : /opposition/i.test(who || "") ? "lawmaker-opposition-leader" : /caucus|party|Party stability/i.test(who || "") ? "lawmaker-majority-leader" : "lawmaker-backbencher";
const LawFace = ({ who }) => <img src={"./art/characters/" + LAWMAKER_ART(who) + ".webp"} alt="" loading="lazy" style={{ width: 34, height: 40, objectFit: "cover", objectPosition: "top", borderRadius: 8, background: CL.grn + "14", verticalAlign: "middle", marginRight: 8, flexShrink: 0 }} />;
const SeatStrip = ({ house }) => { if (!house) return null; const per = house.seats > 60 ? Math.ceil(house.seats / 40) : 1; return <div style={{ margin: "0 auto 22px", maxWidth: 732, padding: "18px 22px", borderRadius: 16, background: "#6b4a2b url(./art/objects/vote-tally-board.webp) center/100% 100% no-repeat" }}>
  <div style={{ display: "flex", flexWrap: "wrap", gap: 5, justifyContent: "center" }} aria-label={house.loyal + " of " + house.seats + " members back you"}>
    {Array.from({ length: Math.ceil(house.seats / per) }, (_, i) => <span key={i} style={{ width: 14, height: 14, borderRadius: "50%", background: i < Math.round(house.loyal / per) ? "#0b6b42" : "#d8cfb8" }} />)}
  </div>
  <div style={{ fontSize: TS(30), color: "#fff8e6", marginTop: 8, textShadow: "0 1px 2px rgba(0,0,0,.6)" }}><b style={{ color: house.loyal > house.seats / 2 ? "#9be7b4" : "#ffb4a9" }}>{house.loyal} of {house.seats}</b> members back you · {Math.floor(house.seats / 2) + 1} needed{per > 1 ? " · each dot ≈ " + per : ""}</div>
</div>; };
const HouseVote = ({ pStab, bud, level, onPass, onAmend, onForce, onNegotiate, onDrop, grudges = [], speakerName = "The Speaker", addL, house, onClear, fixLabel }) => {
  const [voted, setVoted] = useState(false);
  const [result, setResult] = useState(null);
  const [reasons, setReasons] = useState([]);

  const bs = Object.values(bud).reduce((a, b) => a + b, 0);
  const denom = bs || 100;
  const salPct = (bud.salaries || 0) / denom * 100;
  const debtPct = (bud.debt || 0) / denom * 100;
  const eduPct = (bud.education || 0) / denom * 100;
  const secPct = (bud.security || 0) / denom * 100;
  const healthPct = (bud.health || 0) / denom * 100;
  const adminPct = (bud.administration || 0) / denom * 100;

  // Build specific, fixable concerns. The House no longer blocks by random
  // dice-roll: only constitutional/fiscal red flags reject the bill.
  const concerns = [];
  if (bs !== 100) concerns.push({ t: "Appropriation schedule totals " + bs + "% instead of 100% — clerks cannot lay an unbalanced bill.", severity: "high", fix: "Return to Budget and make the total exactly 100%." });
  if (salPct < 14) concerns.push({ t: "Salaries are only " + salPct.toFixed(0) + "% — civil service arrears and NLC strike risk are too obvious for members to defend.", severity: "high", fix: "Raise Salaries to at least 18%." });
  else if (salPct < 18) concerns.push({ t: "Salaries at " + salPct.toFixed(0) + "% will pass, but labour caucus wants a clearer wage buffer.", severity: "medium", fix: "18–22% is politically safer." });
  if (eduPct < 6) concerns.push({ t: "Education is collapsed to " + eduPct.toFixed(0) + "% — teacher unions and parents will punish every member who votes yes.", severity: "high", fix: "Raise Education to at least 12%." });
  else if (eduPct < 10) concerns.push({ t: "Education at " + eduPct.toFixed(0) + "% is thin; House will demand SUBEB line-items.", severity: "medium", fix: "10–18% is defensible." });
  if (healthPct < 5) concerns.push({ t: "Health is only " + healthPct.toFixed(0) + "% — PHCs will run out of drugs before the next quarter.", severity: "high", fix: "Raise Health to at least 10%." });
  else if (healthPct < 8) concerns.push({ t: "Health at " + healthPct.toFixed(0) + "% is below a safe service floor.", severity: "medium", fix: "8–18% is defensible." });
  if (secPct < 5) concerns.push({ t: "Security vote below " + secPct.toFixed(0) + "% leaves the state exposed; even opposition members fear kidnappings.", severity: "high", fix: "Raise Security to at least 8%." });
  else if (secPct > 22) concerns.push({ t: "Security vote at " + secPct.toFixed(0) + "% is too opaque — Speaker demands line-item disclosure before approval.", severity: "high", fix: "Cut Security below 20% or publish a sub-vote schedule." });
  else if (secPct > 16) concerns.push({ t: "Security vote at " + secPct.toFixed(0) + "% will pass with uncomfortable questions about receipts.", severity: "medium", fix: "Keep Security near 8–14% unless insecurity is severe." });
  if (adminPct > 18) concerns.push({ t: "Government House/admin overhead is " + adminPct.toFixed(0) + "% — members see waste, convoys and foreign trips.", severity: "high", fix: "Trim Administration to 10% or less." });
  else if (adminPct > 12) concerns.push({ t: "Administration at " + adminPct.toFixed(0) + "% will pass, but the press will call it wasteful.", severity: "medium", fix: "5–10% is safer." });
  if (debtPct < 3 && debtPct > 0) concerns.push({ t: "Debt service is light; contractors may keep lobbying members over unpaid certificates.", severity: "low", fix: "5–12% keeps creditors quieter." });
  if (pStab < 25) concerns.push({ t: "Party stability is " + Math.round(pStab) + "% — your own caucus can no longer guarantee quorum for an appropriation vote.", severity: "high", fix: "Repair party relations or negotiate with the Speaker." });
  else if (pStab < 40) concerns.push({ t: "Party stability is " + Math.round(pStab) + "% — the bill can pass, but only with observations and political bruising.", severity: "medium", fix: "Meet the caucus before the next bill." });

  // Who objects, and whether it is a fair objection. Budget defects are fair;
  // grudges come from the record (window.SOP_MEMORY) and are often leverage.
  const whoOf = (t) => /^Salaries/.test(t) ? "The labour caucus" : /^Education/.test(t) ? "Members from teacher-heavy constituencies" : /^Health/.test(t) ? "The health committee" : /^Security/.test(t) ? "The security committee" : /admin overhead|^Administration/.test(t) ? "The Public Accounts Committee" : /^Party stability/.test(t) ? "Your own caucus" : /^Debt/.test(t) ? "Members lobbied by contractors" : "The Clerk of the House";
  concerns.forEach(c => { c.who = whoOf(c.t); c.good = !/^Party stability/.test(c.t); });
  grudges.forEach(g => concerns.push({ t: g.who + ": " + g.why, who: g.who, why: g.why, good: g.good, severity: g.block ? "high" : "medium", grudge: true }));
  const hardBlockers = concerns.filter(c => c.severity === "high");
  const fixable = hardBlockers.some(c => !c.grudge);
  const dealCost = Math.round((0.3 + 0.2 * hardBlockers.length) * 10) / 10;
  const statusLabel = hardBlockers.length ? "BLOCKED: " + hardBlockers.length + " fatal defect" + (hardBlockers.length === 1 ? "" : "s") : concerns.length ? "WILL PASS WITH OBSERVATIONS" : "WILL PASS CLEANLY";
  const statusColor = hardBlockers.length ? CL.red : concerns.length ? CL.org : CL.grn;
  const cleanDraft = { salaries: 18, debt: 8, administration: 7, health: 15, education: 15, security: 11, infrastructure: 16, agriculture: 10 };

  const doVote = () => {
    const passed = hardBlockers.length === 0;
    if (!passed) {
      setReasons(hardBlockers);
      addL && addL("❌ House rejects Appropriation Bill. " + hardBlockers.slice(0, 2).map(r => r.who + " voted no: " + (r.why || r.t.split(" — ")[0])).join(" "), "political");
    } else if (concerns.length) {
      addL && addL("✅ Appropriation Bill passed with House observations: " + concerns[0].t, "policy");
    }
    setResult(passed ? "pass" : "reject");
    setVoted(true);
  };

  if (!voted) return (
    <div style={{ textAlign: "center" }}>
      <SceneArt bg="assembly-chamber-wide" who={hardBlockers.length ? "speaker-worried" : "speaker"} alt={speakerName} h={TALL() ? 170 : 230} />
      <h3 style={{ fontFamily: F.d, color: CL.txt, fontSize: TS(65), fontWeight: 600, margin: "0 0 14px" }}>House of Assembly</h3>
      <p style={{ color: CL.td, fontSize: TS(36), marginBottom: 22 }}>Members vote on your budget.</p>
      <SeatStrip house={house} />
      {concerns.length > 0 && (
        <div style={{ textAlign: "left", margin: "0 auto 36px", maxWidth: 732, padding: 29, background: CL.org + "08", borderRadius: 13, border: "1px solid " + CL.org + "25" }}>
          <div style={{ fontSize: TS(34), fontWeight: 700, color: CL.org, marginBottom: 14 }}>⚠️ HOUSE CONCERNS (may cause rejection):</div>
          {concerns.map((c, i) => (
            <div key={i} style={{ display: "flex", alignItems: "center", fontSize: TS(34), color: c.severity === "high" ? CL.red : c.severity === "medium" ? CL.org : CL.tm, padding: "7px 0" }}><LawFace who={c.who} /><span>{c.grudge ? c.t : c.who + ": " + c.t}</span></div>
          ))}
        </div>
      )}
      <div style={{ display: "flex", gap: 29, justifyContent: "center", marginBottom: 36, flexWrap: "wrap" }}>
        <Bg text={"Party: " + Math.round(pStab) + "%"} color={pStab > 50 ? CL.grn : CL.red} />
        <Bg text={statusLabel} color={statusColor} />
      </div>
      <Bt onClick={doVote}>🗳️ CALL THE VOTE</Bt>
    </div>
  );

  if (result === "pass") return (
    <div style={{ textAlign: "center" }}>
      <SceneArt bg="assembly-chamber-wide" who="speaker-pleased" alt={speakerName} h={TALL() ? 170 : 230} />
      <h3 style={{ fontFamily: F.d, color: CL.grn, fontSize: TS(65), fontWeight: 600, margin: "0 0 14px" }}>APPROPRIATION BILL PASSED</h3>
      <p style={{ color: CL.tm, fontSize: TS(36), marginBottom: 43 }}>The House of Assembly has approved your budget.</p>
      <Bt onClick={onPass}>PROCEED TO POLICIES →</Bt>
    </div>
  );

  return (
    <div style={{ textAlign: "center" }}>
      <SceneArt bg="assembly-chamber-wide" who="speaker-angry" alt={speakerName} h={TALL() ? 170 : 230} />
      <h3 style={{ fontFamily: F.d, color: CL.red, fontSize: TS(65), fontWeight: 600, margin: "0 0 14px" }}>BILL REJECTED</h3>
      <div style={{ textAlign: "left", margin: "22px auto 36px", maxWidth: 732, padding: 29, background: CL.red + "08", borderRadius: 13, border: "1px solid " + CL.red + "25" }}>
        <div style={{ fontSize: TS(34), fontWeight: 700, color: CL.red, marginBottom: 14 }}>WHO VOTED AGAINST IT, AND WHY</div>
        {reasons.map((r2, i) => (
          <div key={i} style={{ padding: "10px 0", borderTop: i ? "1px solid " + CL.red + "20" : "none" }}>
            <div style={{ display: "flex", alignItems: "center", fontSize: TS(34), color: CL.txt, lineHeight: 1.4 }}><LawFace who={r2.who} /><span><b>{r2.who}</b> — {r2.why || r2.t}</span></div>
            <div style={{ fontSize: TS(30), color: r2.good ? CL.grn : CL.red, marginTop: 4 }}>{r2.good ? "Fair reason: the bill has a real problem." : r2.grudge ? "Leverage, not policy: this is about what you did, not what the bill says." : "Political: your own side is not with you."}</div>
          </div>
        ))}
      </div>
      {onClear && reasons.some(r2 => r2.grudge) && <div style={{ maxWidth: 768, margin: "0 auto 22px", textAlign: "left" }}>
        <div style={{ fontSize: TS(32), fontWeight: 800, color: CL.txt, marginBottom: 10 }}>Clear the way, then call the vote again</div>
        <div style={{ display: "grid", gap: 10 }}>
          {[...new Set(reasons.filter(r2 => r2.grudge && r2.fix).map(r2 => r2.fix)), "appeal"].map(fx => { const g = reasons.find(r2 => r2.fix === fx) || reasons.find(r2 => r2.grudge); return <button key={fx} className="sp-opt" onClick={() => { onClear(fx, g); setVoted(false); setResult(null); }}><b style={{ fontSize: 16 }}>{fixLabel(fx)}</b></button>; })}
        </div>
      </div>}
      <div style={{ display: "grid", gap: 22, maxWidth: 768, margin: "0 auto", textAlign: "left" }}>
        <Cd onClick={fixable ? () => onAmend(2, cleanDraft) : undefined} style={{ padding: 29, opacity: fixable ? 1 : .45 }}>
          <div style={{ fontWeight: 600, fontSize: TS(40), color: CL.txt, marginBottom: 7 }}>✏️ Amend and resubmit</div>
          <div style={{ fontSize: TS(32), color: CL.td }}>{fixable ? "Adopt a clean draft that fixes the defects above. Costs 2 points of party support." : "Nothing in the text to fix: the objection is to you, not the bill."}</div>
        </Cd>
        <Cd onClick={() => onNegotiate && onNegotiate(dealCost, reasons)} style={{ padding: 29 }}>
          <div style={{ fontWeight: 600, fontSize: TS(40), color: CL.txt, marginBottom: 7 }}>🤝 Negotiate with {speakerName}</div>
          <div style={{ fontSize: TS(32), color: CL.td }}>Constituency projects for the members who voted no. The bill passes as it is. Costs ₦{dealCost}B in new debt, a little corruption, and it goes on the record.</div>
        </Cd>
        <Cd onClick={onDrop} style={{ padding: 29 }}>
          <div style={{ fontWeight: 600, fontSize: TS(40), color: CL.txt, marginBottom: 7 }}>🗑️ Drop it for this year</div>
          <div style={{ fontSize: TS(32), color: CL.td }}>Run the state on last year's figures. Nothing new gets funded. Approval −3, party support −3.</div>
        </Cd>
        <Cd onClick={onForce} style={{ padding: 29, borderColor: CL.red + "44" }}>
          <div style={{ fontWeight: 600, fontSize: TS(40), color: CL.red, marginBottom: 7 }}>⚠️ Force it through by executive order</div>
          <div style={{ fontSize: TS(32), color: CL.td }}>Unconstitutional. Party support −15, approval −5. Likely court challenge.</div>
        </Cd>
      </div>
    </div>
  );
};

// ─── THE WIKIPEDIA ARTICLE ───
// One article, built by buildWiki() in GovScreen from the record (the
// ledger) and the setup: a stub in the first year that grows every
// year, and the full biography at the end. A paragraph is a list of
// strings and { ref: n } footnote markers; references point to the in-game
// news story that reported each fact.
const WIKI_SERIF = "'Linux Libertine','Georgia','Times New Roman',serif";
const WikiPara = ({ parts }) => <p style={{ margin: "0 0 14px" }}>{parts.map((x, i) => typeof x === "string" ? <React.Fragment key={i}>{x}</React.Fragment> : <sup key={i} style={{ fontSize: "70%", lineHeight: 0 }}><a href={"#wref-" + x.ref} onClick={e => { e.preventDefault(); const el = document.getElementById("wref-" + x.ref); el && el.scrollIntoView({ block: "center", behavior: "smooth" }); }} style={{ color: "#3366cc", textDecoration: "none" }}>[{x.ref}]</a></sup>)}</p>;
const WikiArticle = ({ w, onShare }) => {
  const tall = TALL();
  const box = <table style={{ float: tall ? "none" : "right", width: tall ? "100%" : 420, margin: tall ? "0 0 22px" : "0 0 22px 29px", border: "1px solid #a2a9b1", background: "#f8f9fa", borderCollapse: "collapse", fontSize: TS(29), fontFamily: "sans-serif", color: "#202122" }}>
    <tbody>
      <tr><th colSpan={2} style={{ fontSize: TS(36), padding: "10px 8px", textAlign: "center", fontFamily: WIKI_SERIF, fontWeight: 400 }}>{w.title}</th></tr>
      {w.portrait && <tr><td colSpan={2} style={{ textAlign: "center", padding: 8 }}><img src={w.portrait} alt={w.title} style={{ ...frameStyle(), maxWidth: "70%", maxHeight: 300, objectFit: "contain", background: "#eaecf0" }} /><div style={{ fontSize: TS(25), color: "#54595d" }}>{w.title} in {w.startYear}</div></td></tr>}
      <tr><th colSpan={2} style={{ background: "#cee0f2", padding: "6px 8px", textAlign: "center" }}>{w.office}</th></tr>
      <tr><td colSpan={2} style={{ textAlign: "center", padding: "6px 8px", fontWeight: 700 }}>{w.inOffice}</td></tr>
      {w.rows.map(([k, v]) => <tr key={k}><th style={{ textAlign: "left", verticalAlign: "top", padding: "5px 8px", width: "38%" }}>{k}</th><td style={{ padding: "5px 8px" }}>{v}</td></tr>)}
    </tbody>
  </table>;
  return <div style={{ background: "#fff", color: "#202122", border: "1px solid #a7d7f9", padding: tall ? "22px 18px" : "36px 50px", fontFamily: "sans-serif", fontSize: TS(32), lineHeight: 1.6 }}>
    <h1 style={{ fontFamily: WIKI_SERIF, fontWeight: 400, fontSize: TS(58), margin: 0, borderBottom: "1px solid #a2a9b1", paddingBottom: 6 }}>{w.title}</h1>
    <div style={{ fontSize: TS(27), color: "#54595d", margin: "6px 0 18px" }}>From Wikipedia, the free encyclopedia <span style={{ color: "#72777d" }}>(in the game)</span></div>
    {w.stub && <div style={{ border: "1px solid #a2a9b1", background: "#f8f9fa", padding: "8px 12px", fontSize: TS(27), marginBottom: 18 }}>📄 This article about a Nigerian politician is a <i>stub</i>. It grows with every year in office.</div>}
    {box}
    {w.lead.map((pp, i) => <WikiPara key={i} parts={pp} />)}
    {w.sections.map(sec => <div key={sec.h}>
      <h2 style={{ fontFamily: WIKI_SERIF, fontWeight: 400, fontSize: TS(44), borderBottom: "1px solid #a2a9b1", margin: "29px 0 12px" }}>{sec.h}</h2>
      {(sec.subs || []).map(sub => <div key={sub.h}>
        <h3 style={{ fontSize: TS(34), fontWeight: 700, margin: "18px 0 8px" }}>{sub.h}</h3>
        {sub.paras.map((pp, i) => <WikiPara key={i} parts={pp} />)}
      </div>)}
      {(sec.paras || []).map((pp, i) => <WikiPara key={i} parts={pp} />)}
    </div>)}
    <div style={{ clear: "both" }} />
    {w.refs.length > 0 && <div>
      <h2 style={{ fontFamily: WIKI_SERIF, fontWeight: 400, fontSize: TS(44), borderBottom: "1px solid #a2a9b1", margin: "29px 0 12px" }}>References</h2>
      <ol style={{ fontSize: TS(27), paddingLeft: 32, margin: 0 }}>{w.refs.map(r => <li key={r.n} id={"wref-" + r.n} style={{ marginBottom: 6 }}>"{r.head}". <i>{r.src}</i>. {r.when}.</li>)}</ol>
    </div>}
    <div style={{ marginTop: 29, border: "1px solid #a2a9b1", background: "#f8f9fa", padding: "8px 12px", fontSize: TS(27) }}>Categories: {w.cats.join(" | ")}</div>
    {onShare && !VATAR && <div style={{ display: "flex", gap: 12, flexWrap: "wrap", marginTop: 22 }}>
      <Bt onClick={() => onShare("status")} style={{ fontSize: TS(30), background: "#25D366", color: "#fff" }}>Share card · WhatsApp status</Bt>
      <Bt onClick={() => onShare("x")} style={{ fontSize: TS(30), background: "#000", color: "#fff" }}>Share card · X</Bt>
    </div>}
  </div>;
};
// The share card: the top of the article (title, infobox, lead) drawn on a
// canvas. 1080×1920 for a WhatsApp status, 1200×675 for X. It says it is
// from a game, and carries the link back.
const wikiShareCard = async (w, kind) => {
  const W = kind === "x" ? 1200 : 1080, H = kind === "x" ? 675 : 1920;
  const c = document.createElement("canvas"); c.width = W; c.height = H;
  const g = c.getContext("2d");
  const serif = "Georgia, 'Times New Roman', serif", sans = "Arial, Helvetica, sans-serif";
  const wrap = (txt, x, y, maxW, lh, maxLines) => { const words = String(txt).split(/\s+/); let line = "", n = 0; for (let i = 0; i < words.length; i++) { const t = line ? line + " " + words[i] : words[i]; if (g.measureText(t).width > maxW && line) { g.fillText(line, x, y); y += lh; line = words[i]; if (++n >= maxLines - 1) { let rest = words.slice(i).join(" "); while (g.measureText(rest + "…").width > maxW && rest.length) rest = rest.slice(0, -1); g.fillText(rest + (rest.length < words.slice(i).join(" ").length ? "…" : ""), x, y); return y + lh; } } else line = t; } if (line) { g.fillText(line, x, y); y += lh; } return y; };
  const img = await new Promise(res => { if (!w.portrait) return res(null); const im = new Image(); im.onload = () => res(im); im.onerror = () => res(null); im.src = w.portrait; });
  g.fillStyle = "#ffffff"; g.fillRect(0, 0, W, H);
  g.fillStyle = "#0b5d3b"; g.fillRect(0, 0, W, kind === "x" ? 46 : 90);
  g.fillStyle = "#fff"; g.font = "bold " + (kind === "x" ? 22 : 36) + "px " + sans; g.fillText("THE SEAT OF POWER · a game · fictional", 24, kind === "x" ? 31 : 58);
  const lead = w.leadText;
  if (kind === "x") {
    const bx = 760, bw = 410; g.strokeStyle = "#a2a9b1"; g.fillStyle = "#f8f9fa"; g.fillRect(bx, 70, bw, 560); g.strokeRect(bx, 70, bw, 560);
    if (img) { const ih = 300, iw = img.width * ih / img.height; g.drawImage(img, bx + (bw - Math.min(iw, bw - 20)) / 2, 82, Math.min(iw, bw - 20), ih); }
    g.fillStyle = "#cee0f2"; g.fillRect(bx + 1, 394, bw - 2, 34); g.fillStyle = "#202122"; g.font = "bold 20px " + sans; g.fillText(w.office, bx + 12, 418);
    let y = 456; g.font = "18px " + sans; w.rows.slice(0, 5).forEach(([k, v]) => { g.font = "bold 18px " + sans; g.fillText(k, bx + 12, y); g.font = "18px " + sans; wrap(v, bx + 150, y, bw - 160, 22, 1); y += 34; });
    g.fillStyle = "#202122"; g.font = "52px " + serif; wrap(w.title, 30, 120, 700, 58, 2);
    g.fillStyle = "#54595d"; g.font = "20px " + sans; g.fillText("From the game's encyclopedia", 30, 200);
    g.fillStyle = "#202122"; g.font = "24px " + serif; wrap(lead, 30, 250, 700, 34, 10);
    g.fillStyle = "#3366cc"; g.font = "bold 22px " + sans; g.fillText(w.link, 30, 640);
  } else {
    g.fillStyle = "#202122"; g.font = "86px " + serif; let y = wrap(w.title, 60, 220, 960, 96, 2);
    g.fillStyle = "#54595d"; g.font = "32px " + sans; g.fillText("From the game's encyclopedia", 60, y + 6);
    const bx = 60, by = y + 50, bw = 960; g.fillStyle = "#f8f9fa"; g.fillRect(bx, by, bw, 780); g.strokeStyle = "#a2a9b1"; g.lineWidth = 2; g.strokeRect(bx, by, bw, 780);
    if (img) { const ih = 470, iw = Math.min(img.width * ih / img.height, bw - 40); g.drawImage(img, bx + (bw - iw) / 2, by + 20, iw, ih); }
    g.fillStyle = "#cee0f2"; g.fillRect(bx + 2, by + 506, bw - 4, 56); g.fillStyle = "#202122"; g.font = "bold 34px " + sans; g.fillText(w.office, bx + 24, by + 546);
    let ry = by + 610; w.rows.slice(0, 4).forEach(([k, v]) => { g.font = "bold 30px " + sans; g.fillText(k, bx + 24, ry); g.font = "30px " + sans; wrap(v, bx + 300, ry, bw - 330, 34, 1); ry += 44; });
    g.fillStyle = "#202122"; g.font = "38px " + serif; wrap(lead, 60, by + 860, 960, 54, 9);
    g.fillStyle = "#3366cc"; g.font = "bold 34px " + sans; g.fillText(w.link, 60, H - 70);
  }
  return new Promise(res => c.toBlob(b => res(b), "image/png"));
};

// ─── GOVERNANCE ───
// Vatar edition: Second Chance (a paid consumable) reruns a lost re-election
// from the checkpoint saved when the campaign began, once per game.
const SecondChance = () => {
  const [ents, setEnts] = useState(() => window.SOP_ENTS || {});
  const [busy, setBusy] = useState(false), [err, setErr] = useState(null), [cp, setCp] = useState(null);
  useEffect(() => {
    const f = (e) => setEnts(e.detail || {}); window.addEventListener("sop-ents", f);
    (async () => { try { const r = await window.storage.get("sop_preelection"); if (r && r.value) setCp(r.value); } catch (e) {} })();
    return () => window.removeEventListener("sop-ents", f);
  }, []);
  if (!cp || !(window.SOP_canBuy && window.SOP_canBuy())) return null;
  try { const d0 = JSON.parse(cp); if (d0.setup && d0.setup.mode && d0.setup.mode.kind === "challenge") return null; } catch (e) {} // the board stays fair
  const have = (ents.second_chance || 0) > 0;
  const go = async () => {
    setBusy(true); setErr(null);
    try {
      if (!have) await window.SOP_buy("second_chance");
      if (!(await window.SOP_useCredit("second_chance"))) throw new Error("credit");
      const d = JSON.parse(cp); d.stc = { ...(d.stc || {}), secondChance: true };
      await window.storage.set("sop_save", JSON.stringify(d));
      await window.storage.set("sop_preelection", "");
      setTimeout(() => location.reload(), 600);
    } catch (e) {
      setBusy(false);
      setErr(e && e.code === "cancelled" ? null : e && e.code === "payment_failed" ? "The payment didn't go through." : "Something went wrong. Nothing was charged twice; try again.");
    }
  };
  return <Cd style={{ maxWidth: 720, margin: "0 auto 22px", borderColor: CL.gold + "88", textAlign: "center" }}>
    <div style={{ fontSize: TALL() ? TS(30) : TS(44), fontFamily: F.d, fontWeight: 700, color: CL.txt }}>🔁 Second Chance</div>
    <div style={{ fontSize: TALL() ? TS(19) : TS(30), color: CL.tm, margin: "6px 0 12px" }}>Go back to the start of the re-election campaign and fight it again. Once per game.</div>
    <Bt onClick={go} disabled={busy}>{busy ? "Rewinding…" : have ? "Use your Second Chance" : "Get a Second Chance"}</Bt>
    {err && <div style={{ fontSize: TALL() ? TS(18) : TS(26), color: CL.red, marginTop: 8 }}>{err}</div>}
  </Cd>;
};
// ─── PROJECTS (rules in SYS: projects.js, loans.js, proposals.js) ───
// Every screen has three layers: the situation (a headline and a sentence),
// the decision (cards with real figures and only the actions the simulation
// supports), and an optional full briefing. Milestones and the next step
// come from SYS.milestoneOf / SYS.nextStep, so what you see is what is true.
const SECTOR_ICON = { roads: "🛣️", health: "🏥", education: "🏫", water: "🚰", energy: "⚡", markets: "🏬", security: "🛡️", waste: "♻️", industry: "🏭", sports: "🏟️", tourism: "🏝️" };
const MilestoneStrip = ({ at }) => <div className="sp-ms" role="list" aria-label="Project stages">
  {SYS.MILESTONES.map(([k, l], i) => <div key={k} role="listitem" className={"s" + (i < at ? " done" : i === at ? " now" : "")} aria-current={i === at ? "step" : undefined}><span>{l}</span></div>)}
</div>;
const Tiles = ({ items }) => <div className="sp-tiles">{items.filter(Boolean).map(([l, v, tone]) => <div key={l} className={"sp-tile" + (tone ? " " + tone : "")}><div className="l">{l}</div><div className="v">{v}</div></div>)}</div>;
// What a project's site looks like at each stage, and its stage pin (art pack 2).
const siteArt = (p) => p.status === "delivered" ? "project-ribbon-cutting" : ["stalled", "suspended", "abandoned"].includes(p.status) ? "project-site-stalled" : (p.status === "in_progress" && (p.progress || 0) >= 35) || p.status === "built" ? "project-site-halfway" : "project-site-cleared";
const pinOf = (p) => p.status === "delivered" ? "green" : ["stalled", "suspended", "abandoned"].includes(p.status) ? "red" : p.status === "in_progress" || p.status === "built" ? "gold" : "grey";
const Dossier = ({ icon, kicker, title, place, at, children, wide, pic, thumb, pin }) => <div className="sp-card sp-step" style={{ maxWidth: wide ? 980 : 900, margin: "0 auto", padding: TALL() ? "16px 16px 18px" : "22px 26px 24px" }}>
  {pic && <img src={"./art/backgrounds/" + pic + ".webp"} alt="" style={{ display: "block", width: "100%", aspectRatio: "16/9", objectFit: "cover", borderRadius: 16, marginBottom: 14 }} />}
  <div style={{ display: "flex", gap: 14, alignItems: "center" }}>
    <div aria-hidden="true" style={{ width: 54, height: 54, borderRadius: 16, background: "linear-gradient(180deg,#fff7e2,#f1e2b8)", display: "grid", placeItems: "center", fontSize: 28, flexShrink: 0, boxShadow: "inset 0 0 0 1px #e7d6a8" }}>{icon}</div>
    <div style={{ minWidth: 0 }}>
      {kicker && <div className="sp-kicker" style={{ display: "flex", alignItems: "center", gap: 6 }}>{pin && <img src={"./art/objects/map-pin-project-" + pin + ".webp"} alt="" style={{ height: 18, width: "auto" }} />}{kicker}</div>}
      <div style={{ font: "700 " + (TALL() ? 24 : 30) + "px/1.15 'Fraunces', Georgia, serif", color: "#17301f", marginTop: 3 }}>{title}</div>
      {place && <div style={{ font: "600 14px 'Plus Jakarta Sans', sans-serif", color: "#7a6c4c", marginTop: 2 }}>{place}</div>}
    </div>
    {thumb && <img src={"./art/backgrounds/" + thumb + ".webp"} alt="" style={{ marginLeft: "auto", width: TALL() ? 84 : 120, aspectRatio: "16/9", objectFit: "cover", borderRadius: 12, flexShrink: 0 }} />}
  </div>
  {at != null && <div style={{ margin: "14px 0 4px" }}><MilestoneStrip at={at} /></div>}
  {children}
</div>;
const Situation = ({ head, text, tone }) => <div style={{ margin: "14px 0 12px", padding: "12px 14px", borderRadius: 16, background: tone === "bad" ? "#fdf0ee" : tone === "warn" ? "#fdf6e7" : "#f1f7f1", borderLeft: "4px solid " + (tone === "bad" ? "#b3261e" : tone === "warn" ? "#c9922a" : "#0b6b42") }}>
  <div style={{ font: "800 18px/1.3 'Plus Jakarta Sans', sans-serif", color: "#17301f" }}>{head}</div>
  {text && <div style={{ font: "500 15px/1.45 'Plus Jakarta Sans', sans-serif", color: "#3d4f3a", marginTop: 3 }}>{text}</div>}
</div>;
const Brief = ({ children, label = "Full briefing" }) => <details className="sp-brief" style={{ marginTop: 10, borderTop: "1px solid #eee3cb", paddingTop: 4 }}><summary>{label}</summary><div style={{ font: "500 14px/1.5 'Plus Jakarta Sans', sans-serif", color: "#3d4f3a", paddingBottom: 6 }}>{children}</div></details>;
const Actions = ({ children }) => <div style={{ display: "flex", gap: 10, justifyContent: "flex-end", flexWrap: "wrap", marginTop: 14 }}>{children}</div>;
const spField = { padding: "11px 12px", font: "600 16px 'Plus Jakarta Sans', sans-serif", border: "1.5px solid #e2d7bd", borderRadius: 12, width: "100%", boxSizing: "border-box", background: "#fff", color: "#17301f" };
const spLab = (t) => <div className="sp-kicker" style={{ margin: "12px 0 6px" }}>{t}</div>;
// The milestone strip moves from where the project was to where it is now,
// so an advance is seen happening (CSS transitions; none with reduced motion).
const MilestoneMove = ({ from, at }) => {
  const [shown, setShown] = useState(from != null && from < at ? from : at);
  useEffect(() => { if (shown === at) return; const t = setTimeout(() => setShown(at), 650); return () => clearTimeout(t); }, [at]);
  return <MilestoneStrip at={shown} />;
};
// Reduced motion: the device setting, or the player's own switch.
const spStill = () => { try { return localStorage.getItem("sop_still") === "1"; } catch (e) { return false; } };
const setSpStill = (v) => { try { localStorage.setItem("sop_still", v ? "1" : "0"); } catch (e) {} try { document.documentElement.classList.toggle("sp-still", !!v); } catch (e) {} };
try { document.documentElement.classList.toggle("sp-still", spStill()); } catch (e) {}
// Words the adviser uses that a player may not know: tap one for a single plain line.
const GLOSSARY = [
  [/\bFAAC\b/, "FAAC", "The monthly share of federal revenue (mostly oil) paid to every state. It rises and falls with oil prices."],
  [/\bIGR\b|own revenue/i, "Own revenue", "Taxes and fees the state collects itself (IGR). The part of your money you can grow."],
  [/\bthe House\b|House of Assembly/, "The House", "The State House of Assembly. It must pass your budget and bills, and it can impeach you."],
  [/\bgodfather\b/i, "Godfather", "The power broker who funded your campaign. He expects contracts and appointments in return."],
  [/\bprocurement\b/i, "Procurement", "How a contract is given out: an open tender, a selective one, or a direct award."],
  [/\bEFCC\b/, "EFCC", "The federal anti-corruption agency. It investigates what your record shows."],
  [/\bdebt service\b/i, "Debt service", "What the state pays each year on what it has borrowed."],
  [/\bthe bank\b/i, "The bank", "The state's money for this year's work. Spending comes from here first; borrowing only when it is empty."],
  [/\bAppropriation\b/, "Appropriation Bill", "The budget, as a law the House must pass (Section 121)."],
];
const glossed = (text, onTerm) => {
  const parts = []; let rest = String(text || ""), k = 0;
  while (rest) {
    let hit = null;
    GLOSSARY.forEach(g => { const m = rest.match(g[0]); if (m && (!hit || m.index < hit.m.index)) hit = { g, m }; });
    if (!hit) { parts.push(rest); break; }
    if (hit.m.index) parts.push(rest.slice(0, hit.m.index));
    parts.push(<button key={k++} type="button" onClick={() => onTerm(hit.g)} style={{ border: 0, background: "none", padding: 0, font: "inherit", color: "#b3261e", textDecoration: "underline dotted", cursor: "pointer" }}>{hit.m[0]}</button>);
    rest = rest.slice(hit.m.index + hit.m[0].length);
  }
  return parts;
};
const readAloud = (text) => { try { const u = new window.SpeechSynthesisUtterance(SYS.speakable(text)); u.lang = "en-NG"; window.speechSynthesis.cancel(); window.speechSynthesis.speak(u); } catch (e) {} };
/* The Special Adviser, at the desk: one short message, one button that
   opens the exact task, the reasoning on request, and Later. */
const AdviserDesk = ({ name, say, why, action, onAction, onLater, alert, soundOn, onSound }) => {
  const [open, setOpen] = useState(false), [still, setStill] = useState(spStill()), [term, setTerm] = useState(null);
  const ico = { minHeight: 36, padding: "4px 10px", fontSize: 14 };
  return <div className={"sp-card sp-adviser " + (alert ? "alert" : "calm")} role="status" aria-live="polite">
    {name ? (saPose(name, saMood(say, alert)) ? <img className="pic full" src={saPose(name, saMood(say, alert))} alt={name} /> : <img className="pic" src={saPortrait(name)} alt={"Portrait of " + name} />) : <div className="pic" aria-hidden="true" style={{ display: "grid", placeItems: "center", fontSize: 30 }}>🪑</div>}
    <div style={{ minWidth: 0 }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 8, marginBottom: 6 }}>
        <div style={{ minWidth: 0 }}><b style={{ font: "800 16px 'Plus Jakarta Sans', sans-serif", color: "#17301f" }}>{name || "The adviser's desk"}</b><div className="sp-kicker" style={{ marginTop: 3 }}>Special Adviser · by your desk</div></div>
        <div style={{ display: "flex", gap: 2, flexShrink: 0 }}>
          {onSound && <button className="sp-btn quiet" style={ico} aria-pressed={!soundOn} aria-label={soundOn ? "Mute sounds" : "Turn sounds on"} onClick={onSound}>{soundOn ? "🔊" : "🔇"}</button>}
          <button className="sp-btn quiet" style={ico} aria-pressed={still} aria-label={still ? "Turn animations on" : "Reduce motion"} title="Reduce motion" onClick={() => { setSpStill(!still); setStill(!still); }}>{still ? "◻" : "✨"}</button>
        </div>
      </div>
      <div className="sp-bubble">{glossed(say, setTerm)}{typeof window !== "undefined" && window.speechSynthesis && <button type="button" aria-label="Read aloud" onClick={() => readAloud(say)} style={{ border: 0, background: "none", cursor: "pointer", fontSize: 16, marginLeft: 6, verticalAlign: "middle" }}>🔈</button>}</div>
      {term && <div role="note" style={{ font: "500 14px/1.45 'Plus Jakarta Sans', sans-serif", color: "#3d4f3a", padding: "8px 2px 0" }}><b>{term[1]}:</b> {term[2]} <button type="button" onClick={() => setTerm(null)} className="sp-btn quiet" style={{ minHeight: 30, padding: "2px 8px", fontSize: 13 }}>Close</button></div>}
      {open && why && <div style={{ font: "500 14px/1.5 'Plus Jakarta Sans', sans-serif", color: "#3d4f3a", padding: "8px 2px 0" }}>{why}</div>}
      <div style={{ display: "flex", gap: 8, flexWrap: "wrap", alignItems: "center", marginTop: 10 }}>
        {action && <button className="sp-btn" onClick={onAction}>{action}</button>}
        {why && <button className="sp-btn quiet" aria-expanded={open} onClick={() => setOpen(!open)}>{open ? "Hide why" : "Why?"}</button>}
        {onLater && <button className="sp-btn quiet" onClick={onLater}>Later</button>}
      </div>
    </div>
  </div>;
};
// What changed because of the last decision.
const Consequence = ({ text, icon = "✅" }) => text ? <div className="sp-con" role="status"><span aria-hidden="true" style={{ fontSize: 20 }}>{icon}</span><span><b>What changed:</b> {text}</span></div> : null;

const ProjectsView = ({ year, projects, flow, onFlow, needs, lgas, ministries, roomM, onConfirmPlan, onApplyLoan, onAcceptOffer, onAward, onAction, onOpenStep, nextOf, agendaLeft, adviser, soundOn, onSound, onNeedMinistry }) => {
  const F0 = flow;
  const proj = F0 && F0.projId ? projects.find(x => x.id === F0.projId) : null;
  const where = (p) => [p.lga, (ministries || []).find(m => m.id === p.ministryId)?.name].filter(Boolean).join(" · ");

  // ── 1. Proposal: what, where, how big ──
  if (F0 && F0.step === "propose") {
    const P = F0.parsed, MIN_FOR = { health: "health", education: "educ", security: "sec" }, d0 = F0.draft || {};
    const d = d0.type && !d0.ministryId ? { ...d0, ministryId: ((ministries || []).find(m => m.id === (MIN_FOR[SYS.TYPE_SECTOR[d0.type]] || "works")) || (ministries || [])[0] || {}).id } : d0;
    const est = d.type ? SYS.estimate(d.type, d.qty) : null;
    const gate = d.type && projMin(d.type) && !(ministries || []).some(m => m.id === projMin(d.type)) ? MIN_CAT().find(c => c.id === projMin(d.type)) : null;
    const ready = d.type && d.lga && d.ministryId && (d.title || "").trim() && !gate;
    return <Dossier icon={d.type ? SECTOR_ICON[SYS.TYPE_SECTOR[d.type]] : "🏗️"} kicker="New project" title={d.title || "What will you build?"} place={d.lga ? d.lga : null} at={0}>
      <Situation head={d.type ? "Check the proposal, then set its budget." : "Describe it, or answer one of the state's needs."} text={d.need ? "This answers: " + ((needs || []).find(n => n.id === d.need) || {}).label?.replace(/^\S+\s/, "") + "." : null} />
      {!d.type && <>
        {(needs || []).length > 0 && <div style={{ display: "grid", gap: 8 }}>{needs.slice(0, 4).map(n => <button key={n.id} className="sp-opt" onClick={() => { const r = SYS.parseProposal(n.type + " in " + (n.lga || ""), { lgas, federal: SEAT.nat }); onFlow({ ...F0, draft: { ...r.proposal, title: n.label.replace(/^\S+\s/, ""), need: n.id } }); }}><b style={{ fontSize: 16 }}>{n.label}</b></button>)}</div>}
        {spLab("In your own words")}
        <textarea value={F0.text || ""} onChange={e => onFlow({ ...F0, text: e.target.value })} rows={2} placeholder="e.g. A 120-bed maternity hospital in Oredo" style={{ ...spField, resize: "vertical" }} />
        <Actions><button className="sp-btn ghost" onClick={() => { const r = SYS.parseProposal(F0.text, { lgas, federal: SEAT.nat }); onFlow({ ...F0, parsed: r, draft: r.status === "ok" ? { ...r.proposal, title: r.proposal.name } : d }); }}>Read it</button></Actions>
        {P && P.status === "clarify" && <Situation tone="warn" head={P.question} text={null} />}
        {P && P.status === "clarify" && <div style={{ display: "flex", flexWrap: "wrap", gap: 6 }}>{P.choices.map(c => <button key={c} className="sp-btn ghost" style={{ minHeight: 40, padding: "6px 14px", fontSize: 15 }} onClick={() => { const r = SYS.parseProposal(c + " " + (F0.text || ""), { lgas, federal: SEAT.nat }); onFlow({ ...F0, parsed: r, draft: { ...r.proposal, title: r.proposal.name } }); }}>{SYS.UNIT[c].nm}</button>)}</div>}
        {P && P.status === "unsupported" && <Situation tone="bad" head="Not something the state can build" text={P.why} />}
      </>}
      {gate && <Situation tone="warn" head={(adviser || "Your adviser") + ": “Your Excellency, who will run it? We have no Commissioner for " + gate.name + ".”"} text={"A " + SYS.UNIT[d.type].nm.toLowerCase() + " needs its own ministry to plan it and run it after the ribbon. Create the Ministry of " + gate.name + " (" + naira(gate.cost) + " a year) and this project can start."} />}
      {gate && onNeedMinistry && <Actions><button className="sp-btn" onClick={() => onNeedMinistry(gate)}>{gate.icon} Create the Ministry of {gate.name}</button></Actions>}
      {d.type && est && <>
        <Tiles items={[["Cost to build", SYS.fmtM(est.buildM)], est.facility && ["To equip", SYS.fmtM(est.equipM)], est.facility && ["To run", SYS.fmtM(est.opsPerYearM) + "/yr"], ["Takes about", est.years + (est.years === 1 ? " year" : " years")]]} />
        <div style={{ display: "grid", gridTemplateColumns: TALL() ? "1fr" : "1fr 1fr", gap: "0 12px" }}>
          <div>{spLab("Name")}<input value={d.title || ""} onChange={e => onFlow({ ...F0, draft: { ...d, title: e.target.value } })} style={spField} /></div>
          <div>{spLab("Where")}<select value={d.lga || ""} onChange={e => onFlow({ ...F0, draft: { ...d, lga: e.target.value || null } })} style={spField}><option value="">Pick a local government</option>{lgas.map(l => <option key={l} value={l}>{l}</option>)}</select></div>
          <div>{spLab("Kind")}<select value={d.type} onChange={e => { const r = SYS.parseProposal(e.target.value + " " + (d.lga || ""), { lgas, federal: SEAT.nat }); onFlow({ ...F0, draft: { ...d, ...r.proposal, title: d.title, need: d.need, srcPolicy: d.srcPolicy, ministryId: null } }); }} style={spField}>{TYPES_FOR().map(k => <option key={k} value={k}>{SYS.UNIT[k].nm}</option>)}</select></div>
          <div>{spLab("Size (" + est.unit + "s)")}<input type="number" min={1} value={d.qty} onChange={e => onFlow({ ...F0, draft: { ...d, qty: Math.max(1, +e.target.value || 1) } })} style={spField} /></div>
          <div>{spLab("Supervising ministry")}<select value={d.ministryId || ""} onChange={e => onFlow({ ...F0, draft: { ...d, ministryId: e.target.value } })} style={spField}>{(ministries || []).map(m => <option key={m.id} value={m.id}>{m.name}</option>)}</select></div>
        </div>
        <Brief>
          {d.benefit && <div><b>What it should give:</b> {d.benefit}</div>}
          <div><b>Needs:</b> a {SYS.SECTORS[SYS.TYPE_SECTOR[d.type]].toLowerCase()} contractor{est.facility ? "; then " + SYS.FACILITY[d.type].what + " before it serves anyone" : ""}.</div>
          {(d.assumptions || []).map((a, i) => <div key={i} style={{ color: "#9a5b12" }}>• {a}</div>)}
          <div style={{ marginTop: 4, color: "#7a6c4c" }}>Costs are the game's planning figures, not real tender prices.</div>
        </Brief>
      </>}
      <Actions>
        <button className="sp-btn quiet" onClick={() => onFlow(null)}>Cancel</button>
        <button className="sp-btn" disabled={!ready} onClick={() => { const e = SYS.estimate(d.type, d.qty); onFlow({ ...F0, draft: d, step: "plan", plan: { approvedM: e.buildM, thisYearM: Math.round(e.buildM / e.years), choice: null } }); }}>Next: the budget →</button>
      </Actions>
    </Dossier>;
  }

  // ── 2. The budget: phasing or a gap ──
  if (F0 && F0.step === "plan") {
    const d = F0.draft, e = SYS.estimate(d.type, d.qty), P = F0.plan;
    const a = SYS.assessFunding({ needM: e.buildM, approvedM: P.approvedM, thisYearM: P.thisYearM, years: e.years });
    const room = roomM(SYS.TYPE_SECTOR[d.type]), gap = Math.max(a.shortM, P.thisYearM - room), overRoom = P.thisYearM > room;
    const choices = { increase: ["Approve the full cost", "Set the budget to " + SYS.fmtM(e.buildM) + "."], reduce: ["Cut the scope to fit", "About " + Math.max(1, Math.floor(d.qty * P.approvedM / e.buildM)) + " " + e.unit + "s instead of " + d.qty + "."], finance: ["Seek financing", "Apply to lenders for " + SYS.fmtM(gap) + ". No debt until you accept an offer."], defer: ["Defer it", "Nothing starts this year. No agenda used."], proceed: ["Go ahead anyway", "On the record: you were warned the money runs out first."] };
    const head = a.kind === "short" ? "Funding gap: " + SYS.fmtM(a.shortM) : overRoom ? "This year's share is more than the bank can pay" : a.kind === "phased" ? "Phased over " + e.years + (e.years === 1 ? " year" : " years") : "Fully funded";
    return <Dossier icon={SECTOR_ICON[SYS.TYPE_SECTOR[d.type]]} kicker="Budget" title={d.title} place={d.lga} at={0}>
      <Situation tone={a.kind === "short" ? "bad" : overRoom ? "warn" : null} head={head} text={a.kind === "short" ? "The project cannot proceed as planned. Close the gap, cut the scope, or go ahead knowing the money runs out first." : overRoom ? "The bank can pay " + SYS.fmtM(room) + " towards it this year. The rest must be borrowed, or the work goes slower." : "Approval sets the budget. It is not a contract: nothing is paid until a contractor is chosen."} />
      <Tiles items={[["Estimated cost", SYS.fmtM(e.buildM)], ["Approved", SYS.fmtM(P.approvedM), a.kind === "short" ? "bad" : null], ["Funding gap", SYS.fmtM(Math.max(0, a.shortM)), a.shortM ? "bad" : "good"], ["Bank can pay", SYS.fmtM(room), overRoom ? "bad" : null]]} />
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 12 }}>
        <div>{spLab("Total budget (₦M)")}<input type="number" min={0} step={50} value={P.approvedM} onChange={x => onFlow({ ...F0, plan: { ...P, approvedM: Math.max(0, Math.round(+x.target.value || 0)), choice: null } })} style={spField} /></div>
        <div>{spLab("This year (₦M)")}<input type="number" min={0} step={50} value={P.thisYearM} onChange={x => onFlow({ ...F0, plan: { ...P, thisYearM: Math.max(0, Math.round(+x.target.value || 0)), choice: null } })} style={spField} /></div>
      </div>
      {(a.kind === "short" || overRoom) && <div style={{ display: "grid", gap: 8, marginTop: 12 }}>{(a.kind === "short" ? a.options : ["finance", "proceed"]).map(k => <button key={k} className="sp-opt" aria-pressed={P.choice === k} onClick={() => onFlow({ ...F0, plan: { ...P, choice: k } })}><b style={{ display: "block", fontSize: 16 }}>{choices[k][0]}</b><span style={{ fontSize: 14, color: "#5b6b55" }}>{choices[k][1]}</span></button>)}</div>}
      <Brief><div>{a.text}</div><div style={{ marginTop: 4 }}>Phasing (the whole scope funded over several years) is normal. A gap (approving less than the scope costs) means work stops when the money does, quality suffers, and the site may be abandoned.</div></Brief>
      <Actions>
        <button className="sp-btn quiet" onClick={() => onFlow({ ...F0, step: "propose" })}>‹ Back</button>
        <button className="sp-btn" disabled={(a.kind === "short" || overRoom) && !P.choice} onClick={() => onConfirmPlan(F0, a, overRoom)}>{P.choice === "defer" ? "Defer" : "Approve the project"}</button>
      </Actions>
      <div style={{ textAlign: "right", font: "600 13px 'Plus Jakarta Sans', sans-serif", color: "#7a6c4c", marginTop: 6 }}>Approving uses 1 of your {agendaLeft} major actions this year.</div>
    </Dossier>;
  }

  // ── 3. Money: apply, then an offer letter ──
  if (F0 && F0.step === "finance" && proj) {
    return <Dossier icon={SECTOR_ICON[proj.sector]} kicker="Find the money" title={proj.title} place={where(proj)} at={SYS.milestoneOf(proj)}>
      <Situation head={"It needs " + SYS.fmtM(F0.needM) + " from a lender"} text="Applying is free and creates no debt. Only an offer you accept does." />
      {F0.offer ? <div className="sp-card" style={{ padding: "16px 18px", background: "#fff", borderColor: "#cfe6d6" }}>
        <div className="sp-kicker" style={{ color: "#0b6b42" }}>Offer letter</div>
        <div style={{ font: "700 20px 'Fraunces', serif", color: "#17301f", margin: "4px 0 10px" }}>{F0.offer.lender}</div>
        <Tiles items={[["Amount", SYS.fmtM(F0.offer.principalM)], ["Interest", Math.round(F0.offer.rate * 1000) / 10 + "% a year"], ["Each year", SYS.fmtM(F0.offer.serviceM)], ["You repay", SYS.fmtM(F0.offer.repayM), "bad"]]} />
        <div style={{ font: "500 14px/1.45 'Plus Jakarta Sans', sans-serif", color: "#3d4f3a", marginTop: 8 }}>Over {F0.offer.years} years. {F0.offer.conditions}</div>
        <Actions><button className="sp-btn ghost" onClick={() => onFlow({ ...F0, offer: null, tried: [...(F0.tried || []), F0.offer.lenderId] })}>Decline</button><button className="sp-btn gold" onClick={() => onAcceptOffer(F0)}>Accept and receive {SYS.fmtM(F0.offer.principalM)}</button></Actions>
      </div> : <>
        {F0.letter && <Situation tone="bad" head={F0.letter.lender + " said no"} text={F0.letter.reasons.filter(r => r[0] === "✗").map(r => r.slice(2)).join(" ") || "Their credit committee declined."} />}
        <div style={{ display: "grid", gap: 8 }}>{Object.entries(SYS.LENDERS).map(([k, L]) => <button key={k} className="sp-opt" disabled={(F0.tried || []).includes(k)} onClick={() => onApplyLoan(F0, k)}><b style={{ display: "block", fontSize: 16 }}>{L.nm}</b><span style={{ fontSize: 14, color: "#5b6b55" }}>{L.lender} · about {Math.round(L.rate * 100)}% over {L.years} years{(F0.tried || []).includes(k) ? " · already answered" : ""}</span></button>)}</div>
      </>}
      <Actions><button className="sp-btn quiet" onClick={() => onFlow({ step: "contractor", projId: proj.id })}>Go on without a loan</button><button className="sp-btn quiet" onClick={() => onFlow(null)}>Later</button></Actions>
    </Dossier>;
  }

  // ── 4. Procurement: who builds it ──
  if (F0 && F0.step === "contractor" && proj) {
    const list = SYS.eligible(proj.type, projects, proj.id), meth = F0.method || "open", n = nextOf(proj);
    const bar = (l, v) => <span style={{ display: "inline-flex", alignItems: "center", gap: 6, fontSize: 13, color: "#5b6b55" }}>{l}<span style={{ width: 54, height: 6, borderRadius: 3, background: "#ece3cd", overflow: "hidden" }}><span style={{ display: "block", height: "100%", width: Math.round(v * 100) + "%", background: v > .75 ? "#0b6b42" : v > .55 ? "#c9922a" : "#b3261e" }} /></span></span>;
    return <Dossier icon={SECTOR_ICON[proj.sector]} kicker="Procurement" title={proj.title} place={where(proj)} at={SYS.milestoneOf(proj)} wide>
      <Situation tone={n.blocked ? "warn" : null} head={n.blocked ? "No qualified contractor is free" : "Award the contract"} text={n.blocked ? n.say : "Only firms that can do " + SYS.SECTORS[proj.sector].toLowerCase() + " work can bid. Awarding the contract is what starts the work."} />
      {spLab("How the contract is let")}
      <div style={{ display: "grid", gridTemplateColumns: TALL() ? "1fr" : "1fr 1fr 1fr", gap: 8 }}>{Object.entries(SYS.PROCUREMENT).map(([k, M]) => <button key={k} className="sp-opt" aria-pressed={meth === k} onClick={() => onFlow({ ...F0, method: k })}><b style={{ display: "block", fontSize: 15 }}>{M.nm}</b><span style={{ fontSize: 13, color: "#5b6b55" }}>{Math.round(M.price * 100)}% of price{M.cor > 0 ? " · corruption risk" : ""}</span></button>)}</div>
      {spLab("Bidders")}
      <div style={{ display: "grid", gap: 8 }}>{list.map(c => <div key={c.id} className="sp-card" style={{ padding: "12px 14px", boxShadow: "none", borderColor: c.nepotism || c.mine ? "#efc2bc" : c.player ? "#e9cf8a" : "#e7dcc4", background: c.player && !c.mine ? "#fffbef" : undefined, opacity: c.full ? .6 : 1 }}>
        <div style={{ display: "flex", justifyContent: "space-between", gap: 10, alignItems: "center", flexWrap: "wrap" }}>
          <div style={{ minWidth: 0 }}><b style={{ font: "700 17px 'Plus Jakarta Sans', sans-serif", color: "#17301f" }}>{c.name}</b>{c.player && <span style={{ marginLeft: 8, verticalAlign: "middle", fontSize: 12, fontWeight: 800, borderRadius: 999, padding: "2px 9px", background: c.mine ? "#fdecea" : "#fff2c9", color: c.mine ? "#a3271c" : "#7a5a00" }}>{c.mine ? "Your company" : "★ Player-owned"}</span>}<div style={{ fontSize: 13, color: c.nepotism || c.mine ? "#b3261e" : "#7a6c4c" }}>{SYS.fmtM(Math.round(proj.estimateM * c.price * (SYS.PROCUREMENT[meth] || {}).price))} · {c.active}/{c.capacity} jobs{c.nepotism || c.player ? " · " + c.note : ""}</div></div>
          <button className="sp-btn" disabled={c.full} onClick={() => onAward(proj.id, c.id, meth)} style={{ minHeight: 42, padding: "8px 16px", fontSize: 15 }}>{c.full ? "Fully booked" : "Award contract"}</button>
        </div>
        {(() => { const cv = SYS.contractCover(proj, c, meth); return <div style={{ fontSize: 14, marginTop: 6, color: cv.covered ? "#0b6b42" : "#a3271c", fontWeight: 700 }}>Contract sum {SYS.fmtM(cv.sum)}: {cv.over <= 0 ? "within your budget" : cv.covered ? SYS.fmtM(cv.over) + " over, covered by the 10% contingency" : SYS.fmtM(cv.over) + " over your budget. The money runs out before the work is done unless you add funding."}</div>; })()}
        <div style={{ display: "flex", flexWrap: "wrap", gap: "4px 16px", marginTop: 8 }}>{bar("Reliable", c.reliability)}{bar("Quality", c.quality)}{bar("Speed", c.speed)}{bar("Integrity", c.integrity)}</div>
        <Brief label="About this firm">{c.note}{c.ties ? " Ties: " + c.ties + "." : ""} Also does: {c.sectors.filter(x => x !== proj.sector).map(x => SYS.SECTORS[x].toLowerCase()).slice(0, 3).join(", ") || "nothing else"}.</Brief>
      </div>)}</div>
      <Actions><button className="sp-btn quiet" onClick={() => onFlow(null)}>Later</button></Actions>
    </Dossier>;
  }

  // ── The project dossier (from the adviser or the portfolio) ──
  const Card = ({ p, big }) => { const n = nextOf(p), C = SYS.contractorById(p.contractorId), bf = SYS.benefitFactor(p);
    return <Dossier pic={big ? siteArt(p) : null} thumb={big ? null : siteArt(p)} pin={pinOf(p)} icon={SECTOR_ICON[p.sector] || "🏗️"} kicker={{ pending_finance: "Waiting for money", pending_procurement: "Waiting for a contractor", in_progress: "Under construction", stalled: "Stalled", built: "Built, not working", delivered: "Open", suspended: "Suspended", abandoned: "Abandoned" }[p.status] || p.status} title={p.title} place={where(p) + (C ? " · " + C.name : "")} at={SYS.milestoneOf(p)}>
      <Situation tone={n.blocked ? "bad" : n.due ? "warn" : null} head={n.due ? (n.blocked ? "Blocked" : "Next: " + n.button.toLowerCase()) : p.status === "delivered" ? "Open and working" : "Nothing due yet"} text={n.say + (n.when ? " Next check: " + n.when + "." : "")} />
      <Tiles items={[["Scope costs", SYS.fmtM(p.estimateM)], ["Approved", SYS.fmtM(p.approvedM), p.approvedM < p.estimateM * .95 ? "bad" : null], ["Spent", SYS.fmtM(p.spentM)], p.status === "delivered" || p.status === "built" ? ["Benefit", Math.round(bf * 100) + "%", bf < .6 ? "bad" : "good"] : ["Built", p.progress + "%"]]} />
      {n.due && (n.id === "blocked_finance"
        ? <Actions><button className="sp-btn quiet" onClick={() => onAction(p.id, "abandon")}>Defer indefinitely</button><button className="sp-btn" onClick={() => onAction(p.id, "fit")}>Fit the scope to the budget</button></Actions>
        : <Actions><button className="sp-btn" onClick={() => onOpenStep(p)}>{n.button}</button></Actions>)}
      <Brief>
        <div>Committed, not yet spent: {SYS.fmtM(SYS.committedM(p))} · {SYS.toFinishM(p) > 0 ? "Short of finishing by: " + SYS.fmtM(SYS.toFinishM(p)) : "Enough approved to finish"}{p.loanLeftM > 0 ? " · Loan money in hand: " + SYS.fmtM(p.loanLeftM) : ""}.</div>
        {p.facility && <div>Working: {p.equipped && p.staffed ? "equipped and staffed" : p.equipped ? "equipped, no staff" : "not equipped"}.</div>}
        {(p.events || []).slice(-3).map((ev, i) => <div key={i} style={{ color: "#9a5b12" }}>• {ev}</div>)}
        {(p.decisions || []).length > 0 && <div style={{ marginTop: 4 }}>Record: {p.decisions.slice(-4).map(x => "Year " + x.year + ": " + x.text).join(" · ")}</div>}
        <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginTop: 8 }}>
          {(p.status === "stalled" || p.status === "in_progress") && SYS.toFinishM(p) > 0 && <button className="sp-btn ghost" onClick={() => onAction(p.id, "fund")}>Add {SYS.fmtM(SYS.toFinishM(p))}</button>}
          {["stalled", "in_progress", "pending_finance"].includes(p.status) && <button className="sp-btn ghost" onClick={() => onAction(p.id, "reduce")}>Cut the scope</button>}
          {(p.status === "stalled" || p.status === "in_progress") && <button className="sp-btn ghost" onClick={() => onAction(p.id, "replace")}>Replace the contractor</button>}
          {p.status === "in_progress" && <button className="sp-btn ghost" onClick={() => onAction(p.id, "suspend")}>Suspend</button>}
          {["stalled", "pending_finance"].includes(p.status) && <button className="sp-btn ghost" onClick={() => onAction(p.id, "abandon")}>{p.status === "pending_finance" ? "Defer indefinitely" : "Abandon"}</button>}
          {p.facility && p.status === "built" && p.equipped && !p.staffed && <button className="sp-btn ghost" onClick={() => onAction(p.id, "staff")}>Staff it</button>}
        </div>
      </Brief>
      {big && <Actions><button className="sp-btn quiet" onClick={() => onFlow(null)}>Close</button></Actions>}
    </Dossier>; };
  if (F0 && F0.step === "dossier" && proj) return <Card p={proj} big />;
  // ── 5. Recorded: the milestone moving, the adviser's next step ──
  // Shown only once the decision is in the project's own record.
  if (F0 && F0.step === "done" && proj) {
    const n = nextOf(proj), C = SYS.contractorById(proj.contractorId), k = F0.kind;
    const recorded = k === "approved" ? true : k === "funded" ? proj.loanKey === F0.loanKey && proj.loanLeftM > 0 : k === "contract" ? proj.status === "in_progress" && proj.contractorId === F0.contractorId : false;
    const S = { approved: ["Approved", "Budget " + SYS.fmtM(proj.approvedM), false, "Budget approved: " + SYS.fmtM(proj.approvedM), "Approval sets the budget. No contract is signed, nothing has been paid and no one is building yet."],
      funded: ["Funded", SYS.fmtM(F0.amountM || 0) + " received", true, SYS.fmtM(F0.amountM || 0) + " received from " + (F0.lender || "the lender"), "The money is held for this project. No contractor has been paid; the debt is on the state's books."],
      contract: ["Contract signed", C ? C.name : "", true, "Contract signed with " + (C ? C.name : "the contractor"), "Work starts this year. How far it gets depends on the money released and on the contractor; you will see it at year end."] }[k];
    if (!S || !recorded) return <Card p={proj} big />;
    return <Dossier pic={k === "contract" ? "project-site-cleared" : null} pin={pinOf(proj)} icon={SECTOR_ICON[proj.sector] || "🏗️"} kicker="Recorded" title={proj.title} place={where(proj) + (C ? " · " + C.name : "")} at={null}>
      <div style={{ margin: "14px 0 4px" }}><MilestoneMove from={F0.fromAt} at={SYS.milestoneOf(proj)} /></div>
      <Situation head={S[3]} text={S[4]} />
      <Tiles items={[["Scope costs", SYS.fmtM(proj.estimateM)], ["Approved", SYS.fmtM(proj.approvedM)], k === "funded" ? ["Loan in hand", SYS.fmtM(proj.loanLeftM), "good"] : ["Spent", SYS.fmtM(proj.spentM)], ["Stage", SYS.MILESTONES[SYS.milestoneOf(proj)][1]]]} />
      <div style={{ marginTop: 14 }}>
        <AdviserDesk name={adviser} alert={n.due} say={n.say + (!n.due && n.when ? " Nothing is due until " + n.when + "." : "")} why={n.due ? (n.blocked ? "It cannot move until this is dealt with." : "Until this is done, " + proj.title + " stays where it is on the strip above.") : null}
          action={n.due ? n.button : "Back to the desk"} onAction={() => n.due ? onOpenStep(proj) : onFlow(null)} onLater={n.due ? () => onFlow(null) : null} soundOn={soundOn} onSound={onSound} />
      </div>
    </Dossier>;
  }


  // ── The portfolio ──
  const mine = (projects || []).filter(p => p.estimateM != null);
  return <div>
    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 10, flexWrap: "wrap", marginBottom: 14 }}>
      <div><div className="sp-kicker">Year {year}</div><div style={{ font: "700 32px/1.1 'Fraunces', serif", color: "#17301f" }}>Projects</div></div>
      <button className="sp-btn" onClick={() => onFlow({ step: "propose", draft: {} })}>＋ New project</button>
    </div>
    {!mine.length && <div className="sp-card" style={{ padding: 22, textAlign: "center", font: "500 16px 'Plus Jakarta Sans', sans-serif", color: "#5b6b55" }}>No projects yet. Answer a need: describe the project, set its budget, find the money and a contractor.</div>}
    <div style={{ display: "grid", gap: 14 }}>{mine.slice().sort((a, b) => (nextOf(b).due ? 1 : 0) - (nextOf(a).due ? 1 : 0)).map(p => <Card key={p.id} p={p} />)}</div>
  </div>;
};

// ─── THE GOLDFIELDS (rules in SYS/deposits.js) ───
const GoldView = ({ D, year, onChoose, onClose }) => {
  const fz = TALL() ? { s: TS(18), m: TS(21), l: TS(28) } : { s: TS(26), m: TS(31), l: TS(44) };
  const b = SYS.beat(D, year), decided = D.decided[year];
  const WC = { good: CL.grn, fair: CL.blu, poor: CL.org, dire: CL.red };
  return <Cd style={{ maxWidth: 920 }}>
    <div style={{ fontSize: fz.s, fontWeight: 800, letterSpacing: 1.4, textTransform: "uppercase", color: CL.td }}>The goldfields · {D.lga} · Year {year}</div>
    <h3 style={{ fontFamily: F.d, color: CL.txt, fontSize: fz.l, margin: "4px 0 6px" }}>{b ? b.title : "The goldfields"}</h3>
    <div style={{ display: "inline-block", fontSize: fz.s, fontWeight: 800, color: D.stage === "resolved" ? CL.grn : D.stage === "entrenched" || D.stage === "escalation" ? CL.red : CL.org, border: "1px solid currentColor", borderRadius: 999, padding: "2px 10px", marginBottom: 10 }}>{SYS.GOLD_STAGE[D.stage]}</div>
    <div style={{ display: "grid", gridTemplateColumns: TALL() ? "1fr 1fr" : "repeat(3, 1fr)", gap: 6, marginBottom: 12 }}>
      {Object.keys(D.m).map(k => [k, SYS.GOOD_HIGH[k] ? 100 - D.m[k] : D.m[k]]).sort((x, y) => y[1] - x[1]).slice(0, 1).map(([k]) => { const w = SYS.word(k, D.m[k]); return <div key={k} style={{ background: CL.bg, border: "1px solid " + CL.bdr, borderRadius: 12, padding: "6px 10px", fontSize: fz.s }}><div style={{ color: CL.td }}>{SYS.MEASURE_NAME[k]}</div><b style={{ color: WC[w] }}>{w}</b></div>; })}
    </div>
    {D.agreement && <div style={{ fontSize: fz.s, color: CL.tm, marginBottom: 8 }}>Agreement with Northstar (Year {D.agreement.year}): {D.agreement.benefitSharing ? "shares benefits with the host communities." : "shares nothing with the communities."} An agreement is not a solution until it has held.</div>}
    {b && !decided && <>
      <More text={b.text + " Known: " + b.known + " Not known: " + b.unknown} max={110} style={{ fontSize: fz.m, color: CL.txt, lineHeight: 1.45, margin: "0 0 10px" }} />
      {b.options.map(o => <button key={o.id} onClick={() => onChoose(o.id)} style={{ textAlign: "left", width: "100%", padding: "10px 14px", borderRadius: 14, border: "1px solid " + CL.bdr, background: CL.card, cursor: "pointer", marginBottom: 8, fontFamily: F.b, color: CL.txt }}>
        <b style={{ display: "block", fontSize: fz.m }}>{o.label}</b><span style={{ fontSize: fz.s, color: CL.tm }}>{o.costM ? SYS.fmtM(o.costM) : "Free"}</span>
      </button>)}
    </>}
    {decided && <div style={{ fontSize: fz.s, color: CL.tm, marginBottom: 10 }}>This year's decision is made. What it changes shows at the end of the year.</div>}
    {(decided || !b) && <div style={{ fontSize: fz.s, color: CL.td, marginTop: 6 }}>{D.history.slice(-3).map((h, i) => <div key={i}>Year {h.year}: {briefly(h.text, 80)}</div>)}</div>}
    <div style={{ textAlign: "right", marginTop: 12 }}><Bt v="ghost" onClick={onClose}>{decided || !b ? "Close" : "Decide later this year"}</Bt></div>
  </Cd>;
};

// ─── VOICE (prototype; rules in SYS/voice.js) ───
// Optional character speech for one scene type: the Secretariat case meeting.
// Off until the player turns it on. Uses the device's own speech engine; no
// account, no cost, nothing leaves the device. Text is always shown first;
// failure, silence or skipping never blocks play; replay never repeats a
// decision; leaving the scene stops the voice; one line at a time.
const SOP_VOICE = (() => {
  const ok = typeof window !== "undefined" && "speechSynthesis" in window && typeof window.SpeechSynthesisUtterance === "function";
  let prefs = { on: false, vol: .9 };
  try { prefs = { ...prefs, ...JSON.parse(localStorage.getItem("sop_voice") || "{}") }; } catch (e) {}
  const all = () => { try { return ok ? window.speechSynthesis.getVoices() : []; } catch (e) { return []; } };
  const stop = () => { try { if (ok) window.speechSynthesis.cancel(); } catch (e) {} };
  const speak = (text, characterId) => {
    if (!ok || !prefs.on || window.SOP_paused || !text) return false;
    stop();
    try {
      const vs = all().filter(v => /^en/i.test(v.lang || "")), p = SYS.voiceFor(characterId, vs.map(v => v.name));
      const u = new window.SpeechSynthesisUtterance(SYS.speakable(text));
      const v = vs.find(x => x.name === p.voice); if (v) u.voice = v;
      u.rate = p.rate; u.pitch = p.pitch; u.volume = prefs.vol; u.onerror = () => {};
      window.speechSynthesis.speak(u); return true;
    } catch (e) { return false; }
  };
  const set = (k, v) => { prefs = { ...prefs, [k]: v }; try { localStorage.setItem("sop_voice", JSON.stringify(prefs)); } catch (e) {} if (!prefs.on) stop(); };
  return { supported: ok, speak, stop, set, get: () => prefs };
})();
window.SOP_VOICE = SOP_VOICE;
const VoiceBar = ({ text, characterId, sceneKey, fz }) => {
  const [p, setP] = React.useState(SOP_VOICE.get());
  // A new line (entering the scene, or the reply to a choice) is read once.
  React.useEffect(() => { SOP_VOICE.speak(text, characterId); }, [sceneKey, text]);
  React.useEffect(() => () => SOP_VOICE.stop(), []); // leaving the scene stops the voice
  if (!SOP_VOICE.supported) return <div style={{ fontSize: fz.s, color: CL.td, margin: "4px 0 8px" }}>🔇 Voice is not available on this device. The text is all there is to it.</div>;
  const b = { border: "1px solid " + CL.bdr, background: CL.card, borderRadius: 999, padding: "4px 12px", fontSize: fz.s, cursor: "pointer", fontFamily: F.b, color: CL.txt, minHeight: 34 };
  return <div style={{ display: "flex", gap: 6, alignItems: "center", flexWrap: "wrap", margin: "4px 0 10px" }}>
    <button aria-pressed={p.on} onClick={() => { SOP_VOICE.set("on", !p.on); setP(SOP_VOICE.get()); if (!p.on) setTimeout(() => SOP_VOICE.speak(text, characterId), 50); }} style={b}>{p.on ? "🔊 Voice on" : "🔈 Voice off"}</button>
    {p.on && <>
      <button onClick={() => SOP_VOICE.speak(text, characterId)} style={b}>↺ Replay</button>
      <button onClick={() => SOP_VOICE.stop()} style={b}>⏭ Skip</button>
      <label style={{ fontSize: fz.s, color: CL.td, display: "flex", alignItems: "center", gap: 6 }}>Volume <input type="range" min={0} max={1} step={.1} value={p.vol} onChange={e => { SOP_VOICE.set("vol", +e.target.value); setP(SOP_VOICE.get()); }} /></label>
    </>}
  </div>;
};

// ─── THE STATE SECRETARIAT ───
// Where the governor meets the cabinet. A general visit opens the directory
// (commissioners, requests for an audience, open cases, commitments); an
// event opens the right meeting directly (focus.caseId). The rules live in
// SYS (game/systems/cases.js); this only shows them and passes choices back.
const SecretariatView = ({ year, ministries, cases, commits, focus, agendaLeft, onClose, onOpen, onMeet, onGather, onDecide, onAppoint, appointPicks, audiences, onAudience, onApplyRestructure }) => {
  const fz = TALL() ? { s: TS(18), m: TS(21), l: TS(28) } : { s: TS(26), m: TS(31), l: TS(44) };
  const holder = (mid) => (ministries || []).find(m => m.id === mid);
  const chip = (t, col) => <span style={{ display: "inline-block", fontSize: fz.s, fontWeight: 800, color: col, background: col + "16", border: "1px solid " + col + "44", borderRadius: 999, padding: "2px 10px", marginRight: 6 }}>{t}</span>;
  const GCOL = { rumour: CL.td, credible: CL.org, documented: CL.org, substantiated: CL.red, unsupported: CL.grn };
  const head = (m, sub) => <div style={{ display: "flex", gap: 14, alignItems: "center", marginBottom: 12 }}>
    <img src={commissionerArt(m.minister, m.perf, m.id)} alt="" style={{ width: TALL() ? 64 : 84, height: TALL() ? 76 : 100, objectFit: "cover", objectPosition: "top", borderRadius: 14, background: CL.grn + "14", flexShrink: 0 }} />
    <div style={{ minWidth: 0 }}>
      <b style={{ fontSize: fz.l, fontFamily: F.d, color: CL.txt, display: "block", lineHeight: 1.15 }}>{m.acting ? "" : "Hon. "}{m.minister}</b>
      <div style={{ fontSize: fz.s, color: CL.td }}>{m.icon} {m.acting ? "Acting Commissioner (Permanent Secretary), " : "Commissioner for "}{m.name}{sub ? " · " + sub : ""}</div>
    </div>
  </div>;

  // ── One case: the meeting, the evidence, the findings, the decision ──
  if (focus && focus.caseId) {
    const c = cases.find(x => x.id === focus.caseId);
    const m = c && holder(c.ministryId);
    if (!c || !m) return <Cd><div style={{ fontSize: fz.m }}>This file is no longer open.</div><div style={{ marginTop: 12 }}><Bt onClick={() => onOpen({ view: "dir" })}>Back to the Secretariat</Bt></div></Cd>;
    const metThisYear = c.meetings.some(x => x.year === year && x.who === m.minister);
    const last = c.meetings[c.meetings.length - 1];
    const myCommits = (commits || []).filter(x => x.caseId === c.id);
    const decided = c.stage === "decided" || c.stage === "closed";
    const ready = SYS.findingsReady(c);
    return <Cd style={{ maxWidth: 900 }}>
      <div style={{ fontSize: fz.s, fontWeight: 800, letterSpacing: 1.4, textTransform: "uppercase", color: CL.td, marginBottom: 8 }}>State Secretariat · Case file · Year {year}</div>
      {head(m, c.officer !== m.minister ? "inherited the file from Hon. " + c.officer : null)}
      {(() => {
        const lastMt = c.meetings[c.meetings.length - 1];
        const line = lastMt && lastMt.year === year ? lastMt.lines.map(l => l.text).join(" ") : "Your Excellency, you wanted to see me about the " + c.ministryName.toLowerCase() + " payments." + (c.meetings.length ? " We spoke about this in Year " + c.meetings[c.meetings.length - 1].year + "." : "");
        return <>
          <div style={{ fontSize: fz.m, color: CL.txt, fontStyle: "italic", lineHeight: 1.45, marginBottom: 2 }}>{"\u201c" + line + "\u201d"}</div>
          <VoiceBar text={line} characterId={"commissioner:" + m.id + ":" + m.minister} sceneKey={c.id + ":" + c.meetings.length} fz={fz} />
        </>;
      })()}
      <div style={{ background: CL.bg, border: "1px solid " + CL.bdr, borderRadius: 14, padding: "10px 14px", marginBottom: 12 }}>
        <div style={{ fontSize: fz.s, color: CL.td, marginBottom: 4 }}>Why you are meeting</div>
        <div style={{ fontSize: fz.m, color: CL.txt, lineHeight: 1.4 }}>{c.what}. {c.officer !== m.minister ? "It happened under Hon. " + c.officer + "." : ""}</div>
        <div style={{ marginTop: 8 }}>{chip(SYS.GRADE_NAME[c.grade], GCOL[c.grade])}{chip(SYS.fmtM(c.amountM) + " in question", CL.blu)}{chip(SYS.STAGE_NAME[c.stage], CL.td)}</div>
      </div>
      <div style={{ fontSize: fz.s, color: CL.td, margin: "4px 0" }}>What you know</div>
      {c.evidence.length ? <ul style={{ margin: "0 0 10px 18px", padding: 0, fontSize: fz.s, color: CL.tm, lineHeight: 1.45 }}>{c.evidence.map(e => <li key={e.id}>{e.label} <span style={{ color: CL.td }}>({e.by}, Year {e.year})</span></li>)}</ul>
        : <div style={{ fontSize: fz.s, color: CL.tm, marginBottom: 10 }}>Only the allegation itself.</div>}
      {!decided && <div style={{ fontSize: fz.s, color: CL.td, marginBottom: 12, lineHeight: 1.4 }}>Still unknown: whether the money was stolen, wasted through carelessness, lost to a failed contractor, or never missing at all.</div>}
      {c.meetings.length > 0 && <div style={{ marginBottom: 12 }}>
        <div style={{ fontSize: fz.s, color: CL.td, marginBottom: 4 }}>Your meetings on this file</div>
        {c.meetings.map((x, i) => <div key={i} style={{ fontSize: fz.s, color: CL.tm, marginBottom: 6, lineHeight: 1.4 }}><b style={{ color: CL.txt }}>Year {x.year}, Hon. {x.who}:</b> {x.lines.map(l => "“" + l.text + "”").join(" ")}</div>)}
        {myCommits.map(x => <div key={x.id} style={{ fontSize: fz.s, color: x.status === "broken" ? CL.red : x.status === "kept" ? CL.grn : CL.org }}>Promised: {x.action} (by Year {x.reviewYear}) · {x.status === "open" ? "pending" : x.status === "kept" ? "done" : "not done"}{x.notes.length ? " · " + x.notes[x.notes.length - 1] : ""}</div>)}
      </div>}
      {!decided && !metThisYear && <div style={{ display: "grid", gap: 8, marginBottom: 12 }}>
        <div style={{ fontSize: fz.s, color: CL.td }}>{last ? "Meet again" : "How do you open the meeting?"} (a meeting is not a major action)</div>
        {[["explain", "🗣️", "Ask for their account", "Let them explain before you decide anything."], ["confront", "📂", "Put the allegation to them", "Show what you know and watch the answer."], ["notice", "⚠️", "Give a formal warning", "On the record. It protects you if this grows; it tells them you suspect them."]].map(([k, ic, l, d]) =>
          <button key={k} onClick={() => onMeet(c.id, k)} style={{ textAlign: "left", display: "grid", gridTemplateColumns: "auto 1fr", gap: 10, alignItems: "center", padding: "10px 14px", borderRadius: 14, border: "1px solid " + CL.bdr, background: CL.card, cursor: "pointer", fontFamily: F.b, color: CL.txt }}>
            <span style={{ fontSize: fz.l }}>{ic}</span><span><b style={{ display: "block", fontSize: fz.m }}>{l}</b><span style={{ fontSize: fz.s, color: CL.tm }}>{d}</span></span>
          </button>)}
      </div>}
      {!decided && c.meetings.length > 0 && <div style={{ display: "grid", gap: 8, marginBottom: 12 }}>
        <div style={{ fontSize: fz.s, color: CL.td }}>Find out more {c.methodsUsed.length ? "" : "(opening a formal investigation uses one of this year's major actions: " + agendaLeft + " left)"}</div>
        {Object.entries(SYS.METHODS).filter(([k]) => !c.methodsUsed.includes(k)).map(([k, M]) =>
          <button key={k} onClick={() => onGather(c.id, k)} style={{ textAlign: "left", padding: "10px 14px", borderRadius: 14, border: "1px solid " + CL.bdr, background: CL.card, cursor: "pointer", fontFamily: F.b, color: CL.txt }}>
            <b style={{ display: "block", fontSize: fz.m }}>🔎 {M.nm}</b><span style={{ fontSize: fz.s, color: CL.tm }}>{M.note}</span>
          </button>)}
      </div>}
      {!decided && ready && <div style={{ background: CL.bg, border: "1px solid " + CL.bdr, borderRadius: 14, padding: "10px 14px", marginBottom: 12 }}>
        <div style={{ fontSize: fz.m, fontWeight: 800, color: CL.txt, marginBottom: 6 }}>Findings: {SYS.GRADE_NAME[c.grade]}</div>
        <div style={{ fontSize: fz.s, color: CL.tm, marginBottom: 8 }}>{c.grade === "substantiated" ? "The file supports misconduct." : c.grade === "documented" ? "Rules were broken; whether it was theft or carelessness is not settled." : c.grade === "unsupported" ? "The evidence points away from wrongdoing." : "Nothing conclusive either way."} You can decide now, or gather more first.</div>
        <div style={{ display: "grid", gap: 8 }}>
          {Object.entries(SYS.DECISIONS).map(([k, D]) => { const ok = !D.needs || D.needs.includes(c.grade);
            return <button key={k} disabled={!ok} onClick={() => ok && onDecide(c.id, k)} style={{ textAlign: "left", padding: "10px 14px", borderRadius: 14, border: "1px solid " + CL.bdr, background: ok ? CL.card : CL.bg, opacity: ok ? 1 : .55, cursor: ok ? "pointer" : "not-allowed", fontFamily: F.b, color: CL.txt, fontSize: fz.m }}>
              {D.nm}{!ok ? <span style={{ display: "block", fontSize: fz.s, color: CL.td }}>Needs at least a documented irregularity.</span> : null}
            </button>; })}
        </div>
      </div>}
      {decided && <div style={{ fontSize: fz.s, color: CL.tm, marginBottom: 12, lineHeight: 1.45 }}>Decided in Year {c.decision.year}: {SYS.DECISIONS[c.decision.id].nm.toLowerCase()}. {c.recoveredM ? SYS.fmtM(c.recoveredM) + " recovered. " : ""}{c.outstandingM ? SYS.fmtM(c.outstandingM) + " is still missing and stays on the state's books." : ""}</div>}
      <div style={{ display: "flex", gap: 10, flexWrap: "wrap", justifyContent: "flex-end" }}>
        <Bt v="ghost" onClick={() => onOpen({ view: "dir" })}>The Secretariat</Bt>
        <Bt onClick={onClose}>{focus.from ? "Back to where you were" : "Done"}</Bt>
      </div>
    </Cd>;
  }

  // ── An audience a commissioner asked for ──
  if (focus && focus.audience) {
    const a = (audiences || []).find(x => x.id === focus.audience), m = a && holder(a.ministryId);
    if (!a || !m) return <Cd><div style={{ fontSize: fz.m }}>That audience has passed.</div><div style={{ marginTop: 12 }}><Bt onClick={() => onOpen({ view: "dir" })}>Back to the Secretariat</Bt></div></Cd>;
    return <Cd style={{ maxWidth: 900 }}>
      <div style={{ fontSize: fz.s, fontWeight: 800, letterSpacing: 1.4, textTransform: "uppercase", color: CL.td, marginBottom: 8 }}>State Secretariat · Audience · Year {year}</div>
      {head(m)}
      {a.memory && <div style={{ fontSize: fz.s, color: CL.td, marginBottom: 8, fontStyle: "italic" }}>{a.memory}</div>}
      <div style={{ fontSize: fz.m, color: CL.txt, lineHeight: 1.45, marginBottom: 12 }}>“{a.say}”</div>
      <div style={{ display: "grid", gap: 8, marginBottom: 12 }}>
        {a.options.map(o => <button key={o.id} onClick={() => onAudience(a, o)} style={{ textAlign: "left", padding: "10px 14px", borderRadius: 14, border: "1px solid " + CL.bdr, background: CL.card, cursor: "pointer", fontFamily: F.b, color: CL.txt }}>
          <b style={{ display: "block", fontSize: fz.m }}>{o.label}</b><span style={{ fontSize: fz.s, color: CL.tm }}>{o.note}</span>
        </button>)}
      </div>
      <div style={{ textAlign: "right" }}><Bt v="ghost" onClick={() => onOpen({ view: "dir" })}>See them later</Bt></div>
    </Cd>;
  }

  // ── Restructuring the government (SYS.ministries) ──
  if (focus && focus.restructure) {
    const R = focus.restructure, plan = SYS.planRestructure(R.kind, { ministries, a: R.a, b: R.b, area: R.area, name: R.name, lead: R.lead });
    const field = { padding: 10, fontSize: fz.m, border: "1px solid " + CL.bdr, borderRadius: 10, width: "100%", boxSizing: "border-box", background: "#fff", color: CL.txt, fontFamily: F.b };
    const set = (k, v) => onOpen({ ...focus, restructure: { ...R, [k]: v } });
    const sel = (k, label, list) => <label style={{ display: "block", marginBottom: 8 }}><span style={{ fontSize: fz.s, color: CL.td }}>{label}</span><select value={R[k] || ""} onChange={e => set(k, e.target.value)} style={field}><option value="">Choose…</option>{list.map(m => <option key={m.id} value={m.id}>{m.name}</option>)}</select></label>;
    return <Cd style={{ maxWidth: 900 }}>
      <h3 style={{ fontFamily: F.d, color: CL.txt, fontSize: fz.l, margin: "0 0 8px" }}>Restructure the government</h3>
      <div style={{ display: "grid", gridTemplateColumns: TALL() ? "1fr" : "1fr 1fr", gap: 8, marginBottom: 10 }}>
        {Object.entries(SYS.RESTRUCTURE).map(([k, X]) => <button key={k} onClick={() => onOpen({ ...focus, restructure: { kind: k } })} style={{ textAlign: "left", padding: "8px 12px", borderRadius: 12, border: "2px solid " + (R.kind === k ? CL.grn : CL.bdr), background: R.kind === k ? CL.grn + "10" : CL.card, cursor: "pointer", fontFamily: F.b, color: CL.txt, fontSize: fz.s }}><b style={{ display: "block", fontSize: fz.m }}>{X.nm}</b>{X.why}</button>)}
      </div>
      {R.kind && sel("a", R.kind === "merge" ? "First ministry" : R.kind === "reassign" ? "Move the area out of" : "From the area of", ministries.filter(m => !m.taskForce))}
      {(R.kind === "merge" || R.kind === "reassign") && sel("b", R.kind === "merge" ? "Second ministry" : "Into", ministries.filter(m => m.id !== R.a && !m.taskForce))}
      {(R.kind === "split" || R.kind === "taskforce") && <label style={{ display: "block", marginBottom: 8 }}><span style={{ fontSize: fz.s, color: CL.td }}>Name</span><input value={R.name || ""} onChange={e => set("name", e.target.value)} placeholder={R.kind === "split" ? "e.g. Water Resources" : "e.g. Flood Response"} style={field} /></label>}
      {R.kind === "merge" && R.a && R.b && <label style={{ display: "block", marginBottom: 8 }}><span style={{ fontSize: fz.s, color: CL.td }}>Who leads it</span><select value={R.lead || R.a} onChange={e => set("lead", e.target.value)} style={field}>{[R.a, R.b].map(id => { const m = ministries.find(x => x.id === id); return m && <option key={id} value={id}>Hon. {m.minister} ({m.name})</option>; })}</select></label>}
      {R.kind && (plan.ok ? <div style={{ background: CL.bg, border: "1px solid " + CL.bdr, borderRadius: 14, padding: "10px 14px", fontSize: fz.s, color: CL.tm, lineHeight: 1.5 }}>
        <div><b style={{ color: CL.txt }}>Mandate:</b> {plan.mandate}</div>
        <div><b style={{ color: CL.txt }}>Set-up:</b> {SYS.fmtM(plan.setupM)} · <b style={{ color: CL.txt }}>Every year:</b> {plan.budgetSource}</div>
        {plan.lead && <div><b style={{ color: CL.txt }}>Led by:</b> Hon. {plan.lead}</div>}
        <div><b style={{ color: CL.txt }}>Transition:</b> {plan.transition ? "about a year of slower work while it settles" : "none"}. It will not fix the problem by itself.</div>
        <div style={{ marginTop: 10, textAlign: "right" }}><Bt onClick={() => onApplyRestructure(plan)}>Make the change (uses 1 of {agendaLeft} major actions)</Bt></div>
      </div> : <div style={{ fontSize: fz.s, color: CL.org }}>{plan.reason}</div>)}
      <div style={{ textAlign: "right", marginTop: 12 }}><Bt v="ghost" onClick={() => onOpen({ view: "dir" })}>Back</Bt></div>
    </Cd>;
  }

  // ── The directory ──
  const openCases = cases.filter(c => c.stage !== "closed" && c.stage !== "decided"); // decided files leave the list; what follows from them arrives as news
  const openCommits = (commits || []).filter(x => x.status === "open");
  return <Cd style={{ maxWidth: 960 }}>
    <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", gap: 10, marginBottom: 10 }}>
      <h3 style={{ fontFamily: F.d, color: CL.txt, fontSize: fz.l, margin: 0 }}>🏢 The State Secretariat</h3>
      <span style={{ fontSize: fz.s, color: CL.td }}>Year {year} · {agendaLeft} major actions left</span>
    </div>
    {(audiences || []).length > 0 && <div style={{ marginBottom: 12 }}>
      <div style={{ fontSize: fz.s, color: CL.td, marginBottom: 6 }}>Asking to see you</div>
      {audiences.map(a => { const m = holder(a.ministryId); return m && <button key={a.id} onClick={() => onOpen({ audience: a.id })} style={{ display: "flex", width: "100%", gap: 10, alignItems: "center", textAlign: "left", padding: "8px 12px", borderRadius: 14, border: "1px solid " + CL.org + "55", background: CL.org + "0d", cursor: "pointer", marginBottom: 6, fontFamily: F.b, color: CL.txt }}>
        <img src={commissionerArt(m.minister, m.perf, m.id)} alt="" style={{ width: 40, height: 48, objectFit: "cover", objectPosition: "top", borderRadius: 10 }} />
        <span style={{ fontSize: fz.s }}><b>{m.acting ? "" : "Hon. "}{m.minister}</b> ({m.name}): {a.reason}</span></button>; })}
    </div>}
    {openCases.length > 0 && <div style={{ marginBottom: 12 }}>
      <div style={{ fontSize: fz.s, color: CL.td, marginBottom: 6 }}>Open files</div>
      {openCases.map(c => <button key={c.id} onClick={() => onOpen({ caseId: c.id })} style={{ display: "block", width: "100%", textAlign: "left", padding: "8px 12px", borderRadius: 14, border: "1px solid " + CL.bdr, background: CL.card, cursor: "pointer", marginBottom: 6, fontFamily: F.b, color: CL.txt, fontSize: fz.s }}>
        📁 <b>{c.ministryName}</b>: {c.what} · {SYS.GRADE_NAME[c.grade]} · {SYS.STAGE_NAME[c.stage]}</button>)}
    </div>}
    <div style={{ fontSize: fz.s, color: CL.td, marginBottom: 6 }}>The cabinet</div>
    <div style={{ display: "grid", gridTemplateColumns: TALL() ? "1fr" : "1fr 1fr", gap: 8 }}>
      {(ministries || []).map(m => { const mc = openCases.filter(c => c.ministryId === m.id).length, mk = openCommits.filter(x => x.ministryId === m.id).length;
        return <div key={m.id} style={{ display: "flex", gap: 10, alignItems: "center", padding: "8px 10px", borderRadius: 14, border: "1px solid " + CL.bdr, background: CL.card }}>
          <img src={commissionerArt(m.minister, m.perf, m.id)} alt="" style={{ width: 44, height: 52, objectFit: "cover", objectPosition: "top", borderRadius: 10, flexShrink: 0 }} />
          <div style={{ minWidth: 0, flex: 1, fontSize: fz.s, color: CL.tm }}>
            <b style={{ color: CL.txt }}>{m.acting ? "Acting: " : "Hon. "}{m.minister}</b><div>{m.icon} {m.name}{mc ? " · " + mc + " open file" + (mc > 1 ? "s" : "") : ""}{mk ? " · " + mk + " commitment" + (mk > 1 ? "s" : "") : ""}</div>
            {m.acting && <div style={{ marginTop: 4, display: "flex", gap: 6, flexWrap: "wrap" }}>{(appointPicks(m) || []).map(p => <button key={p.nm} onClick={() => onAppoint(m.id, p)} style={{ border: "1px solid " + CL.grn + "66", background: CL.grn + "12", color: CL.grn, borderRadius: 999, padding: "4px 10px", fontSize: fz.s, cursor: "pointer", fontFamily: F.b }}>Appoint {p.nm} ({p.bg.toLowerCase()})</button>)}</div>}
          </div>
        </div>; })}
    </div>
    {openCommits.length > 0 && <div style={{ marginTop: 12 }}>
      <div style={{ fontSize: fz.s, color: CL.td, marginBottom: 6 }}>Commitments still open</div>
      {openCommits.map(x => <div key={x.id} style={{ fontSize: fz.s, color: CL.tm, marginBottom: 4 }}>• Hon. {x.who} ({(holder(x.ministryId) || {}).name || x.ministryId}): {x.action}, by Year {x.reviewYear}{x.resourcesM ? " · " + SYS.fmtM(x.resourcesM) : ""}</div>)}
    </div>}
    <div style={{ display: "flex", justifyContent: "space-between", gap: 10, marginTop: 14, flexWrap: "wrap" }}><Bt v="ghost" onClick={() => onOpen({ restructure: {} })}>🔀 Restructure the government</Bt><Bt onClick={onClose}>Leave the Secretariat</Bt></div>
  </Cd>;
};

/* The Hall of Governors: today's board (one entry a day each), the week's
   board (locked until Monday, then each governor's best day), the all-time
   Hall and the weekly challenge. Tiers: SYS.TIERS (Gold 950+, Silver 800+,
   Bronze 650+). */
const HALL_TABS = [["today", "Today"], ["week", "Last week"], ["all", "All time"], ["challenge", "Challenge"]];
const HallBoard = ({ tab: tab0 = "today", note }) => {
  const [tab, setTab] = useState(tab0), [b, setB] = useState(null);
  useEffect(() => {
    let live = true; setB(null);
    const get = tab === "today" ? window.SOP_hallToday : tab === "week" ? window.SOP_hallWeek : tab === "all" ? window.SOP_hallBoard : window.SOP_chBoard && (() => window.SOP_chBoard(weekNow()));
    if (!get) { setB({ offline: true }); return; }
    get().then(r => { if (live) setB(r || { offline: true }); }).catch(() => { if (live) setB({ error: true }); });
    return () => { live = false; };
  }, [tab]);
  const medal = (t) => (SYS.TIERS.find(x => x.id === t) || {}).icon || "";
  const days = (at) => Math.max(1, Math.ceil((at - Date.now()) / 86400000));
  return <div>
    <div style={{ display: "grid", gridTemplateColumns: "repeat(4, 1fr)", gap: 6, marginBottom: 10 }}>
      {HALL_TABS.map(([k, l]) => <button key={k} onClick={() => setTab(k)} aria-pressed={tab === k} style={{ borderRadius: 999, padding: "8px 6px", minHeight: 40, fontWeight: 800, fontSize: DS.t.meta, fontFamily: F.b, border: "1.5px solid " + (tab === k ? UI.green : UI.line), background: tab === k ? UI.green : "#fff", color: tab === k ? "#fff" : UI.ink, cursor: "pointer" }}>{l}</button>)}
    </div>
    <div style={{ fontSize: DS.t.meta, color: UI.sub, marginBottom: 8, lineHeight: 1.45 }}>{SYS.TIERS.map(t => t.icon + " " + t.nm + " " + t.min + "+").join(" · ")}{tab === "today" ? " · one entry a day" : tab === "week" && b && b.opensAt ? " · this week's board opens in " + days(b.opensAt) + " day" + (days(b.opensAt) === 1 ? "" : "s") : ""}</div>
    {note}
    {!b ? <div style={{ fontSize: DS.t.label, color: UI.sub }}>Loading…</div>
      : b.offline ? <div style={{ fontSize: DS.t.label, color: UI.sub, lineHeight: 1.5 }}>The Hall of Governors is public in Lagos Life. Play there and your results appear here under your username.</div>
      : b.error ? <div style={{ fontSize: DS.t.label, color: UI.sub }}>The board couldn't be loaded. Try again in a moment.</div>
      : b.locked ? <div style={{ fontSize: DS.t.label, color: UI.sub }}>🔒 This week's board opens on Monday.</div>
      : !(b.top || []).length ? <div style={{ fontSize: DS.t.label, color: UI.sub, lineHeight: 1.5 }}>{tab === "today" ? "No governor has entered a result today. Be the first." : tab === "week" ? "Nobody entered a result last week." : "No results yet."}</div>
      : <div style={{ display: "grid", gap: 6 }}>{b.top.map(e => <div key={e.rank} style={{ display: "grid", gridTemplateColumns: "34px 1fr auto", gap: 8, alignItems: "center", padding: "8px 12px", borderRadius: 14, background: e.me ? UI.green + "18" : "#fff", border: "1px solid " + (e.me ? UI.green : UI.line) }}>
          <b style={{ fontFamily: F.d, fontSize: TS(24) }}>{e.rank}</b>
          <span style={{ minWidth: 0 }}><b style={{ display: "block", fontSize: DS.t.body }}>{medal(e.tier || (SYS.tierOf(e.score) || {}).id)} {e.name}{e.me ? " (you)" : ""}</b><span style={{ fontSize: DS.t.meta, color: UI.sub }}>{[e.title, e.state, e.grade && "Grade " + e.grade].filter(Boolean).join(" · ")}</span></span>
          <b style={{ fontFamily: F.m }}>{e.score}</b></div>)}</div>}
    {b && b.you && <div style={{ fontSize: DS.t.label, color: UI.sub, marginTop: 10 }}>You: #{b.you.rank} of {b.players}, score {b.you.score}.</div>}
    {b && tab === "today" && b.players >= 10 && b.pct > 0 && <div style={{ fontSize: DS.t.label, color: UI.sub, marginTop: 6 }}>{b.pct}% of governors played again for a better result.</div>}
  </div>;
};

// The presidential pilot (Lovable Pack 16 brings his own portrait).
