    rows = [{ l: "Your move", v: (d1 >= 0 ? "+" : "−") + Math.abs(d1) + "%", good: d1 >= 0 }, { l: "Their strike", v: (d2 >= 0 ? "+" : "−") + Math.abs(d2) + "%", good: d2 >= 0 }];
