const ExecutiveCommandSA = ({ adviser, brief, inbox, vacantTurns, onFire }) => {
  const [open, setOpen] = React.useState(false);
  const tone = brief?.urgent ? CL.red : CL.grn;
  const urgentCount = inbox.filter(i => i.urgent && !i.done).length;
  const doneCount = inbox.filter(i => i.done).length;
  return (
    <div style={{ background: CL.card, border: "1px solid " + CL.bdr, borderRadius: 17, padding: TALL() ? "14px 14px" : "22px 29px", marginBottom: 8 }}>
      <div onClick={() => setOpen(o => !o)} style={{ display: "flex", gap: TALL() ? 18 : 29, alignItems: "center", cursor: "pointer", flexWrap: TALL() ? "wrap" : "nowrap" }}>
        <div style={{ width: TALL() ? 56 : 98, height: TALL() ? 56 : 98, borderRadius: "50%", background: CL.grn + "18", overflow: "hidden", fontSize: TS(40), display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>{adviser ? <img src={saPortrait(adviser.name)} alt="" style={{ width: "100%", height: "140%", objectFit: "cover", objectPosition: "top" }} /> : "🪑"}</div>
        <div style={{ flex: 1, minWidth: 1 }}>
          <div style={{ fontSize: TALL() ? TS(18) : TS(27), color: CL.td, fontWeight: 700 }}>Adviser's agenda {urgentCount > 0 && <span style={{ background: CL.red, color: "#fff", padding: "0 14px", borderRadius: 13, marginLeft: 14 }}>{urgentCount}</span>}</div>
          <div style={{ color: CL.txt, fontWeight: 700, fontSize: TALL() ? TS(22) : TS(36), lineHeight: 1.25 }}>{brief?.title || (adviser ? adviser.name : "SA seat vacant")}</div>
        </div>
        {brief?.action && <button onClick={(e) => { e.stopPropagation(); brief.action(); }} style={{ ...(TALL() ? { order: 3, flexBasis: "100%" } : {}), border: 0, background: CL.grn, color: "#fff", borderRadius: 999, padding: TALL() ? "10px 16px" : "14px 26px", minHeight: 44, fontSize: TALL() ? TS(20) : TS(29), fontWeight: 800, cursor: "pointer", whiteSpace: "nowrap" }}>{brief.actionLabel}</button>}
        <div style={{ fontSize: TS(29), color: CL.td, marginLeft: 14 }}>{open ? "▲" : "▼"}</div>
      </div>
      {open && <div style={{ marginTop: 29, borderTop: "1px dashed " + CL.bdr, paddingTop: 29 }}>
        {adviser && <div style={{ fontSize: TS(34), color: CL.tm, marginBottom: 22, lineHeight: 1.4 }}><b>{adviser.name}</b> · {adviser.title}<br/><i style={{ fontSize: TS(31), color: CL.td }}>{adviser.file}</i></div>}
        {!adviser && <div style={{ fontSize: TS(34), color: CL.red, marginBottom: 22 }}>Seat vacant · replacement in {vacantTurns} turn{vacantTurns === 1 ? "" : "s"}</div>}
        {brief && <div style={{ background: tone + "0d", border: "1px solid " + tone + "33", borderRadius: 13, padding: "22px 29px", marginBottom: 22, fontSize: TS(36), color: CL.tm, lineHeight: 1.45 }}>{brief.body}</div>}
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(192px, 1fr))", gap: 14 }}>
          {inbox.map((it, i) => <button key={i} onClick={it.action} disabled={!it.action} style={{ textAlign: "left", border: "1px solid " + (it.done ? CL.grn + "55" : it.urgent ? CL.red + "55" : CL.bdr), background: it.done ? CL.grn + "10" : it.urgent ? CL.red + "10" : "#fff", borderRadius: 11, padding: "14px 22px", cursor: it.action ? "pointer" : "default" }}>
            <div style={{ fontSize: TS(31), fontWeight: 800, color: it.done ? CL.grn : it.urgent ? CL.red : CL.tm }}>{it.done ? "✓ " : it.urgent ? "! " : ""}{it.label}</div>
            <div style={{ fontSize: TS(29), color: CL.td, marginTop: 5, lineHeight: 1.3 }}>{it.detail}</div>
          </button>)}
        </div>
        <div style={{ display: "flex", justifyContent: "space-between", marginTop: 22, fontSize: TS(29), color: CL.td }}>
          <span>{doneCount}/{inbox.length} agenda items complete</span>
          {adviser && <button onClick={onFire} style={{ border: 0, background: "transparent", color: CL.red, fontSize: TS(31), fontWeight: 700, cursor: "pointer" }}>🔥 Fire adviser</button>}
        </div>
      </div>}
    </div>
  );
};



function App() {
  // Re-render on rotation so TALL() layouts switch with the screen.
  const [, setShape] = useState(TALL());
  useEffect(() => {
    const on = () => setShape(TALL());
    window.addEventListener("resize", on);
    return () => window.removeEventListener("resize", on);
  }, []);
  const [scr, setScr] = useState("title");
  const [level, setLevel] = useState("medium");
  const [setup, setSetup] = useState(null);
  const [showHelp, setShowHelp] = useState(false);
  const [finalStats, setFinalStats] = useState(null);
  const [loadedSave, setLoadedSave] = useState(null);
  const rst = () => { setScr("title"); setSetup(null); setFinalStats(null); setLoadedSave(null); };
  // After a defeat: four years in opposition, then the same politician back on the ballot in the same state.
  // A defeated governor runs again four years on: with the old team, or a new one. Either
  // way only one term is left (S.182(1)(b): two terms in all).
  const comeback = async (team) => {
    const stName = String((setup && setup.state) || (profile && profile.state) || "your state").replace(/_/g, " ");
    let keep = false;
    if (team && team.setup && team.terms === 1) {
      const dep = team.setup.depGov && team.setup.depGov.nm, n = (team.ministries || []).length;
      keep = await window.SOP_confirm("Bring back your old team?\n\n" + [dep && "Running mate: " + dep, team.setup.saName && "Special Adviser: " + team.setup.saName, team.cos && team.cos.name && "Chief of Staff: " + team.cos.name, n && n + " commissioner" + (n === 1 ? "" : "s"), team.setup.party && "The " + team.setup.party + " ticket, the same agenda and slogan"].filter(Boolean).join("\n") + "\n\nOr start again and choose everyone afresh. Either way, you have four years left: the Constitution allows two terms in all.", "Bring back my team", "Choose a new team");
      track("comeback", keep ? "same team" : "new team");
    }
    seedRandom(null); try { window.dispatchEvent(new CustomEvent("sop-new-game")); } catch (e) {}
    setStartProfile(profile ? { ...profile, state: (setup && setup.state) || profile.state } : null); setStartMode(team && team.terms === 1 ? { kind: "comeback", team: keep ? team : null, startYear: team.startYear || 2027 } : null); setSetup(null); setLoadedSave(null); setScr("setup");
    try { window.SOP_outcome && window.SOP_outcome({ icon: "🔁", title: "Four years in opposition", text: "You spent them in " + stName + ", holding the new government to account. Now the primaries are open again, and your name is on the ballot. Win, and these four years are your last.", tone: "good",
      learn: "There is no limit on returning: a governor who lost may run again. The Constitution only limits anyone to two terms as governor in total (S.182(1)(b))." }); } catch (e) {}
  };

  // The Presidency preview: your politician, just elected President, straight to the oath.
  const presidencyPreview = (p) => {
    const st = (p && p.origin && STATES[p.origin] && p.origin !== "FCT") ? p.origin : "Enugu", z = STATES[st].zone, r = rng(Date.now() % 99991);
    const party = p && MAIN_PARTY_IDS.includes(p.leaning) ? p.leaning : "NRA", P = PARTIES.find(x => x.id === party) || PARTIES[0], O = PARTIES.find(x => MAIN_PARTY_IDS.includes(x.id) && x.id !== party) || PARTIES[1];
    const G = { v: 1, seed: Date.now(), name: p ? (p.first + " " + p.last) : gN(r, z, st), avatar: (p && p.avatar) || "agbada", state: st, zone: z, party, partyNm: P.nm, from: "senator", bio: null, chest: 3, cor: .3,
      opp: { name: gN(r, z === "NW" ? "SW" : "NW", NATION), party: O.id, partyNm: O.nm, zone: z === "NW" ? "SW" : "NW" }, ious: [], pledges: [], mate: { name: gN(r, "NC", NATION), zone: "NC", kind: "partyman" },
      zones: { NW: 52, NE: 50, NC: 54, SW: 53, SE: 51, SS: 52 }, res: { nat: 52.4, statesWon: 21, s25: 29 } };
    seedRandom(null); try { window.dispatchEvent(new CustomEvent("sop-new-game")); } catch (e) {}
    track("preview", "presidency");
    setSetup(presidentSetup(G, { level })); setLoadedSave(null); setScr("gov");
  };
  // The politician profile on this device, used by the entrance and setup.
  const [profile, setProfile] = useState(null);
  const [startProfile, setStartProfile] = useState(null);
  const [startMode, setStartMode] = useState(null); // { kind: "challenge", week, state } | { kind: "scenario", id }
  const [board, setBoard] = useState(null);
  const beginChallenge = async (p) => {
    const ch = challengeOf(weekNow());
    try {
      let r = window.SOP_chStart ? await window.SOP_chStart() : { ok: true };
      if (!r.ok && r.need === "challenge_retry") {
        const yes = await window.SOP_confirm("You have played this week's challenge. Another attempt costs ₦100. Your best score this week is the one that counts.", "Play again · ₦100", "Not now");
        if (!yes) return;
        await window.SOP_buy("challenge_retry");
        r = await window.SOP_chStart();
        if (!r.ok) return;
      }
    } catch (e) { if (e && e.code === "cancelled") return; }
    seedRandom(ch.seed);
    try { window.dispatchEvent(new CustomEvent('sop-new-game')); } catch (e) {}
    setStartProfile(p || null); setStartMode({ kind: "challenge", week: ch.week, state: ch.state }); setLevel("medium"); setScr("setup");
  };
  const beginScenario = (p, id) => { seedRandom(null); try { window.dispatchEvent(new CustomEvent('sop-new-game')); } catch (e) {} setStartProfile(p || null); setStartMode({ kind: "scenario", id }); setScr("setup"); };
  // The Hall of Governors: this week's challenge board and the all-time board, both by Lagos Life username.
  const openBoard = async (tab = "week") => {
    setBoard({ tab, loading: true, top: [], players: 0 });
    const get = tab === "all" ? window.SOP_hallBoard : window.SOP_chBoard && (() => window.SOP_chBoard(weekNow()));
    if (!get) { setBoard({ tab, top: [], players: 0, offline: true }); return; }
    try { const b = await get(); setBoard({ tab, ...(b || { top: [], players: 0, offline: !b }) }); } catch (e) { setBoard({ tab, top: [], players: 0, error: true }); }
  };
  useEffect(() => { loadProfile().then(p => { if (p) { window.SOP_FRAME = p.frame || null; setProfile(p); } }); }, [scr]);
  // Player companies join every contractor list. On the home screen, the owner hears how often other governors used theirs.
  useEffect(() => { loadCompanies().then(r => {
    const M = r && r.mine; if (scr !== "title" || !M || M.hidden || !(M.uses > (M.told || 0))) return;
    const fresh = M.uses - (M.told || 0), owed = Math.round((M.owedM || 0) * 10) / 10;
    try { window.SOP_outcome && window.SOP_outcome({ icon: "🏗️", title: "Your company is working", text: M.name + " has been used " + M.uses + " time" + (M.uses === 1 ? "" : "s") + " in the governorship by " + M.hires + " governor" + (M.hires === 1 ? "" : "s") + (fresh < M.uses ? " (" + fresh + " new since you last looked)" : "") + "." + (owed > 0 ? " ₦" + owed + "M in fees waits for your next campaign." : ""), tone: "good", coins: owed > 0, ok: "Good to know" }); } catch (e) {}
    try { window.SOP_companyTold && window.SOP_companyTold(); } catch (e) {}
  }); }, [scr]);

  const loadGame = async () => {
    try {
      const r = await window.storage.get("sop_save");
      if (r?.value) {
        const d = migrateSave(JSON.parse(r.value));
        try { if (d.setup?.customParty) registerParty(d.setup.customParty); if (d.setup?.party && LEGACY_PARTIES[d.setup.party]) registerParty(LEGACY_PARTIES[d.setup.party]); } catch (e) {}
        // Restore the Historic Ledger BEFORE the governing screen mounts, so
        // the tribunal, EFCC case file and adviser all wake with their memory.
        try { if (d.ledger && window.SOP_LEDGER?.hydrate) window.SOP_LEDGER.hydrate(d.ledger); } catch (e) {}
        try { if (d.civic && window.SOP_CIVIC?.restore) window.SOP_CIVIC.restore(d.civic); } catch (e) {}
        try { if (d.politics && window.SOP_POLITICS?.hydrate) window.SOP_POLITICS.hydrate(d.politics); } catch (e) {}
        setSetup(d.setup);
        setLevel(d.setup?.level || "medium");
        setLoadedSave(d);
        setScr("gov");
      }
    } catch (e) { console.error("Load failed", e); }
  };

  return (
    <div style={{ fontFamily: F.b, background: CL.bg, color: CL.txt, minHeight: "100%" }}>
      <style>{`
        @media (max-width: 640px) {
          .sop-gov-grid { grid-template-columns: 1fr !important; }
          .sop-2col { grid-template-columns: 1fr !important; }
        }
        /* Portrait: the stage is 720 design px wide, so the media query above
           never fires; stack the two-column pages here instead. */
        #sop-stage.sop-tall .sop-gov-grid, #sop-stage.sop-tall .sop-2col { grid-template-columns: 1fr !important; }

        /* ── sp-: the governing slice's design system (adviser, dossier) ── */
        .sp-card { background: #fffdf8; border: 1px solid #e7dcc4; border-radius: 22px; box-shadow: 0 1px 0 #fff inset, 0 12px 30px rgba(18,48,31,.10); }
        .sp-btn { appearance: none; border: 0; border-radius: 999px; min-height: 48px; padding: 11px 22px; font: 800 17px/1.15 'Plus Jakarta Sans', sans-serif; letter-spacing: .1px; background: #12301f; color: #fff; cursor: pointer; box-shadow: 0 6px 16px rgba(18,48,31,.24); transition: transform .12s ease, box-shadow .12s ease, background .15s ease; }
        .sp-btn:hover { background: #0b6b42; transform: translateY(-1px); box-shadow: 0 9px 20px rgba(11,107,66,.28); }
        .sp-btn:active { transform: translateY(1px) scale(.98); box-shadow: 0 2px 6px rgba(18,48,31,.25); }
        .sp-btn:focus-visible { outline: 3px solid #f2c14e; outline-offset: 3px; }
        .sp-btn:disabled { background: #cfc8b8; color: #fff; box-shadow: none; cursor: not-allowed; transform: none; }
        .sp-btn.ghost { background: transparent; color: #12301f; border: 1.5px solid #d6caae; box-shadow: none; }
        .sp-btn.ghost:hover { background: #f4ecd9; }
        .sp-btn.quiet { background: transparent; color: #5b6b55; box-shadow: none; padding: 10px 14px; font-weight: 700; }
        .sp-btn.quiet:hover { background: #f1ead8; color: #12301f; transform: none; }
        .sp-btn.gold { background: linear-gradient(180deg, #e9b949, #c9922a); color: #2a1d05; box-shadow: 0 6px 16px rgba(201,146,42,.35); }
        .sp-opt { display: block; width: 100%; text-align: left; border: 1.5px solid #e2d7bd; background: #fff; border-radius: 16px; padding: 12px 16px; cursor: pointer; font-family: 'Plus Jakarta Sans', sans-serif; color: #17301f; transition: border-color .15s, box-shadow .15s, transform .12s; }
        .sp-opt:hover { border-color: #0b6b42; box-shadow: 0 6px 16px rgba(11,107,66,.12); }
        .sp-opt:active { transform: scale(.99); }
        .sp-opt:focus-visible { outline: 3px solid #f2c14e; outline-offset: 2px; }
        .sp-opt[aria-pressed="true"] { border-color: #0b6b42; background: #effaf3; box-shadow: inset 0 0 0 1px #0b6b42; }
        .sp-opt:disabled { opacity: .5; cursor: not-allowed; }
        .sp-kicker { font: 800 12px/1 'Plus Jakarta Sans', sans-serif; letter-spacing: 1.6px; text-transform: uppercase; color: #8a7a55; }
        .sp-tiles { display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; }
        #sop-stage.sop-tall .sp-tiles { grid-template-columns: repeat(2, 1fr); }
        .sp-tile { background: #f8f2e3; border-radius: 14px; padding: 10px 12px; min-width: 0; }
        .sp-tile .l { font: 700 12px/1.2 'Plus Jakarta Sans', sans-serif; color: #7a6c4c; text-transform: uppercase; letter-spacing: .8px; }
        .sp-tile .v { font: 700 22px/1.2 'Fraunces', Georgia, serif; color: #17301f; margin-top: 4px; overflow-wrap: anywhere; }
        .sp-tile.bad .v { color: #b3261e; } .sp-tile.good .v { color: #0b6b42; }
        .sp-ms { display: flex; align-items: flex-start; gap: 0; margin: 6px 0 2px; }
        .sp-ms .s { flex: 1; text-align: center; position: relative; font: 700 11px/1.2 'Plus Jakarta Sans', sans-serif; color: #a39776; padding-top: 22px; min-width: 0; }
        .sp-ms .s::before { content: ""; position: absolute; top: 6px; left: 50%; width: 12px; height: 12px; margin-left: -6px; border-radius: 50%; background: #e3d9c1; z-index: 1; transition: background .4s, box-shadow .4s, transform .4s; }
        .sp-ms .s::after { content: ""; position: absolute; top: 11px; left: -50%; width: 100%; height: 2px; background: #e3d9c1; transition: background .5s .1s; }
        .sp-ms .s:first-child::after { display: none; }
        .sp-ms .s.done { color: #0b6b42; } .sp-ms .s.done::before, .sp-ms .s.done::after, .sp-ms .s.now::after { background: #0b6b42; }
        .sp-ms .s.now { color: #17301f; } .sp-ms .s.now::before { background: #e9b949; box-shadow: 0 0 0 4px rgba(233,185,73,.3); transform: scale(1.25); }
        #sop-stage.sop-tall .sp-ms .s span { display: none; } #sop-stage.sop-tall .sp-ms .s.now span { display: block; white-space: nowrap; }
        .sp-brief > summary { cursor: pointer; list-style: none; font: 800 14px 'Plus Jakarta Sans', sans-serif; color: #0b6b42; padding: 8px 0; }
        .sp-brief > summary::-webkit-details-marker { display: none; }
        .sp-brief > summary::before { content: "▸ "; } .sp-brief[open] > summary::before { content: "▾ "; }
        .sp-adviser { display: grid; grid-template-columns: auto 1fr; gap: 14px; align-items: start; padding: 14px 16px; animation: spAdvIn .45s cubic-bezier(.2,.8,.2,1) both; }
        .sp-adviser .pic { width: 74px; height: 88px; border-radius: 18px; object-fit: cover; object-position: top; background: linear-gradient(180deg, #e8f3ea, #cfe6d6); box-shadow: 0 0 0 3px #fff, 0 0 0 5px #e9b949; }
        .sp-adviser.calm .pic { box-shadow: 0 0 0 3px #fff, 0 0 0 5px #cfe6d6; }
        .sp-adviser .pic.full, .sp-adviser.calm .pic.full { width: 72px; height: 132px; object-fit: contain; object-position: bottom; background: none; box-shadow: none; border-radius: 0; align-self: end; }
        @media (min-width: 900px) { .sp-adviser .pic.full { width: 96px; height: 172px; } }
        .sp-adviser.alert .pic { animation: spRing 1.8s ease-in-out 2; }
        .sp-bubble { position: relative; background: #fff; border: 1px solid #e7dcc4; border-radius: 18px; padding: 10px 14px; font: 600 17px/1.4 'Plus Jakarta Sans', sans-serif; color: #17301f; }
        .sp-bubble::before { content: ""; position: absolute; left: -8px; top: 18px; width: 14px; height: 14px; background: #fff; border-left: 1px solid #e7dcc4; border-bottom: 1px solid #e7dcc4; transform: rotate(45deg); }
        .sp-con { display: flex; gap: 10px; align-items: center; padding: 10px 14px; border-radius: 14px; background: #eef7f0; border-left: 4px solid #0b6b42; font: 600 15px/1.35 'Plus Jakarta Sans', sans-serif; color: #17301f; animation: sopFadeIn .5s ease-out; }
        @keyframes spFadeOut { 0%, 70% { opacity: 1; } 100% { opacity: 0; } }
        @keyframes spAdvIn { from { opacity: 0; transform: translateY(14px); } to { opacity: 1; transform: none; } }
        @keyframes spRing { 0%, 100% { box-shadow: 0 0 0 3px #fff, 0 0 0 5px #e9b949; } 50% { box-shadow: 0 0 0 3px #fff, 0 0 0 10px rgba(233,185,73,.35); } }
        .sp-step { animation: spAdvIn .35s cubic-bezier(.2,.8,.2,1) both; }
        #sop-stage.sop-tall .sp-adviser { gap: 10px; padding: 12px; } #sop-stage.sop-tall .sp-adviser .pic { width: 54px; height: 64px; border-radius: 14px; } #sop-stage.sop-tall .sp-bubble { font-size: 16px; }
        .sp-still .sp-adviser, .sp-still .sp-adviser .pic, .sp-still .sp-con, .sp-still .sp-step, .sp-still .sp-btn, .sp-still .sp-opt, .sp-still .sp-ms .s::before, .sp-still .sp-ms .s::after { animation: none !important; transition: none !important; }
        @media (prefers-reduced-motion: reduce) { .sp-adviser, .sp-adviser .pic, .sp-con, .sp-step, .sp-btn, .sp-opt, .sp-ms .s::before, .sp-ms .s::after { animation: none !important; transition: none !important; } }
        .sop-fade-in { animation: sopFadeIn .4s ease-out; }
        .sop-slide-up { animation: sopSlideUp .35s ease-out; }
        @keyframes sopFadeIn { from { opacity: 0; } to { opacity: 1; } }
        @keyframes sopPop { 0% { transform: scale(.6); opacity: 0; } 70% { transform: scale(1.06); opacity: 1; } 100% { transform: scale(1); } }
        .sop-pop { animation: sopPop .7s ease-out both; }
        @keyframes sopPulse { 0%, 100% { box-shadow: 0 0 0 3px #ffd166, 0 0 0 0 rgba(255,209,102,.7); } 50% { box-shadow: 0 0 0 3px #ffd166, 0 0 0 14px rgba(255,209,102,0); } }
        .sop-next { animation: sopPulse 1.6s ease-in-out infinite; }
        .sop-flash { animation: sopPulse 1s ease-in-out 3; border-radius: 16px; }
        @media (prefers-reduced-motion: reduce) { .sop-pop, .sop-next, .sop-flash { animation: none; } .sop-next, .sop-flash { box-shadow: 0 0 0 3px #ffd166; } }
        .sop-hub-spot { transition: box-shadow .2s, background .2s; }
        .sop-hub-spot:hover, .sop-hub-spot:focus-visible { background: rgba(255,255,255,.14) !important; box-shadow: inset 0 0 0 2px rgba(255,255,255,.85), 0 0 16px rgba(255,255,255,.5) !important; outline: none; }
        @keyframes sopSlideUp { from { opacity: 0; transform: translateY(12px); } to { opacity: 1; transform: translateY(0); } }
      `}</style>
      <HowToPlay show={showHelp} onClose={() => setShowHelp(false)} />
      {scr === "title" && <TitleScreen onPreview={presidencyPreview} onSenate={() => { setFinalStats(null); setScr("senate"); }} onChairman={() => setScr("chairman")} onAmbassador={() => setScr("ambassador")} onChallenge={beginChallenge} onScenario={beginScenario} onBoard={openBoard} onPresident={() => { setFinalStats(null); setScr("pres"); }} profile={profile} setProfile={setProfile} onStart={(p) => { seedRandom(null); try { window.dispatchEvent(new CustomEvent('sop-new-game')); } catch (e) {} setStartProfile(p || null); setStartMode(null); setScr("setup"); }} onHelp={() => setShowHelp(true)} onLoad={loadGame} />}
      {scr === "setup" && <button onClick={async () => { if (await window.SOP_confirm("Leave the campaign?\n\nIt is not saved until you take office: next time you start the campaign again.", "Go to the home screen", "Keep campaigning")) rst(); }} aria-label="Home screen" style={{ position: "fixed", top: "calc(env(safe-area-inset-top, 0px) + 8px)", right: 10, zIndex: 70, background: "rgba(255,255,255,.92)", border: "1px solid " + CL.bdr, borderRadius: 999, padding: "6px 12px", fontFamily: F.b, fontWeight: 800, fontSize: TALL() ? TS(18) : TS(24), color: CL.txt, cursor: "pointer", boxShadow: "0 2px 8px rgba(0,0,0,.08)" }}>🏠 Home</button>}
      {scr === "setup" && <SetupScreen profile={startProfile} mode={startMode} level={level} setLevel={setLevel} onDone={s => { setSetup({ ...s, level, mode: startMode || undefined }); setLoadedSave(null); setScr("gov"); }} />}
      {scr === "title" && board && <EntranceSheet title="🏛️ Hall of Governors" onClose={() => setBoard(null)}>
        <HallBoard tab={board.tab === "all" ? "all" : "today"} />
      </EntranceSheet>}
      {scr === "gov" && <GovScreen setup={setup ? { ...setup, level } : null} loadedSave={loadedSave} onEnd={(ch, stats) => { if (stats) setFinalStats(stats); if (ch === "restart") rst(); else if (ch === "president") setScr("pres"); else if (ch === "senate") setScr("senate"); else if (ch === "comeback") comeback(stats && stats.team); else if (ch === "again") { seedRandom(null); try { window.dispatchEvent(new CustomEvent("sop-new-game")); } catch (e) {} setStartProfile(profile || null); setStartMode(null); setSetup(null); setLoadedSave(null); setScr("setup"); } else if (ch === "fctm") setScr("end_fctm"); else setScr("end_ret"); }} onHelp={() => setShowHelp(true)} />}
      {scr === "pres" && <AsoRock setup={setup ? { ...setup, level } : { level }} stats={finalStats} onExit={rst} onTakeOffice={su => { setSetup(su); setLoadedSave(null); setScr("gov"); }} />}
      {scr === "ambassador" && <AmbassadorCareer profile={profile} onExit={rst} />}
      {scr === "chairman" && <ChairmanCareer profile={profile} onExit={rst} onGovernor={() => { seedRandom(null); try { window.dispatchEvent(new CustomEvent('sop-new-game')); } catch (e) {} setStartProfile(profile || null); setStartMode(null); setScr("setup"); }} />}
      {scr === "senate" && <SenateCareer stats={finalStats} profile={profile} onExit={rst} onPresident={(rec) => { setFinalStats(f => ({ ...(f || {}), rec })); setScr("pres"); }} />}
      {scr === "end_ret" && <EndScr type="retire" state={setup?.state} onRestart={rst} />}
      {scr === "end_sen_w" && <EndScr type="senate_w" state={setup?.state} onRestart={rst} />}
      {scr === "end_sen_l" && <EndScr type="senate_l" state={setup?.state} onRestart={rst} />}
      {scr === "end_pres_w" && <EndScr type="pres_w" state={setup?.state} onRestart={rst} />}
      {scr === "end_pres_l" && <EndScr type="pres_l" state={setup?.state} onRestart={rst} />}
      {scr === "end_fctm" && <EndScr type="fctm" state={setup?.state} onRestart={rst} />}
    </div>
  );
}

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(React.createElement(App));
